type daNonReplayFixture struct {
	t         *testing.T
	signer    *consensus.MLDSA87Keypair
	address   []byte
	state     *ChainState
	mp        *Mempool
	relay     *DARelayState
	outpoints []consensus.Outpoint
	next      int
}
type daNonReplayTxSpec struct {
	kind                          uint8
	daID, commitment              [32]byte
	chunkCount, chunkIndex        uint16
	payload                       []byte
	commitmentOutputs, inputCount int
	commitmentOutputData          [][]byte
	literalCommitmentOutputs      bool
	chunkHash                     [32]byte
	literalChunkHash              bool
	fee                           consensus.Uint128
	extraOutputs                  []consensus.TxOutput
}
type daNonReplayTx struct {
	spec        daNonReplayTxSpec
	raw         []byte
	txid, wtxid [32]byte
	inputs      []consensus.Outpoint
}

func newDANonReplayFixture(t *testing.T, count int) *daNonReplayFixture {
	signer := mustNodeMLDSA87Keypair(t)
	address := consensus.P2PKCovenantDataForPubkey(signer.PubkeyBytes())
	values := slices.Repeat([]uint64{2_000_000}, count)
	state, outpoints := testSpendableChainState(address, values)
	cfg := DefaultMempoolConfig()
	cfg.PolicyMaxDaBytesPerBlock = consensus.MAX_DA_BYTES_PER_BLOCK
	mp, err := NewMempoolWithConfig(state, nil, devnetGenesisChainID, cfg)
	if err != nil {
		t.Fatalf("NewMempoolWithConfig: %v", err)
	}
	caps := defaultDARelayCaps()
	caps.orphanTTLBlocks = 7
	relay, err := newDARelayState(mp, caps)
	if err != nil {
		t.Fatalf("newDARelayState: %v", err)
	}
	return &daNonReplayFixture{t: t, signer: signer, address: address, state: state, mp: mp, relay: relay, outpoints: outpoints}
}

func (f *daNonReplayFixture) signed(spec daNonReplayTxSpec) daNonReplayTx {
	inputCount := max(spec.inputCount, 1)
	if f.next+inputCount > len(f.outpoints) {
		f.t.Fatal("DA non-replay fixture exhausted")
	}
	if spec.fee == (consensus.Uint128{}) {
		spec.fee = consensus.Uint128{Lo: 600_000}
	}
	inputRows := append([]consensus.Outpoint(nil), f.outpoints[f.next:f.next+inputCount]...)
	inputs := make([]consensus.TxInput, inputCount)
	for i, input := range inputRows {
		inputs[i] = consensus.TxInput{PrevTxid: input.Txid, PrevVout: input.Vout, Sequence: uint32(10 + f.next + i)}
	}
	f.next += inputCount
	tx := &consensus.Tx{
		Version: 1, TxKind: spec.kind, TxNonce: uint64(100 + f.next),
		Inputs:  inputs,
		Outputs: []consensus.TxOutput{{Value: uint64(inputCount)*2_000_000 - spec.fee.Lo, CovenantType: consensus.COV_TYPE_P2PK, CovenantData: append([]byte(nil), f.address...)}},
	}
	if spec.kind == 0x01 {
		if spec.literalCommitmentOutputs {
			for _, output := range spec.commitmentOutputData {
				tx.Outputs = append(tx.Outputs, consensus.TxOutput{CovenantType: consensus.COV_TYPE_DA_COMMIT, CovenantData: append([]byte(nil), output...)})
			}
		} else {
			for i := 0; i < spec.commitmentOutputs; i++ {
				tx.Outputs = append([]consensus.TxOutput{{CovenantType: consensus.COV_TYPE_DA_COMMIT, CovenantData: append([]byte(nil), spec.commitment[:]...)}}, tx.Outputs...)
			}
		}
		tx.DaPayload = []byte("RUB-1287 manifest")
		tx.DaCommitCore = &consensus.DaCommitCore{DaID: spec.daID, ChunkCount: spec.chunkCount, BatchNumber: 9}
	} else {
		tx.DaPayload = append([]byte(nil), spec.payload...)
		hash := sha3.Sum256(spec.payload)
		if spec.literalChunkHash {
			hash = spec.chunkHash
		}
		tx.DaChunkCore = &consensus.DaChunkCore{DaID: spec.daID, ChunkIndex: spec.chunkIndex, ChunkHash: hash}
	}
	tx.Outputs = append(tx.Outputs, spec.extraOutputs...)
	if err := consensus.SignTransaction(tx, f.state.Utxos, devnetGenesisChainID, f.signer); err != nil {
		f.t.Fatalf("SignTransaction: %v", err)
	}
	raw := mustMarshalTxForNodeTest(f.t, tx)
	parsed, txid, wtxid, consumed, err := consensus.ParseTx(raw)
	if err != nil || consumed != len(raw) {
		f.t.Fatalf("ParseTx=(%d,%v), want %d,nil", consumed, err, len(raw))
	}
	if spec.literalChunkHash && sha3.Sum256(parsed.DaPayload) == parsed.DaChunkCore.ChunkHash {
		f.t.Fatal("serialized chunk hash unexpectedly matches payload")
	}
	return daNonReplayTx{spec: spec, raw: raw, txid: txid, wtxid: wtxid, inputs: inputRows}
}

func (f *daNonReplayFixture) begin(tx daNonReplayTx) *DAAdmission {
	return mustDAAdmission(f.t, f.mp, tx.raw)
}

func (f *daNonReplayFixture) admit(tx daNonReplayTx, provenance daProvenance) daRelayAdmissionOutcome {
	admission := f.begin(tx)
	defer admission.Close()
	outcome, err := f.relay.admitDANonReplay(admission, provenance)
	if err != nil {
		f.t.Fatalf("admitDANonReplay: %v", err)
	}
	if outcome.daID != tx.spec.daID || outcome.disposition != daRelayAdmissionDisposition(1) || outcome.sameDAIDCommitConflict {
		f.t.Fatalf("outcome=%+v, want retained da_id=%x", outcome, tx.spec.daID)
	}
	return outcome
}

func (f *daNonReplayFixture) completeReplay(daID [32]byte, kind uint8, payload ...byte) daNonReplayTx {
	if len(payload) == 0 {
		payload = []byte("complete")
	}
	chunk := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: payload})
	f.admit(chunk, daNonReplayPeer("chunk"))
	commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: sha3.Sum256(chunk.spec.payload), commitmentOutputs: 1})
	_, token := mustFinalizeDAAdmission(f.t, f.mp, commit.raw)
	f.mutateRelay(func(s *DARelayState) {
		record := s.sets[daID]
		record.commit = daRelayCommit{daID: daID, payloadCommitment: commit.spec.commitment, member: &daRelayMemberIdentity{txid: commit.txid, wtxid: commit.wtxid, fee: commit.spec.fee, inputs: append([]consensus.Outpoint(nil), commit.inputs...), token: token, provenance: daNonReplayPeer("commit")}, chunkCount: 1, txBytes: append([]byte(nil), commit.raw...)}
		record.wireBytes = uint64(len(chunk.raw) + len(commit.raw))
		record.markComplete(uint64(len(chunk.spec.payload)))
		s.locators[commit.txid] = daRelayLocator{daID: daID, kind: daRelayLocatorCommit}
		s.sets[daID] = record
	})
	if kind != 0x01 {
		return chunk
	}
	return commit
}

// completeReplayPinned builds a LEGACY State C (COMPLETE_SET) record whose image is otherwise
// closed, so that only the candidate walk's State C refusal can refuse it. completeReplay admits
// its chunk through the real orphan-accounting path but then overwrites the record to complete
// without migrating that accounting: it leaves the chunk's orphan footprint in the pool and never
// pins the payload. A real completed set holds NO orphan footprint (its bytes moved to the pinned
// pool), so this repairs the image to that invariant (R4). The chunk is admitted as peer "chunk",
// which is its only orphan footprint. No owner-ready writer produces this record.
func (f *daNonReplayFixture) completeReplayPinned(daID [32]byte) {
	f.completeReplay(daID, 0x02)
	f.mutateRelay(func(s *DARelayState) {
		record := s.sets[daID]
		charge := s.orphanBytesByDAID[daID]
		delete(s.orphanBytesByDAID, daID)
		s.orphanBytes -= charge
		if s.orphanBytesByPeerQuotaKey["chunk"] -= charge; s.orphanBytesByPeerQuotaKey["chunk"] == 0 {
			delete(s.orphanBytesByPeerQuotaKey, "chunk")
		}
		s.pinnedPayloadBytes += record.payloadBytes
	})
}
func daNonReplayPeer(key string) daProvenance { return daProvenance{daProvenanceKind(1), key, key} }
func (f *daNonReplayFixture) requireMember(t *testing.T, record daRelaySetRecord, tx daNonReplayTx, tokenSequence uint64, provenance daProvenance) {
	var member *daRelayMemberIdentity
	var raw, payload []byte
	if tx.spec.kind == 0x01 {
		member, raw = record.commit.member, record.commit.txBytes
		if record.commit.payloadCommitment != tx.spec.commitment || record.commit.chunkCount != tx.spec.chunkCount {
			t.Fatalf("commit metadata=(%x,%d), want (%x,%d)", record.commit.payloadCommitment, record.commit.chunkCount, tx.spec.commitment, tx.spec.chunkCount)
		}
	} else {
		chunk, ok := record.chunks[tx.spec.chunkIndex]
		if !ok {
			t.Fatalf("chunk %d missing", tx.spec.chunkIndex)
		}
		member, raw, payload = chunk.member, chunk.txBytes, chunk.payload
		if chunk.chunkHash != sha3.Sum256(tx.spec.payload) || chunk.chunkIndex != tx.spec.chunkIndex {
			t.Fatalf("chunk metadata=(%x,%d), want (%x,%d)", chunk.chunkHash, chunk.chunkIndex, sha3.Sum256(tx.spec.payload), tx.spec.chunkIndex)
		}
	}
	wantToken := PendingOutpointToken{owner: f.mp.pendingOutpoints, seq: tokenSequence}
	if member == nil || member.txid != tx.txid || member.wtxid != tx.wtxid || member.fee != tx.spec.fee || member.token != wantToken || member.provenance != provenance || !slices.Equal(member.inputs, tx.inputs) || !bytes.Equal(raw, tx.raw) || !bytes.Equal(payload, tx.spec.payload) {
		t.Fatalf("member mismatch: member=%+v raw=%v payload=%v token=%+v", member, bytes.Equal(raw, tx.raw), bytes.Equal(payload, tx.spec.payload), wantToken)
	}
}

func requireDANonReplayUnchanged(t *testing.T, relay *DARelayState, owner *PendingOutpointOwner, relayBefore daRelayStateView, ownerBefore *PendingOutpointOwner) {
	// A leaked owner lock fails here by name instead of deadlocking the clone.
	if !owner.mu.TryLock() {
		t.Fatal("owner mutex leaked")
	}
	owner.mu.Unlock()
	if got := daRelayStateSnapshot(relay); !reflect.DeepEqual(got, relayBefore) { //nolint:govet // Complete private state-image equality requires structural comparison, error identities included.
		t.Fatalf("relay mutated: got=%+v want=%+v", got, relayBefore)
	}
	if got := cloneDAAdmissionOwner(owner); !reflect.DeepEqual(got, ownerBefore) {
		t.Fatalf("owner mutated: got=%+v want=%+v", got, ownerBefore)
	}
}

func requireDANonReplayRejected(t *testing.T, f *daNonReplayFixture, tx daNonReplayTx, provenance daProvenance, want error) {
	admission := f.begin(tx)
	defer admission.Close()
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	outcome, err := f.relay.admitDANonReplay(admission, provenance)
	if outcome != (daRelayAdmissionOutcome{}) || err != want || !errors.Is(err, want) { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
		t.Fatalf("rejection outcome=%+v err=%v want=%v", outcome, err, want)
	}
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
}

func requireDANonReplayClaim(t *testing.T, snapshot, tokenOwner *PendingOutpointOwner, tx daNonReplayTx, sequence uint64) {
	token := PendingOutpointToken{owner: tokenOwner, seq: sequence}
	claim := snapshot.byToken[token]
	if claim == nil || !claim.finalized || !slices.Equal(claim.inputs, tx.inputs) {
		t.Fatalf("claim tx=%x token=%+v claim=%+v", tx.txid, token, claim)
	}
	for _, input := range tx.inputs {
		if snapshot.byOutpoint[input] != (pendingOutpointRow{token: token, txid: tx.txid}) {
			t.Fatalf("input row=%+v token=%+v", input, token)
		}
	}
}

func requireDANonReplayRecordHeader(t *testing.T, relay *DARelayState, daID [32]byte, state daRelaySetState, revision, received, ttl uint64) daRelaySetRecord {
	view := daRelayStateSnapshot(relay)
	record, ok := view.sets[daID]
	if !ok || record.daID != daID || record.state != state || record.revision != revision || record.receivedTime != received || record.ttlBlocksRemaining != ttl || view.records != revision || view.nextReceivedTime != revision {
		t.Fatalf("record header=%+v present=%v high-water=(%d,%d), want state=%d revision=%d received=%d ttl=%d", record, ok, view.records, view.nextReceivedTime, state, revision, received, ttl)
	}
	return record
}

func (f *daNonReplayFixture) requireSingleRetained(t *testing.T, tx daNonReplayTx, state daRelaySetState) {
	record := requireDANonReplayRecordHeader(t, f.relay, tx.spec.daID, state, 1, 1, 7)
	f.requireMember(t, record, tx, 1, daNonReplayPeer("boundary"))
	kind, charge := daRelayLocatorKind(2), uint64(len(tx.raw)+len(tx.spec.payload))
	if tx.spec.kind == 0x01 {
		kind, charge = daRelayLocatorKind(1), uint64(len(tx.raw))
	}
	view := daRelayStateSnapshot(f.relay)
	locator := daRelayLocator{daID: tx.spec.daID, kind: kind, chunkIndex: tx.spec.chunkIndex}
	if len(view.sets) != 1 || len(view.locators) != 1 || view.locators[tx.txid] != locator || view.orphanBytes != charge || view.daIDBytes[tx.spec.daID] != charge || view.commitBytes != map[bool]uint64{true: charge}[kind == daRelayLocatorKind(1)] || len(view.peerBytes) != 1 || view.peerBytes["boundary"] != charge {
		t.Fatalf("single image locator=%+v counters=(%d,%d,%d,%+v)", view.locators, view.orphanBytes, view.daIDBytes[tx.spec.daID], view.commitBytes, view.peerBytes)
	}
	owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, tx, 1)
	if owner.tokenHighWater != 1 || len(owner.byToken) != 1 || len(owner.byOutpoint) != len(tx.inputs) {
		t.Fatalf("single owner=%+v", owner)
	}
}

func TestAdmitDANonReplayStateMatrix(t *testing.T) {
	for _, row := range []struct {
		name  string
		spec  daNonReplayTxSpec
		state daRelaySetState
	}{
		{"A1 chunk index zero payload one", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x11}, payload: []byte{0x5a}}, daRelaySetState(0)},
		{"A1 chunk maximum index and payload", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x12}, chunkIndex: uint16(consensus.MAX_DA_CHUNK_COUNT - 1), payload: bytes.Repeat([]byte{0xa5}, consensus.CHUNK_BYTES)}, daRelaySetState(0)},
		{"A2 commit count one", daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x13}, chunkCount: 1, commitment: [32]byte{0x61}, commitmentOutputs: 1}, daRelaySetState(1)},
		{"A2 commit maximum count", daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x14}, chunkCount: uint16(consensus.MAX_DA_CHUNK_COUNT), commitment: [32]byte{0x62}, commitmentOutputs: 1}, daRelaySetState(1)},
	} {
		t.Run(row.name, func(t *testing.T) {
			f := newDANonReplayFixture(t, max(row.spec.inputCount, 1))
			tx := f.signed(row.spec)
			f.admit(tx, daNonReplayPeer("boundary"))
			f.requireSingleRetained(t, tx, row.state)
		})
	}
	for _, row := range []struct {
		name                string
		first, second       daNonReplayTxSpec
		firstFrom, nextFrom daProvenance
		state               daRelaySetState
		chunks              int
	}{
		{"A3 state A missing chunk", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x15}, chunkIndex: 2, payload: []byte("a3-first")}, daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x15}, payload: []byte("a3-second")}, daNonReplayPeer("peer-a"), daProvenance{kind: daProvenanceKind(3)}, daRelaySetState(0), 2},
		{"A5 state B missing chunk", daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x17}, chunkCount: 3, commitment: sha3.Sum256([]byte("a5")), commitmentOutputs: 1}, daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x17}, chunkIndex: 1, payload: []byte("a5")}, daNonReplayPeer("peer-a"), daNonReplayPeer("peer-b"), daRelaySetState(1), 1},
	} {
		t.Run(row.name, func(t *testing.T) {
			f := newDANonReplayFixture(t, 2)
			first, second := f.signed(row.first), f.signed(row.second)
			f.admit(first, row.firstFrom)
			f.relay.mu.Lock()
			live := f.relay.sets[row.first.daID]
			live.ttlBlocksRemaining = 2
			f.relay.sets[row.first.daID] = live
			f.relay.mu.Unlock()
			f.admit(second, row.nextFrom)
			record := requireDANonReplayRecordHeader(t, f.relay, row.first.daID, row.state, 2, 1, 2)
			if len(record.chunks) != row.chunks {
				t.Fatalf("chunks=%d, want %d", len(record.chunks), row.chunks)
			}
			f.requireMember(t, record, first, 1, row.firstFrom)
			f.requireMember(t, record, second, 2, row.nextFrom)
		})
	}
	f, daID := newDANonReplayFixture(t, 2), [32]byte{0x18}
	f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: [32]byte{0x18}, commitmentOutputs: 1}), daNonReplayPeer("commit"))
	outside := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("outside")})
	requireDANonReplayRejected(t, f, outside, daNonReplayPeer("outside"), errDARelayChunkIndexOutsideCommit)
}

func requireDANonReplayCompletionRefusal(t *testing.T, f *daNonReplayFixture, tx daNonReplayTx) {
	admission := f.begin(tx)
	defer admission.Close()
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	outcome, err := f.relay.admitDANonReplay(admission, daNonReplayPeer("candidate"))
	var admitErr *TxAdmitError
	if outcome != (daRelayAdmissionOutcome{}) || !errors.As(err, &admitErr) || admitErr.Kind != TxAdmitErrorKind("unavailable") || admitErr.Message != "DA COMPLETE_SET capacity owner is not active" || relayDispositionOf(err) != RelayAdmissionDisposition(9) {
		t.Fatalf("completion refusal outcome=%+v err=%v disposition=%d", outcome, err, relayDispositionOf(err))
	}
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
}

func TestAdmitDANonReplayWouldCompleteIsUnavailable(t *testing.T) {
	for _, match := range []bool{true, false} {
		t.Run("commit last match="+map[bool]string{true: "yes", false: "no"}[match], func(t *testing.T) {
			f := newDANonReplayFixture(t, 3)
			daID, payload := [32]byte{0x21, byte(len(map[bool]string{true: "x", false: "yy"}[match]))}, []byte("complete")
			commitment := [32]byte{0xff}
			if match {
				commitment = sha3.Sum256(payload)
			}
			f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 0, payload: payload}), daNonReplayPeer("peer-a"))
			f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 2, payload: []byte("must-not-prune")}), daNonReplayPeer("peer-b"))
			requireDANonReplayCompletionRefusal(t, f, f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: commitment, commitmentOutputs: 1}))
		})
		t.Run("chunk last match="+map[bool]string{true: "yes", false: "no"}[match], func(t *testing.T) {
			f := newDANonReplayFixture(t, 2)
			daID, payload := [32]byte{0x22, byte(len(map[bool]string{true: "x", false: "yy"}[match]))}, []byte("complete")
			commitment := [32]byte{0xff}
			if match {
				commitment = sha3.Sum256(payload)
			}
			f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: commitment, commitmentOutputs: 1}), daNonReplayPeer("peer-a"))
			requireDANonReplayCompletionRefusal(t, f, f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 0, payload: payload}))
		})
	}
}

type daNonReplayPlanned struct {
	admission *DAAdmission
	candidate daRelayAdmissionCandidate
	plan      daRelayAdmissionPlan
}

func (f *daNonReplayFixture) planned(tx daNonReplayTx, provenance daProvenance) daNonReplayPlanned {
	admission := f.begin(tx)
	candidate, err := admission.renderDARelayAdmissionCandidate(provenance)
	if err != nil {
		f.t.Fatalf("render: %v", err)
	}
	return daNonReplayPlanned{admission: admission, candidate: candidate, plan: f.relay.planDANonReplay(candidate)}
}

func (f *daNonReplayFixture) mutateRelay(mutate func(*DARelayState)) {
	f.relay.mu.Lock()
	defer f.relay.mu.Unlock()
	mutate(f.relay)
}

func requireDANonReplayPlanResult(t *testing.T, f *daNonReplayFixture, planned daNonReplayPlanned, want daRelayAdmissionOutcome, wantErr error, message string) {
	defer planned.admission.Close()
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	outcome, err := f.relay.applyDANonReplayPlan(planned.admission, planned.candidate, planned.plan)
	if outcome != want {
		t.Fatalf("outcome=%+v, want %+v", outcome, want)
	}
	if message != "" {
		var admitErr *TxAdmitError
		if !errors.As(err, &admitErr) || admitErr.Kind != TxAdmitErrorKind("unavailable") || admitErr.Message != message || relayDispositionOf(err) != RelayAdmissionDisposition(9) {
			t.Fatalf("error=%v disposition=%d, want unavailable %q", err, relayDispositionOf(err), message)
		}
	} else if wantErr != nil {
		if err != wantErr || !errors.Is(err, wantErr) { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
			t.Fatalf("error=%v, want %v", err, wantErr)
		}
	} else if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
}

func TestAdmitDANonReplayFinalRecheckOrder(t *testing.T) {
	for _, different := range []bool{false, true} {
		t.Run(map[bool]string{false: "same txid", true: "different commit"}[different]+" duplicate outranks stale", func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 2), [32]byte{0x31, byte(map[bool]int{true: 1}[different])}
			spec := daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: sha3.Sum256([]byte("duplicate")), commitmentOutputs: 1}
			tx := f.signed(spec)
			planned := f.planned(tx, daNonReplayPeer("planned"))
			if planned.plan.stageErr != nil {
				t.Fatalf("ABSENT plan stage error=%v", planned.plan.stageErr)
			}
			if different {
				tx = f.signed(spec)
			}
			f.admit(tx, daNonReplayPeer("winner"))
			requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(2), sameDAIDCommitConflict: different}, nil, "")
		})
	}
	for _, row := range []struct {
		name           string
		winner, loser  daNonReplayTxSpec
		commitConflict bool
	}{
		{"occupied commit beats carried stage error", daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x32}, chunkCount: 3, commitment: [32]byte{2}, commitmentOutputs: 1}, daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x32}, chunkCount: 2, commitment: [32]byte{1}, commitmentOutputs: 1}, true},
		{"occupied chunk conflict bit stays false", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x33}, chunkIndex: 4, payload: []byte("winner")}, daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x33}, chunkIndex: 4, payload: []byte("loser")}, false},
	} {
		t.Run(row.name, func(t *testing.T) {
			f := newDANonReplayFixture(t, 2)
			winner, loser := f.signed(row.winner), f.signed(row.loser)
			f.admit(winner, daNonReplayPeer("winner"))
			planned := f.planned(loser, daNonReplayPeer("loser"))
			if planned.plan.stageErr == nil {
				t.Fatal("occupied slot did not carry a stage error")
			}
			want := daRelayAdmissionOutcome{daID: row.winner.daID, disposition: daRelayAdmissionDisposition(2), sameDAIDCommitConflict: row.commitConflict}
			requireDANonReplayPlanResult(t, f, planned, want, nil, "")
		})
	}
	t.Run("duplicate beats carried completion", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x34}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: [32]byte{4}, commitmentOutputs: 1}), daNonReplayPeer("commit"))
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("last")})
		planned := f.planned(tx, daNonReplayPeer("last"))
		if !planned.plan.wouldComplete {
			t.Fatal("completion plan was not staged")
		}
		f.mutateRelay(func(r *DARelayState) { r.locators[tx.txid] = planned.candidate.member.locator })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(2)}, nil, "")
	})
	t.Run("duplicate beats live cap projection", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x35}, payload: []byte("cap")})
		p := f.planned(tx, daNonReplayPeer("cap"))
		f.mutateRelay(func(r *DARelayState) { r.caps.orphanPoolBytes = 1; r.locators[tx.txid] = p.candidate.member.locator })
		requireDANonReplayPlanResult(t, f, p, daRelayAdmissionOutcome{daID: tx.spec.daID, disposition: daRelayAdmissionDisposition(2)}, nil, "")
	})
	t.Run("stale beats carried completion", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x36}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: [32]byte{6}, commitmentOutputs: 1}), daNonReplayPeer("commit"))
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("last")}), daNonReplayPeer("last"))
		f.mutateRelay(func(r *DARelayState) { v := r.sets[daID]; v.revision++; r.records++; r.sets[daID] = v })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, nil, "retained DA record moved while this admission was planned")
	})
	for _, field := range []string{"received time", "revision", "pruned token", "pruned input", "preserved txid", "preserved wtxid", "preserved full fee", "preserved provenance", "preserved token", "preserved input", "preserved chunk hash", "preserved peer quota", "preserved hash checked", "preserved payload", "preserved tx bytes", "commit payload commitment", "commit peer quota", "commit chunk count", "commit tx bytes", "commit member token"} {
		t.Run(field+" high-water incoherence", func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 3), [32]byte{0x37, byte(len(field))}
			complete := field == "preserved full fee"
			var victim daNonReplayTx
			var planned daNonReplayPlanned
			if strings.HasPrefix(field, "commit ") {
				f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 3, commitment: [32]byte{0x37}, commitmentOutputs: 1}), daNonReplayPeer("preserved"))
				planned = f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("next")}), daNonReplayPeer("next"))
			} else {
				preserved := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("preserved")})
				victim = f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("victim")})
				f.admit(preserved, daNonReplayPeer("preserved"))
				f.admit(victim, daNonReplayPeer("victim"))
				planned = f.planned(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: map[bool]uint16{false: 2, true: 1}[complete], commitment: [32]byte{0x37}, commitmentOutputs: 1}), daNonReplayPeer("next"))
			}
			if planned.plan.wouldComplete != complete {
				t.Fatalf("wouldComplete=%t, want %t", planned.plan.wouldComplete, complete)
			}
			f.relay.mu.Lock()
			record := f.relay.sets[daID]
			chunk := record.chunks[0]
			map[string]func(){
				"received time":             func() { f.relay.nextReceivedTime = 0 },
				"revision":                  func() { f.relay.records = 0 },
				"pruned token":              func() { record.chunks[3].member.token.seq++; delete(f.relay.locators, victim.txid) },
				"pruned input":              func() { record.chunks[3].member.inputs[0].Vout++ },
				"preserved txid":            func() { chunk.member.txid[0] ^= 1 },
				"preserved wtxid":           func() { chunk.member.wtxid[0] ^= 1 },
				"preserved full fee":        func() { chunk.member.fee.Hi++ },
				"preserved provenance":      func() { chunk.member.provenance = daProvenance{kind: daProvenanceKind(2)} },
				"preserved token":           func() { chunk.member.token.seq++ },
				"preserved input":           func() { chunk.member.inputs[0].Vout++ },
				"preserved chunk hash":      func() { chunk.chunkHash[0] ^= 1 },
				"preserved peer quota":      func() { chunk.peerQuotaKey = "moved" },
				"preserved hash checked":    func() { chunk.hashChecked = !chunk.hashChecked },
				"preserved payload":         func() { chunk.payload[0] ^= 1 },
				"preserved tx bytes":        func() { chunk.txBytes[0] ^= 1 },
				"commit payload commitment": func() { record.commit.payloadCommitment[0] ^= 1 },
				"commit peer quota":         func() { record.commit.peerQuotaKey = "moved" },
				"commit chunk count":        func() { record.commit.chunkCount = 2 },
				"commit tx bytes":           func() { record.commit.txBytes[0] ^= 1 },
				"commit member token":       func() { record.commit.member.token.seq++ },
			}[field]()
			if !strings.HasPrefix(field, "commit ") {
				record.chunks[0] = chunk
			}
			f.relay.sets[daID] = record
			f.relay.mu.Unlock()
			requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, errDARelayImageIncompatible, "")
		})
	}
	t.Run("duplicate beats target high-water incoherence", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x38}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("seed")}), daNonReplayPeer("seed"))
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("duplicate")})
		p := f.planned(tx, daNonReplayPeer("duplicate"))
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = 0; r.locators[tx.txid] = p.candidate.member.locator })
		requireDANonReplayPlanResult(t, f, p, daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(2)}, nil, "")
	})
	t.Run("stale beats carried stage error", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 4), [32]byte{0x39}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("survivor")}), daNonReplayPeer("survivor"))
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("occupied")}), daNonReplayPeer("occupied"))
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("candidate")}), daNonReplayPeer("candidate"))
		if planned.plan.stageErr == nil {
			t.Fatal("occupied slot did not carry stage error")
		}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0x39}, commitmentOutputs: 1}), daNonReplayPeer("commit"))
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, nil, "retained DA record moved while this admission was planned")
	})
	t.Run("stale beats high-water incoherence", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 3), [32]byte{0x3a}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("seed")}), daNonReplayPeer("seed"))
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 2, payload: []byte("candidate")}), daNonReplayPeer("candidate"))
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("mover")}), daNonReplayPeer("mover"))
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = 0 })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, nil, "retained DA record moved while this admission was planned")
	})
	t.Run("stage error beats high-water incoherence", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x3b}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("seed")}), daNonReplayPeer("seed"))
		f.relay.mu.Lock()
		record := f.relay.sets[daID]
		chunk := record.chunks[0]
		chunk.member.provenance = daProvenance{}
		record.chunks[0] = chunk
		f.relay.sets[daID] = record
		f.relay.nextReceivedTime = 0
		f.relay.mu.Unlock()
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("candidate")}), daNonReplayPeer("candidate"))
		if planned.plan.stageErr != errDAProvenanceInvalid { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
			t.Fatalf("stage error=%v", planned.plan.stageErr)
		}
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, errDAProvenanceInvalid, "")
	})
	t.Run("would complete beats high-water incoherence", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x3c}
		commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 1, commitment: [32]byte{0x3c}, commitmentOutputs: 1})
		f.admit(commit, daNonReplayPeer("commit"))
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("last")}), daNonReplayPeer("last"))
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = 0; delete(r.locators, commit.txid) })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, nil, "DA COMPLETE_SET capacity owner is not active")
	})
	t.Run("high-water incompatibility beats live cap", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x3d}
		f.admit(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("seed")}), daNonReplayPeer("seed"))
		planned := f.planned(f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("candidate")}), daNonReplayPeer("candidate"))
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = 0; r.caps.orphanPoolBytes = 1 })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, errDARelayImageIncompatible, "")
	})
	t.Run("sequence exhaustion beats live cap", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x3e}, payload: []byte("candidate")})
		planned := f.planned(tx, daNonReplayPeer("candidate"))
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = ^uint64(0); r.caps.orphanPoolBytes = 1 })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, errDARelayArithmeticOverflow, "")
	})
	t.Run("live cap beats owner conflict", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x3f}, payload: []byte("candidate")})
		planned := f.planned(tx, daNonReplayPeer("candidate"))
		context, ok := f.mp.pendingOutpoints.AdmissionContext()
		if !ok {
			t.Fatal("owner context unavailable")
		}
		blocker, err := f.mp.pendingOutpoints.Reserve(context, PendingOutpointDomain(1), [32]byte{0xee}, []consensus.Outpoint{tx.inputs[0]})
		if err != nil || f.mp.pendingOutpoints.Finalize(blocker) != nil {
			t.Fatalf("blocker reserve/finalize: %v", err)
		}
		f.mutateRelay(func(r *DARelayState) { r.caps.orphanPoolBytes = 1 })
		requireDANonReplayPlanResult(t, f, planned, daRelayAdmissionOutcome{}, errDARelayOrphanPoolCapExceeded, "")
	})
	t.Run("unrelated movement reprojects live values", func(t *testing.T) {
		f := newDANonReplayFixture(t, 3)
		targetID, otherID := [32]byte{0x40}, [32]byte{0x41}
		seed := f.signed(daNonReplayTxSpec{kind: 0x02, daID: targetID, payload: []byte("seed")})
		f.admit(seed, daNonReplayPeer("seed"))
		target := f.signed(daNonReplayTxSpec{kind: 0x02, daID: targetID, chunkIndex: 2, payload: []byte("target")})
		planned := f.planned(target, daNonReplayPeer("target"))
		defer planned.admission.Close()
		other := f.signed(daNonReplayTxSpec{kind: 0x01, daID: otherID, chunkCount: 2, commitment: [32]byte{0x41}, commitmentOutputs: 1})
		f.admit(other, daNonReplayPeer("other"))
		otherToken := PendingOutpointToken{owner: f.mp.pendingOutpoints, seq: 2}
		otherRecord, otherClaim := daRelayStateSnapshot(f.relay).sets[otherID], cloneDAAdmissionOwner(f.mp.pendingOutpoints).byToken[otherToken]
		outcome, err := f.relay.applyDANonReplayPlan(planned.admission, planned.candidate, planned.plan)
		view := daRelayStateSnapshot(f.relay)
		seedCharge, targetCharge, otherCharge := uint64(len(seed.raw)+len(seed.spec.payload)), uint64(len(target.raw)+len(target.spec.payload)), uint64(len(other.raw))
		if err != nil || outcome != (daRelayAdmissionOutcome{daID: targetID, disposition: daRelayAdmissionDisposition(1)}) || len(view.sets) != 2 || view.nextReceivedTime != 3 || view.records != 3 || view.orphanBytes != seedCharge+targetCharge+otherCharge || view.commitBytes != otherCharge || view.daIDBytes[targetID] != seedCharge+targetCharge || view.daIDBytes[otherID] != otherCharge || len(view.daIDBytes) != 2 || view.peerBytes["seed"] != seedCharge || view.peerBytes["target"] != targetCharge || view.peerBytes["other"] != otherCharge || len(view.peerBytes) != 3 || view.locators[seed.txid] != (daRelayLocator{daID: targetID, kind: daRelayLocatorKind(2)}) || view.locators[target.txid] != (daRelayLocator{daID: targetID, kind: daRelayLocatorKind(2), chunkIndex: 2}) || view.locators[other.txid] != (daRelayLocator{daID: otherID, kind: daRelayLocatorKind(1)}) || len(view.locators) != 3 {
			t.Fatalf("cross-record outcome=%+v err=%v view=%+v", outcome, err, view)
		}
		if a, b := view.sets[targetID], view.sets[otherID]; a.revision != 3 || a.receivedTime != 1 || a.state != daRelayStateOrphanChunks || b.revision != 2 || b.receivedTime != 2 || b.state != daRelayStateStagedCommit {
			t.Fatalf("cross-record headers target=%+v other=%+v", a, b)
		}
		f.requireMember(t, view.sets[targetID], seed, 1, daNonReplayPeer("seed"))
		f.requireMember(t, view.sets[targetID], target, 3, daNonReplayPeer("target"))
		f.requireMember(t, view.sets[otherID], other, 2, daNonReplayPeer("other"))
		owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, seed, 1)
		requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, other, 2)
		requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, target, 3)
		if !reflect.DeepEqual(view.sets[otherID], otherRecord) || !reflect.DeepEqual(owner.byToken[otherToken], otherClaim) {
			t.Fatalf("unrelated record/claim moved: record=%+v claim=%+v", view.sets[otherID], owner.byToken[otherToken])
		}
		if owner.tokenHighWater != 3 || len(owner.byToken) != 3 || len(owner.byOutpoint) != 3 {
			t.Fatalf("cross-record owner=%+v", owner)
		}
	})
}

func TestAdmitDANonReplayOwnerAtomicity(t *testing.T) {
	t.Run("one concurrent winner", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x41}
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 4, payload: []byte("one-winner"), inputCount: 2})
		admissions := [2]*DAAdmission{f.begin(tx), f.begin(tx)}
		type result struct {
			outcome daRelayAdmissionOutcome
			err     error
		}
		results := make(chan result, 2)
		for _, admission := range admissions {
			go func(a *DAAdmission) {
				defer a.Close()
				outcome, err := f.relay.admitDANonReplay(a, daNonReplayPeer("peer"))
				results <- result{outcome: outcome, err: err}
			}(admission)
		}
		retained, duplicate := 0, 0
		for range admissions {
			got := <-results
			if got.err != nil {
				t.Fatalf("concurrent admission: %v", got.err)
			}
			switch got.outcome.disposition {
			case daRelayAdmissionDisposition(1):
				retained++
			case daRelayAdmissionDisposition(2):
				duplicate++
			default:
				t.Fatalf("disposition=%d", got.outcome.disposition)
			}
		}
		if retained != 1 || duplicate != 1 {
			t.Fatalf("retained=%d duplicate=%d", retained, duplicate)
		}
		f.relay.mu.Lock()
		f.mp.pendingOutpoints.mu.Lock()
		record := f.relay.sets[daID]
		member := record.chunks[4].member
		locator, located := f.relay.locators[tx.txid]
		charge := uint64(len(tx.raw) + len(tx.spec.payload))
		if member == nil || member.token != (PendingOutpointToken{owner: f.mp.pendingOutpoints, seq: 1}) || !slices.Equal(member.inputs, tx.inputs) || !located || locator != (daRelayLocator{daID: daID, kind: daRelayLocatorKind(2), chunkIndex: 4}) || f.relay.nextReceivedTime != 1 || f.relay.records != 1 || f.relay.orphanBytes != charge || f.relay.orphanBytesByDAID[daID] != charge || f.relay.orphanBytesByPeerQuotaKey["peer"] != charge || len(f.mp.pendingOutpoints.byToken) != 1 || len(f.mp.pendingOutpoints.byOutpoint) != 2 {
			t.Fatalf("atomic image member=%+v locator=%+v counters=(%d,%d,%d)", member, locator, f.relay.nextReceivedTime, f.relay.records, f.relay.orphanBytes)
		}
		requireDANonReplayClaim(t, f.mp.pendingOutpoints, f.mp.pendingOutpoints, tx, 1)
		f.mp.pendingOutpoints.mu.Unlock()
		f.relay.mu.Unlock()
	})
	for _, row := range []struct {
		name, cap               string
		conflict, accept, chunk bool
	}{{"global equal", "global", false, true, false}, {"commit equal", "commit", false, true, false}, {"da cap ignored", "da", false, true, false}, {"peer cap ignored", "peer", false, true, false}, {"global abort", "global", false, false, false}, {"commit abort", "commit", false, false, false}, {"owner before global", "global", true, false, false}, {"owner before commit", "commit", true, false, false}, {"chunk global abort", "global", false, false, true}, {"chunk commit abort", "commit", false, false, true}, {"chunk owner before global", "global", true, false, true}, {"chunk State-A caps ignored", "state-a", false, true, true}} {
		t.Run("state B "+row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 2), [32]byte{0x46, byte(len(row.name))}
			seed := f.signed(map[bool]daNonReplayTxSpec{false: {kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("victim")}, true: {kind: 0x01, daID: daID, chunkCount: 3, commitment: [32]byte{0x46}, commitmentOutputs: 1}}[row.chunk])
			f.admit(seed, daNonReplayPeer("victim"))
			candidate := f.signed(map[bool]daNonReplayTxSpec{false: {kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0x46}, commitmentOutputs: 1}, true: {kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("chunk")}}[row.chunk])
			view, candidateCharge := daRelayStateSnapshot(f.relay), uint64(len(candidate.raw)+len(candidate.spec.payload))
			globalCharge, commitCharge := map[bool]uint64{false: uint64(len(candidate.raw)), true: view.orphanBytes + candidateCharge}[row.chunk], map[bool]uint64{false: uint64(len(candidate.raw)), true: view.commitBytes}[row.chunk]
			f.relay.mu.Lock()
			f.relay.caps.orphanPoolBytes, f.relay.caps.orphanCommitOverheadBytes = ^uint64(0), ^uint64(0)
			cap := map[string]*uint64{"global": &f.relay.caps.orphanPoolBytes, "commit": &f.relay.caps.orphanCommitOverheadBytes, "da": &f.relay.caps.orphanPoolPerDAIDBytes, "peer": &f.relay.caps.orphanPoolPerPeerBytes, "state-a": &f.relay.caps.orphanPoolPerDAIDBytes}[row.cap]
			*cap = map[string]uint64{"global": globalCharge, "commit": commitCharge, "da": globalCharge, "peer": globalCharge, "state-a": 1}[row.cap]
			if !row.accept || row.cap == "da" || row.cap == "peer" {
				*cap--
			}
			if row.cap == "state-a" {
				f.relay.caps.orphanPoolPerPeerBytes = *cap
			}
			f.relay.mu.Unlock()
			admission := f.begin(candidate)
			defer admission.Close()
			if row.conflict {
				context, _ := f.mp.pendingOutpoints.AdmissionContext()
				blocker, err := f.mp.pendingOutpoints.Reserve(context, PendingOutpointDomain(1), [32]byte{0xee}, candidate.inputs)
				if err != nil || f.mp.pendingOutpoints.Finalize(blocker) != nil {
					t.Fatalf("blocker: %v", err)
				}
			}
			relayBefore, ownerWant := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			if !row.conflict {
				ownerWant.tokenHighWater++
			}
			outcome, err := f.relay.admitDANonReplay(admission, daNonReplayPeer("candidate"))
			if row.accept {
				if err != nil || outcome != (daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(1)}) {
					t.Fatalf("equal cap outcome=%+v err=%v", outcome, err)
				}
				return
			}
			if outcome != (daRelayAdmissionOutcome{}) {
				t.Fatalf("outcome=%+v", outcome)
			}
			if row.conflict {
				var admitErr *TxAdmitError
				if !errors.As(err, &admitErr) || admitErr.Kind != TxAdmitErrorKind("conflict") {
					t.Fatalf("owner precedence error=%v", err)
				}
			} else if row.cap == "global" && err != errDARelayOrphanPoolCapExceeded || row.cap == "commit" && err != errDARelayOrphanCommitCapExceeded { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
				t.Fatalf("cap error=%v", err)
			}
			if got := daRelayStateSnapshot(f.relay); !reflect.DeepEqual(got, relayBefore) { //nolint:govet // Complete private state-image equality requires structural comparison, error identities included.
				t.Fatal("State-B refusal published relay state")
			}
			if got := cloneDAAdmissionOwner(f.mp.pendingOutpoints); !reflect.DeepEqual(got, ownerWant) {
				t.Fatalf("State-B owner=%+v want=%+v", got, ownerWant)
			}
		})
	}
	t.Run("plan isolation and single use", func(t *testing.T) {
		chunkFixture := newDANonReplayFixture(t, 1)
		chunk := chunkFixture.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x44}, chunkIndex: 1, payload: []byte("isolated-payload")})
		chunkPlan := chunkFixture.planned(chunk, daNonReplayPeer("boundary"))
		defer chunkPlan.admission.Close()
		chunkPlan.candidate.member.txBytes[0] ^= 0xff
		chunkPlan.candidate.member.payload[0] ^= 0xff
		chunkPlan.candidate.member.member.inputs[0].Vout++
		stagedChunk := chunkPlan.plan.image.next.chunks[1]
		if len(chunkPlan.plan.victims) != 0 || !bytes.Equal(stagedChunk.txBytes, chunk.raw) || !bytes.Equal(stagedChunk.payload, []byte("isolated-payload")) || stagedChunk.member == nil || !slices.Equal(stagedChunk.member.inputs, []consensus.Outpoint{chunk.inputs[0]}) {
			t.Fatalf("chunk plan aliases candidate: chunk=%+v victims=%+v", stagedChunk, chunkPlan.plan.victims)
		}
		outcome, err := chunkFixture.relay.applyDANonReplayPlan(chunkPlan.admission, chunkPlan.candidate, chunkPlan.plan)
		if err != nil || outcome != (daRelayAdmissionOutcome{daID: chunk.spec.daID, disposition: daRelayAdmissionDisposition(1)}) {
			t.Fatalf("isolated chunk outcome=%+v err=%v", outcome, err)
		}
		chunkFixture.requireSingleRetained(t, chunk, daRelayStateOrphanChunks)
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x45}
		victim := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 2, payload: []byte("victim")})
		f.admit(victim, daNonReplayPeer("victim"))
		commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0x45}, commitmentOutputs: 1})
		plan := f.planned(commit, daNonReplayPeer("commit"))
		defer plan.admission.Close()
		plan.candidate.member.txBytes[0] ^= 0xff
		plan.candidate.member.member.inputs[0].Vout++
		wantVictims := []DAAdmissionVictim{{TxID: victim.txid, Inputs: []consensus.Outpoint{victim.inputs[0]}, Token: PendingOutpointToken{owner: f.mp.pendingOutpoints, seq: 1}}}
		if !bytes.Equal(plan.plan.image.next.commit.txBytes, commit.raw) || plan.plan.image.next.commit.member == nil || !slices.Equal(plan.plan.image.next.commit.member.inputs, []consensus.Outpoint{commit.inputs[0]}) || !reflect.DeepEqual(plan.plan.victims, wantVictims) {
			t.Fatalf("commit plan aliases candidate: commit=%+v victims=%+v", plan.plan.image.next.commit, plan.plan.victims)
		}
		outcome, err = f.relay.applyDANonReplayPlan(plan.admission, plan.candidate, plan.plan)
		if err != nil || outcome != (daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(1)}) {
			t.Fatalf("isolated commit outcome=%+v err=%v", outcome, err)
		}
		f.requireMember(t, daRelayStateSnapshot(f.relay).sets[daID], commit, 2, daNonReplayPeer("commit"))
		relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		outcome, err = f.relay.applyDANonReplayPlan(plan.admission, plan.candidate, plan.plan)
		if err != nil || outcome != (daRelayAdmissionOutcome{daID: daID, disposition: daRelayAdmissionDisposition(2)}) {
			t.Fatalf("reused plan outcome=%+v err=%v", outcome, err)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	})
	t.Run("victim failure releases candidate but keeps high-water", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0x43}
		outside := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("victim")})
		f.admit(outside, daNonReplayPeer("peer"))
		f.relay.mu.Lock()
		record := f.relay.sets[daID]
		chunk := record.chunks[3]
		chunk.member.inputs[0].Vout++
		record.chunks[3] = chunk
		f.relay.sets[daID] = record
		f.relay.mu.Unlock()
		commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0x43}, commitmentOutputs: 1})
		admission := f.begin(commit)
		defer admission.Close()
		relayBefore, ownerWant := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		ownerWant.tokenHighWater++
		outcome, err := f.relay.admitDANonReplay(admission, daNonReplayPeer("candidate"))
		var admitErr *TxAdmitError
		if outcome != (daRelayAdmissionOutcome{}) || !errors.As(err, &admitErr) || admitErr.Kind != TxAdmitErrorKind("unavailable") || admitErr.Message != "DA victim input mismatch" {
			t.Fatalf("victim failure outcome=%+v err=%v", outcome, err)
		}
		if got := daRelayStateSnapshot(f.relay); !reflect.DeepEqual(got, relayBefore) { //nolint:govet // Complete private state-image equality requires structural comparison, error identities included.
			t.Fatal("victim failure published DA state")
		}
		if got := cloneDAAdmissionOwner(f.mp.pendingOutpoints); !reflect.DeepEqual(got, ownerWant) {
			t.Fatalf("owner after victim failure=%+v want one high-water advance and no claim change %+v", got, ownerWant)
		}
	})
}

func daNonReplayFunction(t *testing.T, name string) *ast.FuncDecl {
	path := "da_relay_owner" + map[bool]string{true: "_test"}[strings.HasPrefix(name, "Test") || name == "requireDANonReplayRawCommitOutputs"] + ".go"
	file, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parse da_relay_owner.go: %v", err)
	}
	for _, declaration := range file.Decls {
		function, ok := declaration.(*ast.FuncDecl)
		if ok && function.Name.Name == name {
			return function
		}
	}
	t.Fatalf("function %s missing", name)
	return nil
}

func daNonReplayOwnedExpression(expression ast.Expr, owned map[string]bool) bool {
	switch value := expression.(type) {
	case *ast.Ident:
		return owned[value.Name]
	case *ast.SelectorExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.IndexExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.SliceExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.ParenExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.StarExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.UnaryExpr:
		return daNonReplayOwnedExpression(value.X, owned)
	case *ast.CompositeLit:
		for _, element := range value.Elts {
			if daNonReplayOwnedExpression(element, owned) {
				return true
			}
		}
	case *ast.KeyValueExpr:
		return daNonReplayOwnedExpression(value.Value, owned)
	}
	return false
}

func daNonReplayLiteralCaptures(literal *ast.FuncLit, owned map[string]bool) bool {
	for _, statement := range literal.Body.List {
		if assignment, ok := statement.(*ast.AssignStmt); ok && assignment.Tok == token.DEFINE && len(assignment.Lhs) == 1 && owned[daNonReplaySelector(assignment.Lhs[0])] {
			return false
		}
	}
	captured := false
	ast.Inspect(literal.Body, func(node ast.Node) bool {
		if nested, ok := node.(*ast.FuncLit); ok && nested != literal {
			return false
		}
		if name, ok := node.(*ast.Ident); ok && owned[name.Name] {
			captured = true
			return false
		}
		return !captured
	})
	return captured
}

func heldDANonReplayMutation(function *ast.FuncDecl) string {
	owned := map[string]bool{"admission": true}
	diagnostic := ""
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if diagnostic != "" {
			return false
		}
		if value, ok := node.(*ast.ValueSpec); ok {
			for _, initializer := range value.Values {
				if daNonReplayOwnedExpression(initializer, owned) {
					name := "var"
					if len(value.Names) != 0 {
						name += " " + value.Names[0].Name
					}
					diagnostic = "post-Begin admission escape: " + name
					return false
				}
			}
		}
		if send, ok := node.(*ast.SendStmt); ok && daNonReplayOwnedExpression(send.Value, owned) {
			diagnostic = "post-Begin admission escape: channel send"
			return false
		}
		if literal, ok := node.(*ast.FuncLit); ok && daNonReplayLiteralCaptures(literal, owned) {
			diagnostic = "post-Begin admission capture"
			return false
		}
		if assignment, ok := node.(*ast.AssignStmt); ok {
			for index, right := range assignment.Rhs {
				if daNonReplayOwnedExpression(right, owned) {
					target := "assignment"
					if index < len(assignment.Lhs) {
						target = daNonReplaySelector(assignment.Lhs[index])
					}
					diagnostic = "post-Begin admission escape: " + target
					return false
				}
			}
			for _, left := range assignment.Lhs {
				path := daNonReplaySelector(left)
				root := strings.SplitN(path, ".", 2)[0]
				if owned[root] && (path != root || assignment.Tok != token.DEFINE) {
					diagnostic = "post-Begin admission mutation: " + path
					return false
				}
			}
		}
		if mutation, ok := node.(*ast.IncDecStmt); ok {
			path := daNonReplaySelector(mutation.X)
			if owned[strings.SplitN(path, ".", 2)[0]] {
				diagnostic = "post-Begin admission mutation: " + path
				return false
			}
		}
		call, ok := node.(*ast.CallExpr)
		if !ok {
			return true
		}
		name := daNonReplaySelector(call.Fun)
		if strings.HasSuffix(name, ".admitDANonReplay") || strings.HasSuffix(name, ".Close") {
			return true
		}
		if owned[strings.SplitN(name, ".", 2)[0]] {
			diagnostic = "post-Begin admission escape: " + name
			return false
		}
		for _, argument := range call.Args {
			if daNonReplayOwnedExpression(argument, owned) {
				diagnostic = "post-Begin admission escape: " + name
				return false
			}
		}
		return diagnostic == ""
	})
	return diagnostic
}

func checkDANonReplayCallerDefers(file *ast.File) string {
	callers, diagnostic, direct := 0, "", map[token.Pos]bool{}
	ast.Inspect(file, func(node ast.Node) bool {
		switch value := node.(type) {
		case *ast.CallExpr:
			direct[value.Fun.Pos()] = true
		case *ast.SelectorExpr:
			name := daNonReplaySelector(value)
			if (strings.HasSuffix(name, ".admitDANonReplay") || strings.HasSuffix(name, ".applyDANonReplayPlan")) && !direct[value.Pos()] {
				diagnostic = "direct DA caller lacks preceding defer: method value " + name
				return false
			}
		}
		return true
	})
	ast.Inspect(file, func(node ast.Node) bool {
		block, ok := node.(*ast.BlockStmt)
		if !ok || diagnostic != "" {
			return diagnostic == ""
		}
		deferred := map[string]bool{}
		for _, statement := range block.List {
			if delay, ok := statement.(*ast.DeferStmt); ok && strings.HasSuffix(daNonReplaySelector(delay.Call.Fun), ".Close") {
				deferred[strings.TrimSuffix(daNonReplaySelector(delay.Call.Fun), ".Close")] = true
			}
			ast.Inspect(statement, func(child ast.Node) bool {
				if child != statement {
					switch child.(type) {
					case *ast.FuncLit, *ast.BlockStmt:
						return false
					}
				}
				call, ok := child.(*ast.CallExpr)
				if !ok || len(call.Args) == 0 {
					return true
				}
				name := daNonReplaySelector(call.Fun)
				if !strings.HasSuffix(name, ".admitDANonReplay") && !strings.HasSuffix(name, ".applyDANonReplayPlan") {
					return true
				}
				callers++
				admission := daNonReplaySelector(call.Args[0])
				if !deferred[admission] {
					diagnostic = "direct DA caller lacks preceding defer: " + admission
					return false
				}
				return true
			})
		}
		return diagnostic == ""
	})
	if diagnostic == "" && callers == 0 {
		return "direct DA caller census is empty"
	}
	return diagnostic
}

func parseDANonReplayFixture(t *testing.T, path, source string) *ast.FuncDecl {
	file, err := parser.ParseFile(token.NewFileSet(), path, source, parser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	return file.Decls[0].(*ast.FuncDecl)
}

func daNonReplayDirectErrorReturn(statement ast.Stmt, failure string) bool {
	branch, ok := statement.(*ast.IfStmt)
	if !ok || branch.Else != nil || len(branch.Body.List) != 1 {
		return false
	}
	condition, conditionOK := branch.Cond.(*ast.BinaryExpr)
	result, resultOK := branch.Body.List[0].(*ast.ReturnStmt)
	if !conditionOK || condition.Op != token.NEQ || daNonReplaySelector(condition.X) != "err" || daNonReplaySelector(condition.Y) != "nil" || !resultOK || len(result.Results) != 2 || daNonReplaySelector(result.Results[1]) != failure {
		return false
	}
	zero, zeroOK := result.Results[0].(*ast.CompositeLit)
	return zeroOK && daNonReplaySelector(zero.Type) == "daRelayAdmissionOutcome" && len(zero.Elts) == 0
}

func checkDANonReplayRendererPrefix(function, oracle *ast.FuncDecl) string {
	statements, renderCalls := function.Body.List, 0
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if call, ok := node.(*ast.CallExpr); ok && strings.HasSuffix(daNonReplaySelector(call.Fun), ".renderDARelayAdmissionCandidate") {
			renderCalls++
		}
		return true
	})
	if len(statements) != 4 || renderCalls != 1 {
		return fmt.Sprintf("admission prefix statements=%d renderer calls=%d, want 4,1", len(statements), renderCalls)
	}
	assignment, ok := statements[0].(*ast.AssignStmt)
	if !ok || assignment.Tok != token.DEFINE || len(assignment.Lhs) != 2 || len(assignment.Rhs) != 1 || daNonReplaySelector(assignment.Lhs[0]) != "candidate" || daNonReplaySelector(assignment.Lhs[1]) != "err" {
		return "renderer assignment prefix changed"
	}
	renderer, ok := assignment.Rhs[0].(*ast.CallExpr)
	if !ok || daNonReplaySelector(renderer.Fun) != "admission.renderDARelayAdmissionCandidate" || !daNonReplayDirectErrorReturn(statements[1], "err") {
		return "renderer error prefix changed"
	}
	if _, ok := statements[2].(*ast.IfStmt); !ok {
		return "binding branch prefix changed"
	}
	result, ok := statements[3].(*ast.ReturnStmt)
	if !ok || len(result.Results) != 1 {
		return "planning/apply return prefix changed"
	}
	apply, ok := result.Results[0].(*ast.CallExpr)
	if !ok || daNonReplaySelector(apply.Fun) != "s.applyDANonReplayPlan" || len(apply.Args) != 3 {
		return "planning/apply return prefix changed"
	}
	plan, ok := apply.Args[2].(*ast.CallExpr)
	if !ok || daNonReplaySelector(plan.Fun) != "s.planDANonReplay" {
		return "planning/apply return prefix changed"
	}
	oracleComparisons, literalOracle := 0, false
	ast.Inspect(oracle.Body, func(node ast.Node) bool {
		comparison, ok := node.(*ast.BinaryExpr)
		if !ok || comparison.Op != token.NEQ || daNonReplaySelector(comparison.X) != "output.CovenantType" {
			return true
		}
		oracleComparisons++
		literal, ok := comparison.Y.(*ast.BasicLit)
		literalOracle = ok && literal.Kind == token.INT && literal.Value == "0x0103"
		return true
	})
	if oracleComparisons != 1 || !literalOracle {
		return fmt.Sprintf("raw covenant oracle comparisons=%d literal=%t, want 1,true", oracleComparisons, literalOracle)
	}
	return ""
}

func requireDANonReplayRawCommitOutputs(t *testing.T, raw []byte, want int) {
	tx, _, _, consumed, err := consensus.ParseTx(raw)
	if err != nil || consumed != len(raw) {
		t.Fatalf("independent ParseTx=(%d,%v), want %d,nil", consumed, err, len(raw))
	}
	count := 0
	for _, output := range tx.Outputs {
		if output.CovenantType != 0x0103 {
			continue
		}
		count++
		var content [32]byte
		if len(output.CovenantData) != 32 {
			t.Fatalf("CORE_DA_COMMIT width=%d", len(output.CovenantData))
		}
		copy(content[:], output.CovenantData)
		if content != ([32]byte{0xa5}) {
			t.Fatalf("CORE_DA_COMMIT content=%x", content)
		}
	}
	if count != want {
		t.Fatalf("CORE_DA_COMMIT outputs=%d, want %d", count, want)
	}
}

func TestAdmitDANonReplayFailurePrefixes(t *testing.T) {
	function := daNonReplayFunction(t, "admitDANonReplay")
	if callerFile, err := parser.ParseFile(token.NewFileSet(), "da_relay_owner_test.go", nil, parser.SkipObjectResolution); err != nil {
		t.Fatal(err)
	} else if diagnostic := checkDANonReplayCallerDefers(callerFile); diagnostic != "" {
		t.Fatal(diagnostic)
	}
	if trailing, err := parser.ParseFile(token.NewFileSet(), "trailing.go", "package node\nfunc probe() { admission := f.begin(tx)\ncall := f.relay.admitDANonReplay\n_, _ = call(admission, provenance)\nadmission.Close()\n}", parser.SkipObjectResolution); err != nil {
		t.Fatal(err)
	} else if diagnostic := checkDANonReplayCallerDefers(trailing); !strings.Contains(diagnostic, "lacks preceding defer") {
		t.Fatalf("trailing Close diagnostic=%q", diagnostic)
	}
	if diagnostic := heldDANonReplayMutation(daNonReplayFunction(t, "TestAdmitDANonReplayFailurePrefixes")); diagnostic != "" {
		t.Fatal(diagnostic)
	}
	for name, body := range map[string]string{
		"direct field":      "admission.tx.Version = 2",
		"indexed field":     "admission.tx.Outputs[0].Value = 1",
		"slice alias":       "outputs := admission.tx.Outputs[:]\noutputs[0].Value++",
		"direct alias":      "alias := admission\nalias.tx.Version = 2",
		"alias increment":   "alias := admission\nalias.tx.Version++",
		"var alias":         "var alias = admission\nalias.tx.Version++",
		"assigned alias":    "var alias *DAAdmission\nalias = admission\nalias.tx.Version++",
		"pointer alias":     "alias := &admission.tx\n(*alias).Version = 2",
		"pointer increment": "alias := &admission.tx\n(*alias).Version++",
		"struct alias":      "holder := struct{ admission *DAAdmission }{}\nholder.admission = admission\nholder.admission.tx.Version++",
		"composite alias":   "holder := struct{ admission *DAAdmission }{admission: admission}\n_ = holder",
		"channel send":      "channel := make(chan *DAAdmission, 1)\nchannel <- admission",
		"helper":            "mutate(admission)",
		"alias helper":      "alias := admission\nmutate(alias)",
		"function literal":  "func() { admission.tx.Version = 2 }()",
		"captured literal":  "mutate := func() { admission.tx.Version = 2 }\nmutate()",
		"composite":         "admission.tx = &consensus.Tx{}",
		"whole object":      "*admission = DAAdmission{}",
	} {
		t.Run("AST "+name, func(t *testing.T) {
			if diagnostic := heldDANonReplayMutation(parseDANonReplayFixture(t, "mutation.go", "package node\nfunc probe() { admission := f.begin(tx)\n"+body+"\ndefer admission.Close()\n_, _ = f.relay.admitDANonReplay(admission, provenance)\n}")); !strings.HasPrefix(diagnostic, "post-Begin admission") {
				t.Fatalf("diagnostic=%q", diagnostic)
			}
		})
	}
	if diagnostic := heldDANonReplayMutation(parseDANonReplayFixture(t, "mutation.go", "package node\nfunc probe() { admission := f.begin(tx)\nother := &DAAdmission{}\nother.tx.Version = 2\nother.tx.Version++\ndefer admission.Close()\n_, _ = f.relay.admitDANonReplay(admission, provenance)\n}")); diagnostic != "" {
		t.Fatalf("inert non-owner mutation rejected: %s", diagnostic)
	}
	if diagnostic := checkDANonReplayRendererPrefix(function, daNonReplayFunction(t, "requireDANonReplayRawCommitOutputs")); diagnostic != "" {
		t.Fatal(diagnostic)
	}
	for _, outputs := range []int{0, 2} {
		t.Run("commitment outputs "+string(rune('0'+outputs)), func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x51, byte(outputs)}, chunkCount: 2, commitment: [32]byte{0xa5}, commitmentOutputs: outputs})
			requireDANonReplayRawCommitOutputs(t, tx.raw, outputs)
			admission := f.begin(tx)
			defer admission.Close()
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			outcome, err := f.relay.admitDANonReplay(admission, daNonReplayPeer("peer"))
			if outcome != (daRelayAdmissionOutcome{}) || err != errDARelayMemberIncomplete || !errors.Is(err, errDARelayMemberIncomplete) { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
				t.Fatalf("renderer prefix outcome=%+v err=%v", outcome, err)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
		})
	}
	for _, row := range []struct {
		name                   string
		outputs                int
		matchOwner, matchChain bool
		want                   error
	}{{"foreign chainstate", 1, true, false, errDARelayImageIncompatible}, {"foreign owner", 1, false, true, errDARelayImageIncompatible}, {"renderer precedes foreign binding", 0, false, false, errDARelayMemberIncomplete}} {
		t.Run(row.name, func(t *testing.T) {
			a, b := newDANonReplayFixture(t, 1), newDANonReplayFixture(t, 1)
			originalOwner, originalOwnerBefore := a.mp.pendingOutpoints, cloneDAAdmissionOwner(a.mp.pendingOutpoints)
			if row.matchOwner {
				a.mp.pendingOutpoints = b.mp.pendingOutpoints
			}
			if row.matchChain {
				a.mp.chainState = b.mp.chainState
			}
			tx := b.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x50, byte(row.outputs)}, chunkCount: 2, commitment: [32]byte{0xa5}, commitmentOutputs: row.outputs})
			requireDANonReplayRawCommitOutputs(t, tx.raw, row.outputs)
			admission := b.begin(tx)
			defer admission.Close()
			aRelay, aOwnerBefore := daRelayStateSnapshot(a.relay), cloneDAAdmissionOwner(a.mp.pendingOutpoints)
			bRelay, bOwner := daRelayStateSnapshot(b.relay), cloneDAAdmissionOwner(b.mp.pendingOutpoints)
			outcome, err := a.relay.admitDANonReplay(admission, daNonReplayPeer("peer"))
			if outcome != (daRelayAdmissionOutcome{}) || err != row.want { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
				t.Fatalf("foreign outcome=%+v err=%v want=%v", outcome, err, row.want)
			}
			requireDANonReplayUnchanged(t, a.relay, a.mp.pendingOutpoints, aRelay, aOwnerBefore)
			if got := cloneDAAdmissionOwner(originalOwner); !reflect.DeepEqual(got, originalOwnerBefore) {
				t.Fatal("foreign admission mutated relay A's original owner")
			}
			requireDANonReplayUnchanged(t, b.relay, b.mp.pendingOutpoints, bRelay, bOwner)
		})
	}
	t.Run("caller defer closes on precommit panic", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		sentinel := &struct{}{}
		recovered := func() (value any) {
			defer func() { value = recover() }()
			panicAdmission := f.begin(f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x55}, payload: []byte("panic")}))
			defer panicAdmission.Close()
			candidate, err := panicAdmission.renderDARelayAdmissionCandidate(daNonReplayPeer("peer"))
			if err != nil {
				t.Fatal(err)
			}
			_ = f.relay.planDANonReplay(candidate)
			panic(sentinel)
		}()
		if recovered != sentinel || !f.state.admissionMu.TryLock() {
			t.Fatalf("recovered=%v; admission guard leaked", recovered)
		}
		f.state.admissionMu.Unlock()
	})
	t.Run("invalid provenance", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x52}, payload: []byte("invalid provenance")})
		requireDANonReplayRejected(t, f, tx, daProvenance{}, errDAProvenanceInvalid)
	})
	for _, row := range []struct {
		name    string
		corrupt func(*daRelaySetRecord)
		want    error
	}{
		{"zero revision", func(record *daRelaySetRecord) { record.revision = 0 }, errDARelayImageIncompatible},
		{"zero received time", func(record *daRelaySetRecord) { record.receivedTime = 0 }, errDARelayImageIncompatible},
		{"zero ttl", func(record *daRelaySetRecord) { record.ttlBlocksRemaining = 0 }, errDARelayImageIncompatible},
		{"legacy wire bytes", func(record *daRelaySetRecord) { record.wireBytes = 1 }, errDARelayImageIncompatible},
		{"complete set", func(record *daRelaySetRecord) { record.state = daRelayStateCompleteSet }, errDARelayImageIncompatible},
		{"zero preserved token", func(record *daRelaySetRecord) { record.chunks[0].member.token.seq = 0 }, errDARelayImageIncompatible},
		{"zero retained txid", func(record *daRelaySetRecord) { record.chunks[0].member.txid = [32]byte{} }, errDARelayMemberIncomplete},
		{"zero retained wtxid", func(record *daRelaySetRecord) { record.chunks[0].member.wtxid = [32]byte{} }, errDARelayMemberIncomplete},
		{"foreign preserved token", func(record *daRelaySetRecord) {
			record.chunks[0].member.token = PendingOutpointToken{owner: newPendingOutpointOwner(PendingOutpointTip{}), seq: 1}
		}, errDARelayImageIncompatible},
		{"zero commit token", func(record *daRelaySetRecord) { record.commit.member.token.seq = 0 }, errDARelayImageIncompatible},
		{"foreign commit token", func(record *daRelaySetRecord) {
			record.commit.member.token.owner = newPendingOutpointOwner(PendingOutpointTip{})
		}, errDARelayImageIncompatible},
		{"invalid provenance", func(record *daRelaySetRecord) {
			chunk := record.chunks[0]
			chunk.member.provenance = daProvenance{}
			record.chunks[0] = chunk
		}, errDAProvenanceInvalid},
	} {
		t.Run("rejected prior "+row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 2), [32]byte{0x54, byte(len(row.name))}
			seed := daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("resident")}
			if strings.Contains(row.name, "commit token") {
				seed = daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 3, commitment: [32]byte{0x54}, commitmentOutputs: 1}
			}
			f.admit(f.signed(seed), daNonReplayPeer("resident"))
			f.mutateRelay(func(r *DARelayState) { record := r.sets[daID]; row.corrupt(&record); r.sets[daID] = record })
			candidate := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("candidate")})
			requireDANonReplayRejected(t, f, candidate, daNonReplayPeer("candidate"), row.want)
		})
	}
	for _, row := range []struct {
		name  string
		setup func(*daNonReplayFixture, [32]byte)
		want  error
	}{
		{"locator mismatch", func(f *daNonReplayFixture, daID [32]byte) {
			seed := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("seed")})
			f.admit(seed, daNonReplayPeer("peer"))
			f.mutateRelay(func(r *DARelayState) { delete(r.locators, seed.txid) })
		}, errDARelayLocatorMismatch},
		{"revision overflow", func(f *daNonReplayFixture, _ [32]byte) {
			f.mutateRelay(func(r *DARelayState) { r.records = ^uint64(0) })
		}, errDARelayArithmeticOverflow},
	} {
		t.Run(row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 2), [32]byte{0x53, byte(len(row.name))}
			row.setup(f, daID)
			candidate := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("candidate")})
			requireDANonReplayRejected(t, f, candidate, daNonReplayPeer("candidate"), row.want)
		})
	}
}

func TestAdmitDANonReplayPrunesOutOfRangeClaims(t *testing.T) {
	f, daID := newDANonReplayFixture(t, 5), [32]byte{0x61}
	inside := []daNonReplayTx{
		f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 0, payload: []byte("inside-zero")}),
		f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("inside-one")}),
	}
	outside := []daNonReplayTx{
		f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 3, payload: []byte("outside-three")}),
		f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 4, payload: []byte("outside-four")}),
	}
	commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 3, commitment: [32]byte{0x99}, commitmentOutputs: 1})
	for index, tx := range append(append([]daNonReplayTx(nil), inside...), outside...) {
		f.admit(tx, daNonReplayPeer(fmt.Sprintf("peer-%d", index)))
	}
	f.admit(commit, daNonReplayPeer("peer-commit"))
	record := requireDANonReplayRecordHeader(t, f.relay, daID, daRelaySetState(1), 5, 1, 7)
	if len(record.chunks) != 2 || record.chunks[0].member == nil || record.chunks[1].member == nil {
		t.Fatalf("pruned chunks=%+v, want exact indexes 0 and 1", record.chunks)
	}
	for index, tx := range inside {
		f.requireMember(t, record, tx, uint64(index+1), daNonReplayPeer(fmt.Sprintf("peer-%d", index)))
	}
	f.requireMember(t, record, commit, 5, daNonReplayPeer("peer-commit"))
	view := daRelayStateSnapshot(f.relay)
	insideCharge := uint64(0)
	for index, tx := range inside {
		insideCharge += uint64(len(tx.raw) + len(tx.spec.payload))
		if view.locators[tx.txid] != (daRelayLocator{daID: daID, kind: daRelayLocatorKind(2), chunkIndex: tx.spec.chunkIndex}) {
			t.Fatalf("survivor %d locator=%+v", index, view.locators[tx.txid])
		}
	}
	for index, tx := range outside {
		if _, retained := record.chunks[tx.spec.chunkIndex]; retained {
			t.Fatalf("victim %d chunk survived", index)
		}
		if _, present := view.locators[tx.txid]; present {
			t.Fatalf("victim %d locator survived", index)
		}
	}
	commitCharge := uint64(len(commit.raw))
	if len(view.locators) != 3 || view.locators[commit.txid] != (daRelayLocator{daID: daID, kind: daRelayLocatorKind(1)}) {
		t.Fatalf("locators=%+v, want commit plus two survivors", view.locators)
	}
	if view.orphanBytes != insideCharge+commitCharge || view.daIDBytes[daID] != insideCharge+commitCharge || view.commitBytes != commitCharge || view.peerBytes["peer-0"] != uint64(len(inside[0].raw)+len(inside[0].spec.payload)) || view.peerBytes["peer-1"] != uint64(len(inside[1].raw)+len(inside[1].spec.payload)) || view.peerBytes["peer-2"] != 0 || view.peerBytes["peer-3"] != 0 || view.peerBytes["peer-commit"] != commitCharge || len(view.peerBytes) != 3 {
		t.Fatalf("accounting global=%d da=%d commit=%d peers=%+v", view.orphanBytes, view.daIDBytes[daID], view.commitBytes, view.peerBytes)
	}
	owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	for index, tx := range inside {
		requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, tx, uint64(index+1))
	}
	for index, tx := range outside {
		_, inputPresent := owner.byOutpoint[tx.inputs[0]]
		if owner.byToken[PendingOutpointToken{owner: f.mp.pendingOutpoints, seq: uint64(index + 3)}] != nil || inputPresent {
			t.Fatalf("victim %d claim/input survived", index)
		}
	}
	requireDANonReplayClaim(t, owner, f.mp.pendingOutpoints, commit, 5)
	if owner.tokenHighWater != 5 || len(owner.byToken) != 3 || len(owner.byOutpoint) != 3 {
		t.Fatalf("pruned owner=%+v", owner)
	}
}

func TestAdmitDANonReplaySequenceAndAccounting(t *testing.T) {
	for _, row := range []struct {
		name, peerKey string
		provenance    daProvenance
		inputCount    int
		fee           consensus.Uint128
	}{
		{"peer", "quota", daNonReplayPeer("quota"), 2, consensus.Uint128{Hi: 1, Lo: 700_000}},
		{"local", "", daProvenance{kind: daProvenanceKind(2)}, 0, consensus.Uint128{Lo: 600_000}},
		{"detached", "", daProvenance{kind: daProvenanceKind(3)}, 0, consensus.Uint128{Lo: 600_000}},
	} {
		t.Run(row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, max(row.inputCount, 1)), [32]byte{0x71, byte(len(row.name))}
			for _, input := range f.outpoints[:row.inputCount] {
				utxo := f.state.Utxos[input]
				utxo.Value += 1 << 63
				f.state.Utxos[input] = utxo
			}
			tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: uint16(len(row.name)), payload: []byte("accounting"), inputCount: row.inputCount, fee: row.fee})
			f.admit(tx, row.provenance)
			view, charge := daRelayStateSnapshot(f.relay), uint64(len(tx.raw)+len(tx.spec.payload))
			if view.nextReceivedTime != 1 || view.records != 1 || view.orphanBytes != charge || view.daIDBytes[daID] != charge || view.commitBytes != 0 || view.sets[daID].receivedTime != 1 {
				t.Fatalf("accounting sequence=%d revision=%d global=%d da=%d commit=%d", view.nextReceivedTime, view.records, view.orphanBytes, view.daIDBytes[daID], view.commitBytes)
			}
			if row.peerKey == "" {
				if len(view.peerBytes) != 0 {
					t.Fatalf("peerless buckets=%+v, want none", view.peerBytes)
				}
			} else if len(view.peerBytes) != 1 || view.peerBytes[row.peerKey] != charge {
				t.Fatalf("peer buckets=%+v, want %q=%d", view.peerBytes, row.peerKey, charge)
			}
			f.requireMember(t, view.sets[daID], tx, 1, row.provenance)
		})
	}
	for _, provenance := range []daProvenance{daNonReplayPeer("cap"), {kind: daProvenanceKind(2)}, {kind: daProvenanceKind(3)}} {
		for _, capName := range []string{"global", "da", "peer"} {
			for _, reject := range []bool{false, true} {
				t.Run("State A provenance "+string([]byte{'0' + byte(provenance.kind)})+" "+capName+map[bool]string{false: " equal", true: " minus one"}[reject], func(t *testing.T) {
					f := newDANonReplayFixture(t, 1)
					tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x72, byte(len(capName)), byte(map[bool]int{true: 1}[reject])}, payload: []byte("cap")})
					limit := uint64(len(tx.raw) + len(tx.spec.payload))
					if reject {
						limit--
					}
					f.relay.mu.Lock()
					cap := map[string]*uint64{"global": &f.relay.caps.orphanPoolBytes, "da": &f.relay.caps.orphanPoolPerDAIDBytes, "peer": &f.relay.caps.orphanPoolPerPeerBytes}[capName]
					*cap = limit
					f.relay.mu.Unlock()
					capReject := reject && (capName != "peer" || provenance.kind == daProvenanceKind(1))
					if !capReject {
						f.admit(tx, provenance)
						return
					}
					want := map[string]error{"global": errDARelayOrphanPoolCapExceeded, "da": errDARelayOrphanDAIDCapExceeded, "peer": errDARelayOrphanPeerCapExceeded}[capName]
					requireDANonReplayRejected(t, f, tx, provenance, want)
				})
			}
		}
	}
	for _, field := range []string{"global", "revision", "da", "peer"} {
		t.Run("checked "+field+" overflow before cap", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x75, byte(len(field))}, payload: []byte("overflow")})
			f.relay.mu.Lock()
			f.relay.caps.orphanPoolBytes = 1
			switch field {
			case "global":
				f.relay.orphanBytes, f.relay.caps.orphanPoolBytes = ^uint64(0), ^uint64(0)
			case "revision":
				f.relay.records = ^uint64(0)
			case "da":
				f.relay.orphanBytesByDAID[tx.spec.daID] = ^uint64(0)
			case "peer":
				f.relay.orphanBytesByPeerQuotaKey["peer"] = ^uint64(0)
			}
			f.relay.mu.Unlock()
			requireDANonReplayRejected(t, f, tx, daNonReplayPeer("peer"), errDARelayArithmeticOverflow)
		})
	}
	t.Run("last sequence then overflow", func(t *testing.T) {
		f := newDANonReplayFixture(t, 2)
		f.mutateRelay(func(r *DARelayState) { r.nextReceivedTime = ^uint64(0) - 1 })
		last := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x73}, payload: []byte("last")})
		f.admit(last, daNonReplayPeer("peer"))
		view := daRelayStateSnapshot(f.relay)
		if view.nextReceivedTime != ^uint64(0) || view.sets[last.spec.daID].receivedTime != ^uint64(0) {
			t.Fatalf("last sequence state=%d record=%d", view.nextReceivedTime, view.sets[last.spec.daID].receivedTime)
		}
		overflow := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x74}, payload: []byte("overflow")})
		requireDANonReplayRejected(t, f, overflow, daNonReplayPeer("peer"), errDARelayArithmeticOverflow)
	})
}

func daNonReplaySelector(expression ast.Expr) string {
	switch value := expression.(type) {
	case *ast.Ident:
		return value.Name
	case *ast.SelectorExpr:
		prefix := daNonReplaySelector(value.X)
		if prefix != "" {
			return prefix + "." + value.Sel.Name
		}
	case *ast.IndexExpr:
		return daNonReplaySelector(value.X)
	case *ast.ParenExpr:
		return daNonReplaySelector(value.X)
	case *ast.StarExpr:
		return daNonReplaySelector(value.X)
	case *ast.UnaryExpr:
		return daNonReplaySelector(value.X)
	}
	return ""
}

func daNonReplayAssignment(statement ast.Stmt, left, right string) bool {
	assignment, ok := statement.(*ast.AssignStmt)
	return ok && assignment.Tok == token.ASSIGN && len(assignment.Lhs) == 1 && len(assignment.Rhs) == 1 && daNonReplaySelector(assignment.Lhs[0]) == left && daNonReplaySelector(assignment.Rhs[0]) == right
}

func daNonReplayCall(statement ast.Stmt, name string, argument string) bool {
	expression, ok := statement.(*ast.ExprStmt)
	if !ok {
		return false
	}
	call, ok := expression.X.(*ast.CallExpr)
	return ok && daNonReplaySelector(call.Fun) == name && (argument == "" && len(call.Args) == 0 || len(call.Args) == 1 && daNonReplaySelector(call.Args[0]) == argument)
}

func daNonReplayTokenAssignment(statement ast.Stmt) bool {
	assignment, ok := statement.(*ast.AssignStmt)
	if !ok || assignment.Tok != token.ASSIGN || len(assignment.Lhs) != 1 || len(assignment.Rhs) != 1 || daNonReplaySelector(assignment.Lhs[0]) != "member.token" {
		return false
	}
	call, ok := assignment.Rhs[0].(*ast.CallExpr)
	return ok && daNonReplaySelector(call.Fun) == "commit.CandidateToken" && len(call.Args) == 0
}

func daNonReplayCapAbort(statement ast.Stmt, projected, cap, failure string) bool {
	branch, ok := statement.(*ast.IfStmt)
	if !ok || branch.Else != nil || len(branch.Body.List) != 2 {
		return false
	}
	condition, ok := branch.Cond.(*ast.BinaryExpr)
	if !ok {
		return false
	}
	exceeded, right := condition.Y.(*ast.BinaryExpr)
	result, resultOK := branch.Body.List[1].(*ast.ReturnStmt)
	if condition.Op != token.LAND || daNonReplaySelector(condition.X) != "stateB" || !right || exceeded.Op != token.GTR || daNonReplaySelector(exceeded.X) != projected || daNonReplaySelector(exceeded.Y) != cap || !daNonReplayCall(branch.Body.List[0], "commit.Abort", "") || !resultOK || len(result.Results) != 2 {
		return false
	}
	zero, zeroOK := result.Results[0].(*ast.CompositeLit)
	return zeroOK && daNonReplaySelector(zero.Type) == "daRelayAdmissionOutcome" && len(zero.Elts) == 0 && daNonReplaySelector(result.Results[1]) == failure
}

func checkDANonReplayPostReserveTail(function *ast.FuncDecl) string {
	calls := map[string]int{}
	ast.Inspect(function.Body, func(node ast.Node) bool {
		call, ok := node.(*ast.CallExpr)
		if ok {
			calls[daNonReplaySelector(call.Fun)]++
		}
		return true
	})
	for name, want := range map[string]int{"admission.BeginCommit": 1, "commit.Abort": 2, "commit.CandidateToken": 1, "s.installDASetRecordLocked": 1, "commit.Commit": 1} {
		if calls[name] != want {
			return fmt.Sprintf("post-reserve call count %s=%d, want %d", name, calls[name], want)
		}
	}
	begin := -1
	for i, statement := range function.Body.List {
		if assignment, ok := statement.(*ast.AssignStmt); ok && len(assignment.Rhs) == 1 {
			if call, ok := assignment.Rhs[0].(*ast.CallExpr); ok && daNonReplaySelector(call.Fun) == "admission.BeginCommit" {
				begin = i
			}
		}
	}
	if begin < 0 || begin+1 >= len(function.Body.List) || !daNonReplayDirectErrorReturn(function.Body.List[begin+1], "err") {
		return "BeginCommit checkpoint missing"
	}
	tail := function.Body.List[begin+2:]
	unsafeAccess := false
	ast.Inspect(&ast.BlockStmt{List: tail}, func(node ast.Node) bool {
		_, index := node.(*ast.IndexExpr)
		_, dereference := node.(*ast.StarExpr)
		unsafeAccess = unsafeAccess || index || dereference
		return !unsafeAccess
	})
	if unsafeAccess || len(tail) != 8 || !daNonReplayCapAbort(tail[0], "projectedOrphanBytes", "orphanCap", "errDARelayOrphanPoolCapExceeded") || !daNonReplayCapAbort(tail[1], "projectedCommitBytes", "commitCap", "errDARelayOrphanCommitCapExceeded") || !daNonReplayTokenAssignment(tail[2]) || !daNonReplayAssignment(tail[3], "placement.record.receivedTime", "receivedTime") || !daNonReplayAssignment(tail[4], "s.nextReceivedTime", "sequence") || !daNonReplayCall(tail[5], "s.installDASetRecordLocked", "placement") || !daNonReplayCall(tail[6], "commit.Commit", "") {
		return "post-reserve tail shape or publication order changed"
	}
	result, ok := tail[7].(*ast.ReturnStmt)
	if !ok || len(result.Results) != 2 || daNonReplaySelector(result.Results[1]) != "nil" {
		return "post-reserve return changed"
	}
	outcome, ok := result.Results[0].(*ast.CompositeLit)
	if !ok || daNonReplaySelector(outcome.Type) != "daRelayAdmissionOutcome" || len(outcome.Elts) != 2 {
		return "post-reserve return outcome is not direct"
	}
	daID, daIDOK := outcome.Elts[0].(*ast.KeyValueExpr)
	disposition, dispositionOK := outcome.Elts[1].(*ast.KeyValueExpr)
	if !daIDOK || !dispositionOK || daNonReplaySelector(daID.Key) != "daID" || daNonReplaySelector(daID.Value) != "candidate.member.locator.daID" || daNonReplaySelector(disposition.Key) != "disposition" || daNonReplaySelector(disposition.Value) != "daRelayAdmissionRetained" {
		return "post-reserve success outcome changed"
	}
	return ""
}

func TestAdmitDANonReplayPostReserveTailIsClosed(t *testing.T) {
	if diagnostic := checkDANonReplayPostReserveTail(daNonReplayFunction(t, "applyDANonReplayPlan")); diagnostic != "" {
		t.Fatal(diagnostic)
	}
	success := "return daRelayAdmissionOutcome{daID: candidate.member.locator.daID, disposition: daRelayAdmissionRetained}, nil"
	valid := "if stateB && projectedOrphanBytes > orphanCap { commit.Abort(); return daRelayAdmissionOutcome{}, errDARelayOrphanPoolCapExceeded }\nif stateB && projectedCommitBytes > commitCap { commit.Abort(); return daRelayAdmissionOutcome{}, errDARelayOrphanCommitCapExceeded }\nmember.token = commit.CandidateToken()\nplacement.record.receivedTime = receivedTime\ns.nextReceivedTime = sequence\ns.installDASetRecordLocked(placement)\ncommit.Commit()\n" + success
	for name, tail := range map[string]string{
		"helper":               "helper()\n" + valid,
		"function literal":     "func() {}()\n" + valid,
		"return IIFE":          strings.Replace(valid, success, "return func() daRelayAdmissionOutcome { return daRelayAdmissionOutcome{} }(), nil", 1),
		"extra success field":  strings.Replace(valid, "disposition: daRelayAdmissionRetained", "disposition: daRelayAdmissionRetained, sameDAIDCommitConflict: s.caps.orphanPoolBytes == 0", 1),
		"extra BeginCommit":    "if false { _, _ = admission.BeginCommit(plan.victims) }\n" + valid,
		"missing global Abort": strings.Replace(valid, "commit.Abort(); return daRelayAdmissionOutcome{}, errDARelayOrphanPoolCapExceeded", "return daRelayAdmissionOutcome{}, errDARelayOrphanPoolCapExceeded", 1),
		"missing commit Abort": strings.Replace(valid, "commit.Abort(); return daRelayAdmissionOutcome{}, errDARelayOrphanCommitCapExceeded", "return daRelayAdmissionOutcome{}, errDARelayOrphanCommitCapExceeded", 1),
		"index lookup":         "_ = placement.install[0]\n" + valid,
		"pointer dereference":  "_ = *member\n" + valid,
		"declaration":          "alias := member\n_ = alias\n" + valid,
		"whole replacement":    "placement.record = next\n" + valid,
		"pointer alias":        "alias := &placement.record\n_ = alias\n" + valid,
		"publication order":    "s.installDASetRecordLocked(placement)\nmember.token = commit.CandidateToken()\nplacement.record.receivedTime = receivedTime\ns.nextReceivedTime = sequence\ncommit.Commit()\n" + success,
	} {
		t.Run(name, func(t *testing.T) {
			if diagnostic := checkDANonReplayPostReserveTail(parseDANonReplayFixture(t, "tail.go", "package node\nfunc (s *DARelayState) apply(admission *DAAdmission) (daRelayAdmissionOutcome, error) {\ncommit, err := admission.BeginCommit(plan.victims)\nif err != nil { return daRelayAdmissionOutcome{}, err }\n"+tail+"\n}")); !strings.Contains(diagnostic, "post-reserve") {
				t.Fatalf("diagnostic=%q, want post-reserve rejection", diagnostic)
			}
		})
	}
}

func publicPeer(t *testing.T, suffix string) DAProvenance {
	t.Helper()
	p, err := NewPeerDAProvenance("peer-"+suffix, "quota-"+suffix)
	if err != nil {
		t.Fatalf("NewPeerDAProvenance: %v", err)
	}
	return p
}

func requirePublicDAResult(t *testing.T, got DAAdmissionResult, err error, want DAAdmissionResult) {
	t.Helper()
	if err != nil || got != want {
		t.Fatalf("AdmitDA=(%+v,%v), want (%+v,nil)", got, err, want)
	}
}

func requirePublicDAFailure(t *testing.T, got DAAdmissionResult, err error, kind TxAdmitErrorKind, message string, disposition ...RelayAdmissionDisposition) {
	t.Helper()
	var admit *TxAdmitError
	if got != (DAAdmissionResult{}) || !errors.As(err, &admit) || admit.Kind != kind || (message != "" && admit.Message != message) || len(disposition) != 0 && relayDispositionOf(err) != disposition[0] {
		t.Fatalf("AdmitDA=(%+v,%v) disposition=%v, want zero %s %q disposition=%v", got, err, relayDispositionOf(err), kind, message, disposition)
	}
}

func requirePublicDAInternal(t *testing.T, f *daNonReplayFixture, got DAAdmissionResult, err error) {
	t.Helper()
	requirePublicDAFailure(t, got, err, TxAdmitRejected, errDARelayImageIncompatible.Error(), RelayAdmissionInternal)
	if !f.state.admissionMu.TryLock() {
		t.Fatalf("internal result=(%+v,%v) disposition=%v or leaked guard", got, err, relayDispositionOf(err))
	}
	f.state.admissionMu.Unlock()
}

func TestAdmitDAPublicAPISurfaceIsClosedAndDormant(t *testing.T) {
	if _, err := NewPeerDAProvenance("", "quota"); err != errDAProvenanceInvalid { //nolint:errorlint // Exact direct sentinel identity is part of the public constructor contract.
		t.Fatalf("empty peer constructor error=%v", err)
	}
	if _, err := NewPeerDAProvenance("peer", ""); err != errDAProvenanceInvalid { //nolint:errorlint // Exact direct sentinel identity is part of the public constructor contract.
		t.Fatalf("empty quota constructor error=%v", err)
	}
	for _, provenance := range []DAProvenance{LocalDAProvenance(), DetachedReorgDAProvenance(), publicPeer(t, "surface")} {
		if err := provenance.validate(); err != nil {
			t.Fatalf("valid public provenance=%+v err=%v", provenance, err)
		}
	}
	if err := (DAProvenance{}).validate(); err != errDAProvenanceInvalid { //nolint:errorlint // Exact direct sentinel identity is part of the closed provenance domain.
		t.Fatalf("zero provenance error=%v", err)
	}
	provenanceType := reflect.TypeOf(DAProvenance{})
	for i := 0; i < provenanceType.NumField(); i++ {
		if provenanceType.Field(i).IsExported() {
			t.Fatalf("DAProvenance exposes %s", provenanceType.Field(i).Name)
		}
	}
	if DAAdmissionRetained != DAAdmissionDisposition(1) || DAAdmissionDuplicate != DAAdmissionDisposition(2) {
		t.Fatalf("public disposition values=(%d,%d)", DAAdmissionRetained, DAAdmissionDuplicate)
	}
	for _, relay := range []*DARelayState{nil, {}, {mempool: &Mempool{}}, {mempool: &Mempool{chainState: &ChainState{}}}} {
		got, err := relay.AdmitDA(nil, LocalDAProvenance())
		requirePublicDAFailure(t, got, err, TxAdmitUnavailable, "", RelayAdmissionUnavailable)
	}
	f := newDANonReplayFixture(t, 1)
	tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x90}, payload: []byte("surface")})
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	got, err := f.relay.AdmitDA(nil, DAProvenance{})
	requirePublicDAFailure(t, got, err, TxAdmitRejected, "invalid da provenance", RelayAdmissionStableTerminalReject)
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	got, err = f.relay.AdmitDA(nil, LocalDAProvenance())
	requirePublicDAFailure(t, got, err, TxAdmitRejected, "empty DA transaction", RelayAdmissionStableTerminalReject)
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	got, err = f.relay.AdmitDA(tx.raw, DAProvenance{})
	requirePublicDAFailure(t, got, err, TxAdmitRejected, "invalid da provenance", RelayAdmissionStableTerminalReject)
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	got, err = publicDAAdmissionResult(daRelayAdmissionOutcome{})
	requirePublicDAFailure(t, got, err, TxAdmitRejected, errDARelayImageIncompatible.Error(), RelayAdmissionInternal)

	if source, err := os.ReadFile("da_relay_owner.go"); err != nil || bytes.Contains(source, []byte("LookupRetainedTx")) || bytes.Contains(source, []byte("DARetainedTxSnapshot")) {
		t.Fatalf("forbidden retained API source err=%v", err)
	}
	requireDAAdmissionStructure(t)
	TestDAAdmissionCandidateClosedDomain(t)
}

func TestAdmitDAOwnerObservationPrecedesCandidateIntegrity(t *testing.T) {
	unavailable := func(f *daNonReplayFixture, tx daNonReplayTx, suffix, message string) {
		got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, suffix))
		requirePublicDAFailure(t, got, err, TxAdmitUnavailable, message, RelayAdmissionUnavailable)
		if !f.state.admissionMu.TryLock() {
			t.Fatal("unavailable observation leaked guard or changed class")
		}
		f.state.admissionMu.Unlock()
	}
	rows := []struct {
		name     string
		output   [][]byte
		wantErr  error
		wantKind TxAdmitErrorKind
		msg      string
	}{
		{"zero CORE_DA_COMMIT outputs", nil, errDARelayMemberIncomplete, "", ""},
		{"two valid CORE_DA_COMMIT outputs", [][]byte{make([]byte, 32), make([]byte, 32)}, errDARelayMemberIncomplete, "", ""},
		{"31-byte CORE_DA_COMMIT", [][]byte{make([]byte, 31)}, nil, TxAdmitRejected, "TX_ERR_COVENANT_TYPE_INVALID: invalid CORE_DA_COMMIT covenant_data length"},
		{"33-byte CORE_DA_COMMIT", [][]byte{make([]byte, 33)}, nil, TxAdmitRejected, "TX_ERR_COVENANT_TYPE_INVALID: invalid CORE_DA_COMMIT covenant_data length"},
	}
	for _, row := range rows {
		t.Run(row.name+" absent", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x91, byte(len(row.name))}, chunkCount: 2, literalCommitmentOutputs: true, commitmentOutputData: row.output})
			parsed, _, _, consumed, err := consensus.ParseTx(tx.raw)
			if err != nil || consumed != len(tx.raw) {
				t.Fatalf("independent ParseTx=(%d,%v)", consumed, err)
			}
			count := 0
			for _, output := range parsed.Outputs {
				if output.CovenantType == 0x0103 {
					if count >= len(row.output) || len(output.CovenantData) != len(row.output[count]) {
						t.Fatalf("literal CORE_DA_COMMIT output[%d] width=%d", count, len(output.CovenantData))
					}
					count++
				}
			}
			if count != len(row.output) {
				t.Fatalf("literal CORE_DA_COMMIT count=%d want=%d", count, len(row.output))
			}
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, row.name))
			if row.wantErr != nil {
				if got != (DAAdmissionResult{}) || err != row.wantErr { //nolint:errorlint // Exact direct renderer sentinel identity is contract-owned.
					t.Fatalf("AdmitDA=(%+v,%v), want zero %v", got, err, row.wantErr)
				}
			} else {
				requirePublicDAFailure(t, got, err, row.wantKind, row.msg)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
		})
		t.Run(row.name+" unavailable", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x92, byte(len(row.name))}, chunkCount: 2, literalCommitmentOutputs: true, commitmentOutputData: row.output})
			f.mutateRelay(func(s *DARelayState) { s.sets = nil })
			unavailable(f, tx, "unavailable"+row.name, "DA relay owner maps unavailable")
		})
		t.Run(row.name+" located INTERNAL", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0x95, byte(len(row.name))}, chunkCount: 2, literalCommitmentOutputs: true, commitmentOutputData: row.output})
			recordID := [32]byte{0x96, byte(len(row.name))}
			f.mutateRelay(func(s *DARelayState) {
				s.sets[recordID] = daRelaySetRecord{daID: recordID, state: daRelayStateOrphanChunks, revision: 1, receivedTime: 1, ttlBlocksRemaining: 1}
				s.locators[tx.txid] = daRelayLocator{daID: recordID, kind: daRelayLocatorChunk}
			})
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, "internal"+row.name))
			requirePublicDAInternal(t, f, got, err)
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
		})
	}
	for _, maps := range []func(*DARelayState){func(s *DARelayState) { s.sets = nil }, func(s *DARelayState) { s.locators = nil }} {
		f := newDANonReplayFixture(t, 1)
		bad := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x94}, payload: []byte("public replay chunk"), literalChunkHash: true, chunkHash: [32]byte{0xff}})
		maps(f.relay)
		unavailable(f, bad, "chunk-map", "DA relay owner maps unavailable")
	}
	t.Run("chunk hash mismatch after ABSENT", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		bad := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x97}, payload: []byte("public replay chunk"), literalChunkHash: true, chunkHash: [32]byte{0xff}})
		relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		got, err := f.relay.AdmitDA(bad.raw, publicPeer(t, "chunk-absent"))
		requirePublicDAFailure(t, got, err, TxAdmitRejected, "DA chunk payload hash mismatch", RelayAdmissionStableTerminalReject)
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	})
	t.Run("located corruption outranks chunk hash mismatch", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		bad := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x98}, payload: []byte("public replay chunk"), literalChunkHash: true, chunkHash: [32]byte{0xff}})
		recordID := [32]byte{0x99}
		f.mutateRelay(func(s *DARelayState) {
			s.sets[recordID] = daRelaySetRecord{daID: recordID, state: daRelayStateOrphanChunks, revision: 1, receivedTime: 1, ttlBlocksRemaining: 1}
			s.locators[bad.txid] = daRelayLocator{daID: recordID, kind: daRelayLocatorChunk}
		})
		relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		got, err := f.relay.AdmitDA(bad.raw, publicPeer(t, "chunk-internal"))
		requirePublicDAInternal(t, f, got, err)
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	})
	for _, row := range []struct {
		name, message string
		mutate        func(*PendingOutpointOwner)
	}{
		{"transition", "pending-outpoint owner admission context unavailable", func(owner *PendingOutpointOwner) { owner.inTransition = true }},
		{"generation exhausted", "pending-outpoint owner admission context unavailable", func(owner *PendingOutpointOwner) { owner.generation = ^uint64(0) }},
		{"stable tip mismatch", "pending-outpoint owner tip does not match the guarded chainstate tip", func(owner *PendingOutpointOwner) { owner.stableTip.Height++ }},
	} {
		t.Run("owner context "+row.name+" wins", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			bad := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x9a, byte(len(row.name))}, payload: []byte("public replay chunk"), literalChunkHash: true, chunkHash: [32]byte{0xff}})
			f.mutateRelay(func(s *DARelayState) { s.sets = nil })
			f.mp.pendingOutpoints.mu.Lock()
			row.mutate(f.mp.pendingOutpoints)
			f.mp.pendingOutpoints.mu.Unlock()
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			unavailable(f, bad, row.name, row.message)
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
		})
	}
	t.Run("real nonexact snapshot panic closes admission guard", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0x9b}, payload: []byte("nonexact-panic")})
		owned, parsed, txid, wtxid, inputs, err := parseDAAdmissionCandidate(tx.raw)
		if err != nil {
			t.Fatal(err)
		}
		hold, err := f.mp.acquireDAAdmissionHold(f.mp.pendingOutpoints, inputs)
		if err != nil {
			t.Fatal(err)
		}
		hold.guard.state.Store(daAdmissionResolved)
		var recovered any
		func() {
			defer func() { recovered = recover() }()
			_, _ = f.relay.admitDANonExact(hold, owned, parsed, txid, wtxid, inputs, publicPeer(t, "nonexact-panic"))
		}()
		if recovered != "DA admission snapshot is not available" {
			t.Fatalf("recovered=%v", recovered)
		}
		if !f.state.admissionMu.TryLock() {
			t.Fatal("real nonexact panic leaked admission guard")
		}
		f.state.admissionMu.Unlock()
	})
}

func TestAdmitDAD00R3ReplayMatrix(t *testing.T) {
	for _, row := range []struct {
		name  string
		tx    daNonReplayTxSpec
		clear bool
	}{
		{"A chunk", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xa0}, payload: []byte("replay-a")}, false},
		{"B commit", daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0xb0}, chunkCount: 2, commitment: [32]byte{0xa5}, commitmentOutputs: 1}, false},
		{"exact ignores installer accounting", daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xa5}, payload: []byte("exact")}, true},
	} {
		t.Run(row.name+" exact replay", func(t *testing.T) {
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(row.tx)
			f.admit(tx, daNonReplayPeer("resident"))
			if row.clear {
				f.mutateRelay(func(s *DARelayState) { s.orphanBytesByPeerQuotaKey, s.orphanBytesByDAID = nil, nil })
			}
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, row.name))
			requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: tx.spec.daID, Disposition: DAAdmissionDuplicate})
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
			if !f.state.admissionMu.TryLock() {
				t.Fatal("exact replay leaked admission guard")
			}
			f.state.admissionMu.Unlock()
		})
	}
	t.Run("ABSENT retains through the established path", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xa1}, payload: []byte("absent")})
		provenance, err := NewPeerDAProvenance("boundary", "boundary")
		if err != nil {
			t.Fatal(err)
		}
		got, err := f.relay.AdmitDA(tx.raw, provenance)
		requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: tx.spec.daID, Disposition: DAAdmissionRetained})
		f.requireSingleRetained(t, tx, daRelayStateOrphanChunks)
	})
	t.Run("valid NONEXACT resumes the existing duplicate path", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xa3}, payload: []byte("nonexact")})
		f.admit(tx, daNonReplayPeer("resident"))
		parsed, _, _, consumed, err := consensus.ParseTx(tx.raw)
		if err != nil || consumed != len(tx.raw) {
			t.Fatalf("independent ParseTx=(%d,%v)", consumed, err)
		}
		if err := consensus.SignTransaction(parsed, f.state.Utxos, devnetGenesisChainID, f.signer); err != nil {
			t.Fatalf("alternate SignTransaction: %v", err)
		}
		alternate := mustMarshalTxForNodeTest(t, parsed)
		_, alternateTxID, alternateWTxID, consumed, err := consensus.ParseTx(alternate)
		if err != nil || consumed != len(alternate) || alternateTxID != tx.txid || alternateWTxID == tx.wtxid {
			t.Fatalf("alternate identifiers=(%x,%x,%d,%v), want same txid and distinct wtxid", alternateTxID, alternateWTxID, consumed, err)
		}
		relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		got, err := f.relay.AdmitDA(alternate, publicPeer(t, "nonexact"))
		requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: tx.spec.daID, Disposition: DAAdmissionDuplicate})
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	})
	t.Run("observation is alias-isolated", func(t *testing.T) {
		f := newDANonReplayFixture(t, 1)
		tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xa2}, payload: []byte("alias")})
		f.admit(tx, daNonReplayPeer("resident"))
		before := daRelayStateSnapshot(f.relay)
		liveVout := f.relay.sets[tx.spec.daID].chunks[0].member.inputs[0].Vout
		observation := f.relay.observeDAAdmission(tx.txid)
		observation.candidate.member.txBytes[0] ^= 0xff
		observation.candidate.member.payload[0] ^= 0xff
		observation.candidate.member.member.inputs[0].Vout++
		if got := daRelayStateSnapshot(f.relay); !reflect.DeepEqual(got, before) || f.relay.sets[tx.spec.daID].chunks[0].member.inputs[0].Vout != liveVout { //nolint:govet // Complete private state-image equality requires structural comparison, including nested alias isolation.
			t.Fatalf("observation leaked alias: got=%+v want=%+v", got, before)
		}
	})
}

func TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict(t *testing.T) {
	const (
		aChunk = iota
		bCommit
		bChunk
		cCommit
		cChunk
	)
	type row struct {
		name   string
		role   int
		drop   bool
		mutate func(*daRelaySetRecord, *daRelayCommit, *daRelayChunk)
	}
	setup := func(role int) (*daNonReplayFixture, daNonReplayTx) {
		daID := [32]byte{0xb1, byte(role)}
		switch role {
		case aChunk:
			f := newDANonReplayFixture(t, 2)
			tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, payload: []byte("corrupt-a"), inputCount: 2})
			f.admit(tx, daNonReplayPeer("resident"))
			return f, tx
		case bCommit:
			f := newDANonReplayFixture(t, 2)
			tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0xa5}, commitmentOutputs: 1, inputCount: 2})
			f.admit(tx, daNonReplayPeer("resident"))
			return f, tx
		case cCommit, cChunk:
			f := newDANonReplayFixture(t, 2)
			return f, f.completeReplay(daID, uint8(role-cCommit+1))
		default:
			f := newDANonReplayFixture(t, 4)
			f.admit(f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0xa6}, commitmentOutputs: 1, inputCount: 2}), daNonReplayPeer("commit"))
			tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("corrupt-b"), inputCount: 2})
			f.admit(tx, daNonReplayPeer("chunk"))
			return f, tx
		}
	}
	for _, role := range []int{bChunk, cCommit, cChunk} {
		f, tx := setup(role)
		relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, "complete"))
		requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: tx.spec.daID, Disposition: DAAdmissionDuplicate})
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	}
	for _, row := range []row{
		{"dangling locator", aChunk, true, nil},
		{"missing chunk member", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.member = nil }},
		{"missing commit member", bCommit, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.member = nil }},
		{"zero revision", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.revision = 0 }},
		{"zero received time", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.receivedTime = 0 }},
		{"zero ttl", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.ttlBlocksRemaining = 0 }},
		{"invalid chunk state", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.state = daRelayStateCompleteSet }},
		{"invalid commit role", bCommit, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.state = daRelayStateOrphanChunks }},
		{"invalid staged chunk role", bChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.state = daRelayStateOrphanChunks }},
		{"missing retained raw", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.txBytes = nil }},
		{"truncated retained raw", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.txBytes = c.txBytes[:len(c.txBytes)-1] }},
		{"trailing retained raw", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.txBytes = append(c.txBytes, 0) }},
		{"indexed member txid", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.member.txid[0] ^= 1 }},
		{"admission wtxid", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.member.wtxid[0] ^= 1 }},
		{"commit slot daid", bCommit, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.daID[0] ^= 1 }},
		{"chunk slot daid", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.daID[0] ^= 1 }},
		{"chunk slot index", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.chunkIndex++ }},
		{"ordered inputs", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) {
			c.member.inputs[0], c.member.inputs[1] = c.member.inputs[1], c.member.inputs[0]
		}},
		{"retained provenance", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.member.provenance = DAProvenance{} }},
		{"retained payload", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.payload = []byte("other") }},
		{"retained hash", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.chunkHash = [32]byte{0xee} }},
		{"record payload residual", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.payloadBytes = 1 }},
		{"record wire residual", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.wireBytes = 1 }},
		{"record replaceable residual", aChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.replaceableChunks = map[uint16]bool{} }},
		{"target wire residual", bChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.wireBytes = 1 }},
		{"target peer residual", bChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.peerQuotaKey = "moved" }},
		{"target hash checked residual", bChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.hashChecked = !c.hashChecked }},
		{"orphan commit commitment residual", aChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.payloadCommitment[0] = 1 }},
		{"staged commit daid", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.daID[0] ^= 1 }},
		{"staged commit count", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.chunkCount = 0 }},
		{"staged commit wire", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.wireBytes = 1 }},
		{"staged commit peer", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.peerQuotaKey = "moved" }},
		{"staged commit raw", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.txBytes = nil }},
		{"missing staged member", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.member = nil }},
		{"staged commit count above max", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) {
			c.chunkCount = uint16(consensus.MAX_DA_CHUNK_COUNT + 1)
		}},
		{"staged target index outside count", bChunk, false, func(_ *daRelaySetRecord, c *daRelayCommit, _ *daRelayChunk) { c.chunkCount = 1 }},
		{"zero token sequence", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.member.token.seq = 0 }},
		{"foreign token", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) {
			c.member.token = PendingOutpointToken{owner: newPendingOutpointOwner(PendingOutpointTip{}), seq: 1}
		}},
		{"partial token", aChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) {
			c.member.token = PendingOutpointToken{seq: 1}
		}},
		{"C nonzero ttl", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.ttlBlocksRemaining = 1 }},
		{"C zero retained bytes", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.wireBytes = 0 }},
		{"C zero payload bytes", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.payloadBytes = 0 }},
		{"C replaceable", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.replaceableChunks = map[uint16]bool{} }},
		{"C stored payload", cChunk, false, func(_ *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { c.payload = []byte{} }},
		{"C retained bytes below raw", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { r.wireBytes = uint64(len(c.txBytes) - 1) }},
		{"C payload bytes below raw payload", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) { r.payloadBytes = 1 }},
		{"C commit retained bytes equal raw", cCommit, false, func(r *daRelaySetRecord, _ *daRelayCommit, _ *daRelayChunk) {
			r.wireBytes = uint64(len(r.commit.txBytes))
		}},
		{"C chunk retained bytes equal raw", cChunk, false, func(r *daRelaySetRecord, _ *daRelayCommit, c *daRelayChunk) { r.wireBytes = uint64(len(c.txBytes)) }},
	} {
		t.Run(row.name, func(t *testing.T) {
			f, tx := setup(row.role)
			f.mutateRelay(func(s *DARelayState) {
				if row.drop {
					delete(s.sets, tx.spec.daID)
					return
				}
				r := s.sets[tx.spec.daID]
				c := r.chunks[tx.spec.chunkIndex]
				row.mutate(&r, &r.commit, &c)
				if tx.spec.kind == 0x02 {
					r.chunks[tx.spec.chunkIndex] = c
				}
				s.sets[tx.spec.daID] = r
			})
			relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, row.name))
			requirePublicDAInternal(t, f, got, err)
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
		})
	}
}

func TestConflictBitRequiresAProvenDifferentTxid(t *testing.T) {
	f := newDANonReplayFixture(t, 2)
	daID, commitment := [32]byte{0xc1}, [32]byte{0xa5}
	resident := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: commitment, commitmentOutputs: 1})
	f.admit(resident, daNonReplayPeer("resident"))
	candidate := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: commitment, commitmentOutputs: 1})
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	got, err := f.relay.AdmitDA(candidate.raw, publicPeer(t, "conflict"))
	requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: daID, Disposition: DAAdmissionDuplicate, SameDAIDCommitConflict: true})
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	got, err = f.relay.AdmitDA(resident.raw, publicPeer(t, "exact"))
	requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: daID, Disposition: DAAdmissionDuplicate})
}

// daCompanionRecordFixture builds ONE State B or State C set holding both a
// commit and a chunk, and returns the fixture with the requested target.
func daCompanionRecordFixture(t *testing.T, complete bool, kind uint8, daID [32]byte) (*daNonReplayFixture, daNonReplayTx) {
	t.Helper()
	f := newDANonReplayFixture(t, 8)
	if complete {
		return f, f.completeReplay(daID, kind)
	}
	commit := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: 2, commitment: [32]byte{0xa6}, commitmentOutputs: 1, inputCount: 2})
	f.admit(commit, daNonReplayPeer("commit"))
	chunk := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: 1, payload: []byte("companion"), inputCount: 2})
	f.admit(chunk, daNonReplayPeer("chunk"))
	if kind == 0x01 {
		return f, commit
	}
	return f, chunk
}

func requireExactDADuplicate(t *testing.T, f *daNonReplayFixture, tx daNonReplayTx) {
	t.Helper()
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, "companion-exact"))
	requirePublicDAResult(t, got, err, DAAdmissionResult{DAID: tx.spec.daID, Disposition: DAAdmissionDuplicate})
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
	if !f.state.admissionMu.TryLock() {
		t.Fatal("exact replay leaked the admission guard")
	}
	f.state.admissionMu.Unlock()
}

func requireInternalDAReplay(t *testing.T, f *daNonReplayFixture, tx daNonReplayTx) {
	t.Helper()
	relayBefore, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, "companion-internal"))
	requirePublicDAInternal(t, f, got, err)
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, relayBefore, ownerBefore)
}

// TestAdmitDAChunkReplayValidatesBoundedCompanionCommit drives every row with
// the BYTE-EXACT retained target, so a defect that compares bytes before
// validating the companion returns DUPLICATE instead of the required INTERNAL.
// Expected identities come from consensus.ParseTx over the fixture's own bytes,
// never from the observation under test.
func TestAdmitDAChunkReplayValidatesBoundedCompanionCommit(t *testing.T) {
	states := []struct {
		name     string
		complete bool
		daID     [32]byte
	}{{"state B", false, [32]byte{0xd1}}, {"state C", true, [32]byte{0xd2}}}
	for _, state := range states {
		t.Run(state.name+" exact chunk replay accepts its bound companion", func(t *testing.T) {
			f, chunk := daCompanionRecordFixture(t, state.complete, 0x02, state.daID)
			requireExactDADuplicate(t, f, chunk)
		})
		t.Run(state.name+" commit target validates only its own member", func(t *testing.T) {
			f, commit := daCompanionRecordFixture(t, state.complete, 0x01, state.daID)
			f.mutateRelay(func(s *DARelayState) {
				record := s.sets[state.daID]
				for index, chunk := range record.chunks {
					chunk.member.txid[0] ^= 1
					record.chunks[index] = chunk
				}
				s.sets[state.daID] = record
			})
			requireExactDADuplicate(t, f, commit)
		})
	}
	for _, row := range []struct {
		name   string
		mutate func(*daNonReplayFixture, daNonReplayTx, *daRelayCommit)
	}{
		// inherited: killed by validateStagedCommit before validateCompanionCommit runs; kept so the companion path never reopens them.
		{"inherited: absent companion member", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.member = nil }},
		{"inherited: empty companion raw", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.txBytes = nil }},
		{"inherited: companion zero chunk count scalar", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.chunkCount = 0 }},
		{"inherited: companion chunk count above max", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.chunkCount = uint16(consensus.MAX_DA_CHUNK_COUNT + 1)
		}},
		{"truncated companion raw", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.txBytes = slices.Clone(c.txBytes[:len(c.txBytes)-1])
		}},
		{"trailing companion raw", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.txBytes = append(slices.Clone(c.txBytes), 0)
		}},
		{"companion raw is a chunk", func(_ *daNonReplayFixture, chunk daNonReplayTx, c *daRelayCommit) {
			c.txBytes = slices.Clone(chunk.raw)
		}},
		{"companion raw is another commit", func(f *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.txBytes = slices.Clone(f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0xd9}, chunkCount: 2, commitment: [32]byte{0xa7}, commitmentOutputs: 1}).raw)
		}},
		{"companion chunk count scalar", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.chunkCount += 2 }},
		{"companion payload commitment scalar", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.payloadCommitment[0] ^= 1 }},
		{"companion txid", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.member.txid[0] ^= 1 }},
		{"companion admission wtxid", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.member.wtxid[0] ^= 1 }},
		{"companion ordered inputs", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.member.inputs = append([]consensus.Outpoint{{Txid: [32]byte{0x7f}}}, c.member.inputs...)
		}},
		// Zeroing invalidates the provenance KIND; a valid-but-different provenance is undetectable by design, as on the target path.
		{"companion provenance kind invalid", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) { c.member.provenance = DAProvenance{} }},
		{"companion zero token", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.member.token = PendingOutpointToken{}
		}},
		{"companion foreign token", func(_ *daNonReplayFixture, _ daNonReplayTx, c *daRelayCommit) {
			c.member.token = PendingOutpointToken{owner: newPendingOutpointOwner(PendingOutpointTip{}), seq: 1}
		}},
	} {
		for _, state := range states {
			t.Run(row.name+" "+state.name, func(t *testing.T) {
				f, chunk := daCompanionRecordFixture(t, state.complete, 0x02, state.daID)
				f.mutateRelay(func(s *DARelayState) {
					record := s.sets[state.daID]
					row.mutate(f, chunk, &record.commit)
					s.sets[state.daID] = record
				})
				requireInternalDAReplay(t, f, chunk)
			})
		}
	}
	t.Run("an invalid target outranks a valid companion", func(t *testing.T) {
		f, chunk := daCompanionRecordFixture(t, false, 0x02, [32]byte{0xd5})
		f.mutateRelay(func(s *DARelayState) {
			record := s.sets[chunk.spec.daID]
			target := record.chunks[chunk.spec.chunkIndex]
			target.payload = []byte("other")
			record.chunks[chunk.spec.chunkIndex] = target
			s.sets[chunk.spec.daID] = record
		})
		requireInternalDAReplay(t, f, chunk)
	})
	t.Run("state A chunk keeps the exact empty companion tuple", func(t *testing.T) {
		f := newDANonReplayFixture(t, 2)
		chunk := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xd3}, payload: []byte("orphan companion")})
		f.admit(chunk, daNonReplayPeer("chunk"))
		requireExactDADuplicate(t, f, chunk)
		f.mutateRelay(func(s *DARelayState) {
			record := s.sets[chunk.spec.daID]
			record.commit.txBytes = slices.Clone(chunk.raw)
			s.sets[chunk.spec.daID] = record
		})
		// State A copies no companion, whatever its empty commit slot holds.
		if observation := f.relay.observeDAAdmission(chunk.txid); !reflect.DeepEqual(observation.companion, daRelayAdmissionCandidate{}) {
			t.Fatalf("state A chunk target copied a companion: %+v", observation.companion)
		}
		requireInternalDAReplay(t, f, chunk)
	})
	t.Run("companion copy is alias isolated", func(t *testing.T) {
		f, chunk := daCompanionRecordFixture(t, false, 0x02, [32]byte{0xd4})
		before := daRelayStateSnapshot(f.relay)
		observation := f.relay.observeDAAdmission(chunk.txid)
		copied := slices.Clone(observation.companion.member.txBytes)
		if len(copied) == 0 || len(observation.companion.member.member.inputs) == 0 {
			t.Fatal("a State B chunk target copied no companion commit")
		}
		observation.companion.member.txBytes[0] ^= 0xff
		observation.companion.member.member.inputs[0].Vout++
		if got := daRelayStateSnapshot(f.relay); !reflect.DeepEqual(got, before) { //nolint:govet // Complete private state-image equality requires structural comparison.
			t.Fatalf("mutating the companion copy reached live state: got=%+v want=%+v", got, before)
		}
		f.mutateRelay(func(s *DARelayState) { s.sets[chunk.spec.daID].commit.txBytes[0] ^= 0xff })
		observation.companion.member.txBytes[0] ^= 0xff
		if !bytes.Equal(observation.companion.member.txBytes, copied) {
			t.Fatal("mutating live retained bytes reached the companion copy")
		}
	})
	// White-box rows edit the observation copy directly, so each isolates ONE
	// conjunct of validateCompanionCommit no live-record mutation reaches alone:
	// the staged twins share their source with the companion, and validateHeader
	// stops any undeclared record state first.
	t.Run("white-box: companion twins and state gate", func(t *testing.T) {
		f, chunk := daCompanionRecordFixture(t, false, 0x02, [32]byte{0xd6})
		owner := f.mp.pendingOutpoints
		// A self-consistent commit of ANOTHER da_id: every companion-internal
		// binding holds, only the record-level da_id twin can refuse it.
		foreign := f.signed(daNonReplayTxSpec{kind: 0x01, daID: [32]byte{0xd7}, chunkCount: 2, commitment: [32]byte{0xa6}, commitmentOutputs: 1, inputCount: 2})
		for _, row := range []struct {
			name   string
			direct bool
			mutate func(*daAdmissionObservation)
		}{
			{"staged chunk count twin", false, func(o *daAdmissionObservation) { o.stagedCommitChunkCount++ }},
			{"staged payload commitment twin", false, func(o *daAdmissionObservation) { o.stagedCommitPayloadCommitment[0] ^= 1 }},
			{"staged da_id twin against a foreign self-consistent companion", false, func(o *daAdmissionObservation) {
				o.companion.member.locator.daID, o.companion.member.txBytes = foreign.spec.daID, slices.Clone(foreign.raw)
				o.companion.member.member.txid, o.companion.member.member.wtxid, o.companion.member.member.inputs = foreign.txid, foreign.wtxid, slices.Clone(foreign.inputs)
			}},
			{"chunk target in an undeclared record state", true, func(o *daAdmissionObservation) { o.recordState = 7 }},
		} {
			t.Run(row.name, func(t *testing.T) {
				observation := f.relay.observeDAAdmission(chunk.txid)
				if err := observation.validateDAAdmissionObservation(owner); err != nil {
					t.Fatalf("unedited observation=%v", err)
				}
				row.mutate(&observation)
				validate := observation.validateDAAdmissionObservation
				if row.direct {
					validate = observation.validateCompanionCommit
				}
				if err := validate(owner); err != errDARelayImageIncompatible { //nolint:errorlint // Exact direct sentinel identity is the internal contract.
					t.Fatalf("%s=%v, want errDARelayImageIncompatible", row.name, err)
				}
			})
		}
	})
}

// TestAdmitDAOutcomeOrderAndLocalCallerCensus pins the two orders this slice
// owns — target before companion, observation before the exact byte comparison —
// proves the companion decision reads only its copied evidence, proves every
// error return of the shared parsed-candidate path either leaves a disposition
// its own branch selected or is validateDACandidate's fail-closed nil-hold
// sentinel, which AdmitDA never reaches, and proves the whole surface still has
// exactly its live census: remote, local and detached-reorg production callers.
func TestAdmitDAOutcomeOrderAndLocalCallerCensus(t *testing.T) {
	declaredFunctions := func(path string) map[string]*ast.FuncDecl {
		file, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
		if err != nil {
			t.Fatalf("parse %s: %v", path, err)
		}
		out := map[string]*ast.FuncDecl{}
		for _, declaration := range file.Decls {
			if function, ok := declaration.(*ast.FuncDecl); ok {
				out[function.Name.Name] = function
			}
		}
		return out
	}
	calleeName := func(call *ast.CallExpr) string {
		switch function := call.Fun.(type) {
		case *ast.Ident:
			return function.Name
		case *ast.SelectorExpr:
			return function.Sel.Name
		}
		return ""
	}
	calledNames := func(node ast.Node, wanted ...string) []string {
		var order []string
		ast.Inspect(node, func(node ast.Node) bool {
			if call, ok := node.(*ast.CallExpr); ok && slices.Contains(wanted, calleeName(call)) {
				order = append(order, calleeName(call))
			}
			return true
		})
		return order
	}
	// ORDER 1: the target's own retained validation runs first, and the companion
	// step is the observation validator's final statement.
	observed := daNonReplayFunction(t, "validateDAAdmissionObservation")
	retainedAt, companionAt := -1, -1
	for i, statement := range observed.Body.List {
		for _, name := range calledNames(statement, "validateRetained", "validateCompanionCommit") {
			if name == "validateRetained" {
				retainedAt = i
			} else {
				companionAt = i
			}
		}
	}
	if retainedAt < 0 || companionAt <= retainedAt || companionAt != len(observed.Body.List)-1 {
		t.Fatalf("target/companion statement order=%d/%d of %d", retainedAt, companionAt, len(observed.Body.List))
	}
	// ORDER 2: the observation is validated before the exact byte comparison, and
	// each happens exactly once.
	if order := calledNames(daNonReplayFunction(t, "classifyDAReplay").Body, "validateDAAdmissionObservation", "Equal"); !slices.Equal(order, []string{"validateDAAdmissionObservation", "Equal"}) {
		t.Fatalf("replay classification order=%v", order)
	}
	// BOUNDED SOURCE: the companion decision reads its copied evidence only. The
	// identifier and range guard is body-local, not transitive: it trusts the
	// callees those bodies name (parseRelayMetadataTx, renderDACommitAdmissionCandidate
	// with daAdmissionPayloadCommitment, sameDAAdmissionCandidate, validateToken,
	// checkOwnerReadyRetainedBytes, isDAAdmissionTx, relayMetadataInputs,
	// daRelayMemberIdentity.clone), each of which reads only its arguments.
	for _, name := range []string{"validateCompanionCommit", "captureDAAdmissionCommit"} {
		function := daNonReplayFunction(t, name)
		ast.Inspect(function.Body, func(node ast.Node) bool {
			if _, ranged := node.(*ast.RangeStmt); ranged {
				t.Fatalf("%s ranges over live state", name)
			}
			if identifier, ok := node.(*ast.Ident); ok && slices.Contains([]string{
				"sets", "locators", "chunks", "byToken", "byOutpoint", "claimForToken", "claimForTokenLocked",
				"Lock", "Unlock", "mu", "observeDAAdmission", "parseDAAdmissionCandidate", "AdmissionContext",
			}, identifier.Name) {
				t.Fatalf("%s reads %s outside the copied observation", name, identifier.Name)
			}
			return true
		})
	}
	// ORIGINATING DISPOSITIONS: every error a shared parsed-candidate branch
	// returns is either stamped at that branch or produced by a helper that
	// stamps at its own. The last result of every return is pinned in order.
	returnShapes := func(function *ast.FuncDecl) []string {
		var shapes []string
		ast.Inspect(function.Body, func(node ast.Node) bool {
			returned, ok := node.(*ast.ReturnStmt)
			if !ok || len(returned.Results) == 0 {
				return true
			}
			last := returned.Results[len(returned.Results)-1]
			// stamped:<helper> when the branch's own classifier call selected the
			// disposition, stamped=<constant> when the site names it literally.
			if stamp, ok := last.(*ast.CallExpr); ok && calleeName(stamp) == "selectRelayDisposition" && len(stamp.Args) == 2 {
				if helper, ok := stamp.Args[1].(*ast.CallExpr); ok {
					shapes = append(shapes, "stamped:"+calleeName(helper))
				} else if constant, ok := stamp.Args[1].(*ast.Ident); ok {
					shapes = append(shapes, "stamped="+constant.Name)
				} else {
					shapes = append(shapes, fmt.Sprintf("stamped?%T", stamp.Args[1]))
				}
				return true
			}
			if identifier, ok := last.(*ast.Ident); ok {
				shapes = append(shapes, identifier.Name)
				return true
			}
			shapes = append(shapes, fmt.Sprintf("%T", last))
			return true
		})
		return shapes
	}
	unavailable, terminal := "stamped=RelayAdmissionUnavailable", "stamped=RelayAdmissionStableTerminalReject"
	simplicity := "stamped:relayDispositionForSimplicityPreActivationOutcome"
	for _, row := range []struct {
		path, name string
		want       []string
	}{
		{"mempool.go", "checkParsedTransactionWithSnapshot", []string{"err", unavailable, "err", "err", "err", "stamped:relayDispositionForPolicyError", "nil"}},
		{"mempool.go", "rejectSimplicityPreActivationLane", []string{"nil", simplicity, simplicity, "nil"}},
		{"mempolicy_helpers.go", "validateChainSnapshot", []string{unavailable, unavailable, "nil"}},
		{"mempolicy_helpers.go", "validateTransactionWithConsensus", []string{"stamped:relayDispositionForConsensusError", "nil"}},
		{"mempool_precheck.go", "buildPolicyInputSnapshotIfNeeded", []string{"stamped=RelayAdmissionInternal", "nil", "stamped:relayDispositionForInputError", "nil"}},
		{"da_admission.go", "validateDACandidate", []string{"errDARelayImageIncompatible", terminal, "err", "nil"}},
	} {
		function := declaredFunctions(row.path)[row.name]
		if function == nil {
			t.Fatalf("%s:%s missing", row.path, row.name)
		}
		if got := returnShapes(function); !slices.Equal(got, row.want) {
			t.Fatalf("%s:%s error returns=%v, want %v", row.path, row.name, got, row.want)
		}
	}
	// CLOSED SET: the touched sites name only dispositions relay_admission.go declares.
	declared := map[string]bool{}
	relay, err := parser.ParseFile(token.NewFileSet(), "relay_admission.go", nil, parser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parse relay_admission.go: %v", err)
	}
	ast.Inspect(relay, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.TypeSpec:
			declared[node.Name.Name] = true
		case *ast.ValueSpec:
			for _, name := range node.Names {
				declared[name.Name] = true
			}
		}
		return true
	})
	for _, path := range []string{"mempool.go", "mempolicy_helpers.go", "da_admission.go", "da_relay_owner.go"} {
		file, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
		if err != nil {
			t.Fatalf("parse %s: %v", path, err)
		}
		ast.Inspect(file, func(node ast.Node) bool {
			if identifier, ok := node.(*ast.Ident); ok && strings.HasPrefix(identifier.Name, "RelayAdmission") && !declared[identifier.Name] {
				t.Fatalf("%s names undeclared disposition %s", path, identifier.Name)
			}
			return true
		})
	}
	if !declared["RelayAdmissionDisposition"] || !declared["RelayAdmissionUnavailable"] {
		t.Fatalf("disposition declarations were not collected: %v", declared)
	}
	// OWNED CALLERS: remote, both local arms and detached-reorg ingress are the only
	// AdmitDA selectors over every non-test Go source.
	refs := productionReferenceCensus(t, "AdmitDA", "ClaimDARelayState", "NewPeerDAProvenance", "LocalDAProvenance", "DetachedReorgDAProvenance")
	require(t, reflect.DeepEqual(refs, map[string][]string{"AdmitDA": {"AdmitLocalDA", "admitDetachedReorgDA", "announceLocalDA", "handleRelayDATx"}, "ClaimDARelayState": {"NewService"}, "NewPeerDAProvenance": {"remoteDAProvenance"}, "LocalDAProvenance": {"AdmitLocalDA", "announceLocalDA"}, "DetachedReorgDAProvenance": {"admitDetachedReorgDA"}}), "production references=%v", refs)
	newService, detached := declaredFunctions("p2p/service.go")["NewService"], declaredFunctions("p2p/da_relay_ingest.go")["admitDetachedReorgDA"]
	if newService == nil || detached == nil {
		t.Fatal("detached admission binding functions missing")
	}
	storedRelays, ownerCalls, serviceAt := 0, 0, token.NoPos
	writes, identifiers := map[string]int{}, map[ast.Expr]string{}
	var claimCall *ast.CallExpr
	ast.Inspect(newService.Body, func(node ast.Node) bool {
		switch node.(type) {
		case *ast.DeferStmt, *ast.GoStmt:
			t.Fatal("reorg claim binding mismatch: deferred or concurrent initialization")
		}
		if assign, ok := node.(*ast.AssignStmt); ok {
			for _, left := range assign.Lhs {
				name := daNonReplaySelector(left)
				writes[name]++
				if !slices.Contains([]string{"service", "expectedRelay"}, name) {
					continue
				}
				require(t, assign.Tok == token.DEFINE && len(assign.Lhs) == 1 && len(assign.Rhs) == 1, "reorg claim binding mismatch: assignment to %s", name)
				if name == "expectedRelay" {
					getter, ok := ast.Unparen(assign.Rhs[0]).(*ast.CallExpr)
					require(t, ok && calleeName(getter) == "DARelayState" && len(getter.Args) == 0, "reorg claim binding mismatch: expected relay getter")
					continue
				}
				serviceAt = assign.Pos()
				address, ok := ast.Unparen(assign.Rhs[0]).(*ast.UnaryExpr)
				require(t, ok && address.Op == token.AND, "reorg claim binding mismatch: service construction")
				literal, ok := ast.Unparen(address.X).(*ast.CompositeLit)
				require(t, ok, "reorg claim binding mismatch: service literal")
				identifiers[literal.Type] = "Service"
				for _, element := range literal.Elts {
					field, ok := element.(*ast.KeyValueExpr)
					require(t, ok, "reorg claim binding mismatch: unkeyed service field")
					if daNonReplaySelector(field.Key) == "daRelay" {
						identifiers[field.Value] = "expectedRelay"
						storedRelays++
					}
				}
			}
		}
		if call, ok := node.(*ast.CallExpr); ok && calleeName(call) == "ClaimDARelayState" {
			claimCall = call
			require(t, daNonReplaySelector(call.Fun) == "cfg.SyncEngine.ClaimDARelayState", "reorg claim binding mismatch: receiver")
			require(t, len(call.Args) == 2, "NewService detached claim argument count=%d", len(call.Args))
			second, secondOK := call.Args[1].(*ast.SelectorExpr)
			require(t, secondOK && second.Sel.Name == "admitDetachedReorgDA", "reorg claim binding mismatch: callback is %T", call.Args[1])
			identifiers[call.Args[0]], identifiers[second.X] = "expectedRelay", "service"
		}
		return true
	})
	ast.Inspect(detached.Body, func(node ast.Node) bool {
		if call, ok := node.(*ast.CallExpr); ok && calleeName(call) == "AdmitDA" {
			ownerCalls++
			require(t, len(call.Args) == 2, "detached admission owner argument count=%d", len(call.Args))
			provenance, provenanceOK := call.Args[1].(*ast.CallExpr)
			require(t, provenanceOK && calleeName(provenance) == "DetachedReorgDAProvenance", "detached admission owner arguments=%#v", call.Args)
			identifiers[call.Args[0]] = "txBytes"
		}
		return true
	})
	tail := newService.Body.List
	require(t, len(tail) >= 3 && tail[len(tail)-3].Pos() == serviceAt, "reorg claim binding mismatch: construction is not immediately before claim")
	require(t, writes["service"] == 1 && writes["expectedRelay"] == 1 && writes["service.daRelay"] == 0, "reorg claim binding mismatch: writes=%v", writes)
	claimIf, ifOK := tail[len(tail)-2].(*ast.IfStmt)
	require(t, ifOK && claimIf.Else == nil && len(claimIf.Body.List) == 1, "reorg claim binding mismatch: claim statement shape")
	init, initOK := claimIf.Init.(*ast.AssignStmt)
	require(t, initOK && init.Tok == token.DEFINE && len(init.Lhs) == 2 && len(init.Rhs) == 1 && init.Rhs[0] == claimCall, "reorg claim binding mismatch: claim initializer")
	condition, conditionOK := claimIf.Cond.(*ast.BinaryExpr)
	require(t, conditionOK && condition.Op == token.NEQ, "reorg claim binding mismatch: claim condition")
	identifiers[init.Lhs[0]], identifiers[init.Lhs[1]], identifiers[condition.X], identifiers[condition.Y] = "_", "err", "err", "nil"
	for i, statement := range []ast.Stmt{claimIf.Body.List[0], tail[len(tail)-1]} {
		returned, ok := statement.(*ast.ReturnStmt)
		require(t, ok && len(returned.Results) == 2, "reorg claim binding mismatch: return statement shape %d", i)
		want := [2][2]string{{"nil", "err"}, {"service", "nil"}}[i]
		identifiers[returned.Results[0]], identifiers[returned.Results[1]] = want[0], want[1]
	}
	for expression, want := range identifiers {
		name, ok := expression.(*ast.Ident)
		require(t, ok && name.Name == want, "reorg claim binding mismatch: expected identifier %s, got %T", want, expression)
	}
	require(t, storedRelays == 1 && ownerCalls == 1, "detached admission binding stored_relays=%d owner_calls=%d", storedRelays, ownerCalls)
	bindings, directBindings := map[string][]string{}, map[string][]string{}
	serverStarted := false
	run := declaredFunctions("../cmd/rubin-node/main.go")["run"]
	require(t, run != nil, "production run function missing")
	directServerAt := token.NoPos
	for _, statement := range run.Body.List {
		if assign, ok := statement.(*ast.AssignStmt); ok && len(assign.Rhs) == 1 {
			if call, ok := assign.Rhs[0].(*ast.CallExpr); ok && calleeName(call) == "startDevnetRPCServer" {
				directServerAt = statement.Pos()
			}
		}
	}
	require(t, directServerAt != token.NoPos, "direct production startDevnetRPCServer statement missing")
	ast.Inspect(run.Body, func(n ast.Node) bool {
		if call, ok := n.(*ast.CallExpr); ok && calleeName(call) == "startDevnetRPCServer" {
			serverStarted = true
		}
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for _, expression := range assign.Lhs {
			left, ok := expression.(*ast.SelectorExpr)
			if !ok {
				continue
			}
			leftBase, lbok := left.X.(*ast.Ident)
			if !lbok || leftBase.Name != "rpcState" || !slices.Contains([]string{"admitLocalDA", "prefetchLocalDA"}, left.Sel.Name) {
				continue
			}
			rhs := "<invalid>"
			if len(assign.Lhs) == 1 && len(assign.Rhs) == 1 {
				if right, ok := assign.Rhs[0].(*ast.SelectorExpr); ok {
					if base, ok := right.X.(*ast.Ident); ok {
						rhs = base.Name + "." + right.Sel.Name
					}
				}
			}
			if serverStarted {
				rhs = "late:" + rhs
			}
			bindings[left.Sel.Name] = append(bindings[left.Sel.Name], rhs)
			if slices.Contains(run.Body.List, ast.Stmt(assign)) && assign.Pos() < directServerAt {
				directBindings[left.Sel.Name] = append(directBindings[left.Sel.Name], rhs)
			}
		}
		return true
	})
	require(t, serverStarted, "startDevnetRPCServer missing")
	for field, want := range map[string]string{"admitLocalDA": "p2pService.AdmitLocalDA", "prefetchLocalDA": "p2pService.ScheduleLocalDAPrefetch"} {
		got := bindings[field]
		require(t, reflect.DeepEqual(got, []string{want}), "%s bindings=%v, want one %s before server start", field, got, want)
		require(t, reflect.DeepEqual(directBindings[field], []string{want}), "%s direct bindings=%v, want one direct %s before direct server start", field, directBindings[field], want)
	}
}

// productionReferenceCensus walks every non-test Go source under clients/go (no build tags: cgo
// and platform-ignored files included) and returns, per tracked name, the sorted enclosing
// declarations of every identifier use (call, method value, passed value, package-level
// initializer); each name must be declared exactly once.
func productionReferenceCensus(t *testing.T, names ...string) map[string][]string {
	t.Helper()
	refs, declarations := map[string][]string{}, map[string]int{}
	for _, name := range names {
		refs[name] = nil
	}
	note := func(node ast.Node, enclosing string) {
		ast.Inspect(node, func(node ast.Node) bool {
			if ident, ok := node.(*ast.Ident); ok {
				if _, tracked := refs[ident.Name]; tracked {
					refs[ident.Name] = append(refs[ident.Name], enclosing)
				}
			}
			return true
		})
	}
	if err := filepath.Walk("..", func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return err
		}
		file, parseErr := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
		if parseErr != nil {
			return parseErr
		}
		for _, decl := range file.Decls {
			function, ok := decl.(*ast.FuncDecl)
			if !ok {
				note(decl, "package-level "+path)
				continue
			}
			if _, tracked := refs[function.Name.Name]; tracked {
				declarations[function.Name.Name]++
			}
			if function.Body != nil {
				note(function.Body, function.Name.Name)
			}
		}
		return nil
	}); err != nil {
		t.Fatalf("reference census: %v", err)
	}
	for _, name := range names {
		require(t, declarations[name] == 1, "%s: %d declarations, want 1", name, declarations[name])
		sort.Strings(refs[name])
	}
	return refs
}

// require fails the test with the formatted message unless ok holds.
func require(t *testing.T, ok bool, format string, args ...any) {
	t.Helper()
	if !ok {
		t.Fatalf(format, args...)
	}
}

// ownerReadyChunk admits one owner-ready chunk to daID under provenance and returns its tx.
func (f *daNonReplayFixture) ownerReadyChunk(daID [32]byte, index uint16, payload string, provenance daProvenance) daNonReplayTx {
	tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: daID, chunkIndex: index, payload: []byte(payload)})
	f.admit(tx, provenance)
	return tx
}

// ownerReadyCommit admits one owner-ready staged commit (chunkCount chunks, a commitment
// that never matches the retained payloads so the set stays State B) and returns its tx.
func (f *daNonReplayFixture) ownerReadyCommit(daID [32]byte, chunkCount uint16, provenance daProvenance) daNonReplayTx {
	tx := f.signed(daNonReplayTxSpec{kind: 0x01, daID: daID, chunkCount: chunkCount, commitment: [32]byte{0x9c, daID[0]}, commitmentOutputs: 1})
	f.admit(tx, provenance)
	return tx
}

func (f *daNonReplayFixture) setOwnerReadyTTL(daID [32]byte, ttl uint64) {
	f.mutateRelay(func(s *DARelayState) {
		mutateOwnerReadyRecord(s, daID, func(r *daRelaySetRecord) { r.ttlBlocksRemaining = ttl })
	})
}

func ownerReadyClaimGone(t *testing.T, owner *PendingOutpointOwner, token PendingOutpointToken, inputs []consensus.Outpoint) {
	t.Helper()
	if owner.byToken[token] != nil {
		t.Fatalf("claim %+v survived removal", token)
	}
	for _, input := range inputs {
		if row, present := owner.byOutpoint[input]; present && row.token == token {
			t.Fatalf("outpoint %+v still claimed by released token %+v", input, token)
		}
	}
}

func ownerReadyClaimLive(t *testing.T, owner *PendingOutpointOwner, token PendingOutpointToken) {
	t.Helper()
	if claim := owner.byToken[token]; claim == nil || !claim.finalized {
		t.Fatalf("claim %+v not live: %+v", token, claim)
	}
}

// mutateOwnerReadyRecord edits one resident record's own scalars and stores it back, since a
// map value is not addressable. The caller holds the relay lock.
func mutateOwnerReadyRecord(s *DARelayState, daID [32]byte, edit func(*daRelaySetRecord)) {
	record := s.sets[daID]
	edit(&record)
	s.sets[daID] = record
}

// ownerReadyDropRelease is the PEER selector under the quota identity every fixture below gives
// the members that arm may release.
func ownerReadyDropRelease(s *DARelayState) error { return s.releaseOwnerReadyPeerQuota("drop") }

// requireOwnerReadySentinel runs one selector and requires the EXACT sentinel identity, never a
// wrapped one, with both complete images unchanged.
func requireOwnerReadySentinel(t *testing.T, f *daNonReplayFixture, run func(*DARelayState) error, want error, label string) {
	t.Helper()
	before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	if err := run(f.relay); err != want { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
		t.Fatalf("%s: err=%v, want %v", label, err, want)
	}
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
}

// requireOwnerReadyTerminal is the same for the canonical retained-DA terminal class. A nonempty
// detail must appear in the message, so a row cannot pass on another arm's refusal of its image.
func requireOwnerReadyTerminal(t *testing.T, f *daNonReplayFixture, run func(*DARelayState) error, detail, label string) {
	t.Helper()
	if detail == "" {
		t.Fatalf("%s: strings.Contains accepts the empty detail, so a row must name its own arm's evidence", label)
	}
	before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
	var terminal *canonicalDATerminalError
	if err := run(f.relay); !errors.As(err, &terminal) || !strings.Contains(err.Error(), detail) {
		t.Fatalf("%s: err=%v, want canonical retained-DA terminal naming %q", label, err, detail)
	}
	requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
}

// ownerReadyEditOwner edits the shared claim domain under the owner lock the removal path takes.
func ownerReadyEditOwner(f *daNonReplayFixture, edit func(*PendingOutpointOwner)) {
	owner := f.mp.pendingOutpoints
	owner.mu.Lock()
	defer owner.mu.Unlock()
	edit(owner)
}

func ownerReadyRecordAbsent(t *testing.T, view daRelayStateView, daID [32]byte, txids ...[32]byte) {
	t.Helper()
	if _, present := view.sets[daID]; present {
		t.Fatalf("record %x still present", daID)
	}
	if _, present := view.daIDBytes[daID]; present {
		t.Fatalf("da_id bytes for %x survived removal", daID)
	}
	if _, present := view.prefetchIndexes[daID]; present {
		t.Fatalf("prefetch reservation for %x survived removal", daID)
	}
	// releaseSet owns BOTH prefetch maps, so the expiry row is its own assertion.
	if _, present := view.prefetchExpires[daID]; present {
		t.Fatalf("prefetch expiry for %x survived removal", daID)
	}
	for _, txid := range txids {
		if _, present := view.locators[txid]; present {
			t.Fatalf("locator %x survived removal", txid)
		}
	}
}

// requireOwnerReadyPeerCharges pins what every quota key still HOLDS after a cleanup ran: the
// per-peer counters equal the charge the SURVIVING members imply, key for key, so a released key
// whose last member left is ABSENT rather than zero and a key whose commit survived still carries
// that commit's bytes. Every published record is billed: an image carrying a COMPLETE_SET is
// terminal before publication, so no surviving view holds one.
func requireOwnerReadyPeerCharges(t *testing.T, view daRelayStateView) {
	t.Helper()
	want := map[string]uint64{}
	for _, record := range view.sets {
		accounting, err := record.ownerReadyAccounting()
		if err != nil {
			t.Fatalf("surviving record %x accounting: %v", record.daID, err)
		}
		for key, charge := range accounting.peerBytes {
			want[key] += charge
		}
	}
	if !maps.Equal(want, view.peerBytes) {
		t.Fatalf("per-peer charge: surviving members imply %+v, state holds %+v", want, view.peerBytes)
	}
}

// frozenD00ProducerDisposition reads one case's expected result.producer_disposition
// from the frozen artifact, the inert authority the correspondence below is driven by.
func frozenD00ProducerDisposition(t *testing.T, caseID string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "..", "conformance", "fixtures", "protocol", "da_admission_expected_v1.json"))
	require(t, err == nil, "read frozen D00 authority: %v", err)
	var artifact struct {
		Cases []struct {
			ID     string         `json:"id"`
			Expect map[string]any `json:"expect"`
		} `json:"cases"`
	}
	require(t, json.Unmarshal(raw, &artifact) == nil, "decode frozen D00 authority")
	for _, row := range artifact.Cases {
		if result, _ := row.Expect["result"].(map[string]any); row.ID == caseID && result["producer_disposition"] != nil {
			return result["producer_disposition"].(string)
		}
	}
	t.Fatalf("frozen row %s is absent or carries no producer disposition", caseID)
	return ""
}

// TestRemoteD00InternalObservationCorrespondence maps the five D00 IDs no public P2P input can
// corrupt onto their existing internal carriers (run as subtests), then drives each row's exact
// image through the public AdmitDA and compares the producer disposition with the artifact's.
func TestRemoteD00InternalObservationCorrespondence(t *testing.T) {
	t.Run("TestAdmitDAOwnerObservationPrecedesCandidateIntegrity", TestAdmitDAOwnerObservationPrecedesCandidateIntegrity)
	t.Run("TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict", TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict)
	source, err := os.ReadFile("da_relay_owner_test.go")
	require(t, err == nil, "read carrier source: %v", err)
	producer := map[RelayAdmissionDisposition]string{RelayAdmissionUnavailable: "UNAVAILABLE", RelayAdmissionInternal: "INTERNAL"}
	relayMaps := func(f *daNonReplayFixture, _ daNonReplayTx) { f.mutateRelay(func(s *DARelayState) { s.sets = nil }) }
	chunk := func(edit func(*daRelayChunk)) func(*daNonReplayFixture, daNonReplayTx) {
		return func(f *daNonReplayFixture, tx daNonReplayTx) {
			f.mutateRelay(func(s *DARelayState) {
				r := s.sets[tx.spec.daID]
				c := r.chunks[0]
				edit(&c)
				r.chunks[0] = c
				s.sets[tx.spec.daID] = r
			})
		}
	}
	for _, row := range []struct {
		id, carrier, subtest string
		corrupt              func(*daNonReplayFixture, daNonReplayTx)
		present, rawMissing  bool // the corrupted record's shape: DANGLING is absent, CORRUPT keeps the record with no raw
	}{
		{"REMOTE_REPLAY_EVIDENCE_UNAVAILABLE", "TestAdmitDAOwnerObservationPrecedesCandidateIntegrity", "zero CORE_DA_COMMIT outputs unavailable", relayMaps, false, false},
		{"REMOTE_REPLAY_EVIDENCE_UNSTABLE", "TestAdmitDAOwnerObservationPrecedesCandidateIntegrity", "owner context stable tip mismatch wins", func(f *daNonReplayFixture, tx daNonReplayTx) {
			relayMaps(f, tx)
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { o.stableTip.Height++ })
		}, false, false},
		{"REMOTE_REPLAY_EVIDENCE_DANGLING", "TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict", "dangling locator", func(f *daNonReplayFixture, tx daNonReplayTx) {
			f.mutateRelay(func(s *DARelayState) { delete(s.sets, tx.spec.daID) })
		}, false, false},
		{"REMOTE_REPLAY_EVIDENCE_CORRUPT", "TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict", "missing retained raw", chunk(func(c *daRelayChunk) { c.txBytes = nil }), true, true},
		{"REMOTE_REPLAY_EVIDENCE_MISMATCH", "TestReplayClassificationValidatesTheObservationBeforeTheExactVerdict", "indexed member txid", chunk(func(c *daRelayChunk) { c.member.txid[0] ^= 1 }), true, false},
	} {
		t.Run(row.id, func(t *testing.T) {
			require(t, bytes.Contains(source, []byte("func "+row.carrier+"(")) && bytes.Contains(source, []byte(`"`+row.subtest+`"`)), "carrier %s subtest %q is not in this file", row.carrier, row.subtest)
			f := newDANonReplayFixture(t, 1)
			tx := f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xd0, byte(len(row.id))}, payload: []byte(row.id)})
			f.admit(tx, daNonReplayPeer("resident"))
			row.corrupt(f, tx)
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			record, present := before.sets[tx.spec.daID]
			require(t, present == row.present && (!present || (record.chunks[0].txBytes == nil) == row.rawMissing), "%s: corrupted record present=%v (want %v) raw missing=%v (want %v)", row.id, present, row.present, present && record.chunks[0].txBytes == nil, row.rawMissing)
			got, err := f.relay.AdmitDA(tx.raw, publicPeer(t, row.id))
			want := frozenD00ProducerDisposition(t, row.id)
			require(t, got == DAAdmissionResult{} && producer[relayDispositionOf(err)] == want, "%s: AdmitDA=(%+v,%v) disposition=%v, want zero result and frozen producer %s", row.id, got, err, relayDispositionOf(err), want)
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		})
	}
}

// daOwnerFileFuncs parses one source in this package and indexes its FuncDecls by name.
func daOwnerFileFuncs(t *testing.T, path string) map[string]*ast.FuncDecl {
	t.Helper()
	file, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	functions := map[string]*ast.FuncDecl{}
	for _, declaration := range file.Decls {
		if function, ok := declaration.(*ast.FuncDecl); ok {
			functions[function.Name.Name] = function
		}
	}
	return functions
}

// ownerReadyRemovalSelectors drives one row through both owner-ready removal roots (live behind the exported wrappers).
var ownerReadyRemovalSelectors = []struct {
	name string
	run  func(*DARelayState) error
}{
	{"ttl tick", (*DARelayState).advanceOwnerReadyTTL},
	{"peer release", ownerReadyDropRelease},
}

func TestOwnerReadyRemovalPeerAndTTLSelectors(t *testing.T) {
	t.Run("peer state A whole record", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xd0}
		tx := f.ownerReadyChunk(daID, 0, "drop-a", daNonReplayPeer("drop"))
		f.mutateRelay(func(s *DARelayState) { s.prefetch.indexes = map[[32]byte]map[uint16]string{daID: {1: "peer"}} })
		before := daRelayStateSnapshot(f.relay)
		token := before.sets[daID].chunks[0].member.token
		if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
			t.Fatalf("release: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		ownerReadyRecordAbsent(t, after, daID, tx.txid)
		if len(after.sets) != 0 || len(after.locators) != 0 || after.orphanBytes != 0 || len(after.peerBytes) != 0 || len(after.daIDBytes) != 0 {
			t.Fatalf("residual image after whole removal: %+v", after)
		}
		ownerReadyClaimGone(t, cloneDAAdmissionOwner(f.mp.pendingOutpoints), token, tx.inputs)
	})
	t.Run("peer state A partial keeps non-matching members", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 3), [32]byte{0xd1}
		drop0 := f.ownerReadyChunk(daID, 0, "d0", daNonReplayPeer("drop"))
		keep := f.ownerReadyChunk(daID, 1, "k1", LocalDAProvenance())
		drop2 := f.ownerReadyChunk(daID, 2, "d2", daNonReplayPeer("drop"))
		var liveBefore, liveAfter daRelaySetRecord
		var keptBefore daRelayChunk // a value copy: an in-place edit of the shared live map cannot reach it
		f.mutateRelay(func(s *DARelayState) {
			s.prefetch.indexes = map[[32]byte]map[uint16]string{daID: {3: "peer"}}
			liveBefore = s.sets[daID]
			keptBefore = liveBefore.chunks[1]
		})
		before := daRelayStateSnapshot(f.relay)
		dropToken0, keepToken, dropToken2 := before.sets[daID].chunks[0].member.token, before.sets[daID].chunks[1].member.token, before.sets[daID].chunks[2].member.token
		keptCharge := uint64(len(before.sets[daID].chunks[1].txBytes) + len(before.sets[daID].chunks[1].payload))
		if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
			t.Fatalf("release: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		f.mutateRelay(func(s *DARelayState) { liveAfter = s.sets[daID] })
		// Alias rule: a DISTINCT survivor container, the live one unedited, the kept member's backing shared.
		require(t, reflect.ValueOf(liveAfter.chunks).Pointer() != reflect.ValueOf(liveBefore.chunks).Pointer() && len(liveBefore.chunks) == 3, "partial removal edited the live chunks container in place: before=%d chunks", len(liveBefore.chunks))
		require(t, liveAfter.chunks[1].member == keptBefore.member && &liveAfter.chunks[1].txBytes[0] == &keptBefore.txBytes[0] && &liveAfter.chunks[1].payload[0] == &keptBefore.payload[0], "partial removal copied the surviving member's backing")
		record, ok := after.sets[daID]
		if !ok || len(record.chunks) != 1 || record.state != daRelayStateOrphanChunks || record.ttlBlocksRemaining != before.sets[daID].ttlBlocksRemaining {
			t.Fatalf("survivor record=%+v", record)
		}
		if _, kept := record.chunks[1]; !kept {
			t.Fatalf("kept chunk missing: %+v", record.chunks)
		}
		if record.revision <= before.sets[daID].revision || after.records != record.revision {
			t.Fatalf("revision not minted: record=%d high-water=%d before=%d", record.revision, after.records, before.sets[daID].revision)
		}
		// Partial removal reprices exactly to the kept member and leaves no drop-quota
		// charge, and it retains the still-incomplete record's prefetch reservation.
		if after.orphanBytes != keptCharge || after.daIDBytes[daID] != keptCharge || len(after.peerBytes) != 0 {
			t.Fatalf("partial counters orphan=%d da=%d peer=%+v, want %d", after.orphanBytes, after.daIDBytes[daID], after.peerBytes, keptCharge)
		}
		if _, present := after.prefetchIndexes[daID]; !present {
			t.Fatalf("partial removal released the surviving record's prefetch reservation")
		}
		if _, dropped := after.locators[drop0.txid]; dropped {
			t.Fatalf("dropped locator survived: %x", drop0.txid)
		}
		if after.locators[keep.txid] != (daRelayLocator{daID: daID, kind: daRelayLocatorChunk, chunkIndex: 1}) {
			t.Fatalf("kept locator=%+v", after.locators[keep.txid])
		}
		owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		ownerReadyClaimGone(t, owner, dropToken0, drop0.inputs)
		ownerReadyClaimGone(t, owner, dropToken2, drop2.inputs)
		ownerReadyClaimLive(t, owner, keepToken)
	})
	// F1's PEER arm over the full (matching commit, matching chunk, non-PEER chunk) triple. The
	// released identity is "drop"; "keep" is a PEER identity of a DIFFERENT quota, which this arm
	// never names and which therefore cannot protect a matching commit — only a LOCAL or a
	// DETACHED_REORG member can, so a whole-record removal can release members the caller never
	// named. Every row carries a commit, so each is a State B record.
	for _, row := range []struct {
		name    string
		commit  daProvenance
		chunks  []daProvenance
		whole   bool
		dropped []uint16
	}{
		{name: "a matching commit with no chunk at all removes the whole record", commit: daNonReplayPeer("drop"), whole: true},
		{name: "a foreign-quota PEER sibling does not protect a matching commit", commit: daNonReplayPeer("drop"), chunks: []daProvenance{daNonReplayPeer("keep")}, whole: true},
		{name: "a matching chunk under a LOCAL commit drops the chunk alone", commit: LocalDAProvenance(), chunks: []daProvenance{daNonReplayPeer("drop")}, dropped: []uint16{0}},
		{name: "a matching chunk beside a foreign-quota PEER sibling still removes the whole record", commit: daNonReplayPeer("drop"), chunks: []daProvenance{daNonReplayPeer("drop"), daNonReplayPeer("keep")}, whole: true},
		{name: "a DETACHED_REORG sibling alone protects a matching commit", commit: daNonReplayPeer("drop"), chunks: []daProvenance{DetachedReorgDAProvenance()}},
		{name: "a LOCAL sibling protects a matching commit beside a foreign-quota PEER sibling", commit: daNonReplayPeer("drop"), chunks: []daProvenance{daNonReplayPeer("keep"), LocalDAProvenance()}},
		{name: "a matching chunk under a foreign-quota commit drops the chunk alone", commit: daNonReplayPeer("keep"), chunks: []daProvenance{daNonReplayPeer("drop")}, dropped: []uint16{0}},
		{name: "no matching member beside a LOCAL sibling is a no-op", commit: daNonReplayPeer("keep"), chunks: []daProvenance{LocalDAProvenance()}},
	} {
		t.Run("peer state B triple: "+row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 1+len(row.chunks)), [32]byte{0xf0}
			txs := []daNonReplayTx{f.ownerReadyCommit(daID, 3, row.commit)}
			for index, provenance := range row.chunks {
				txs = append(txs, f.ownerReadyChunk(daID, uint16(index), fmt.Sprintf("q%d", index), provenance))
			}
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			tokens, txids := []PendingOutpointToken{before.sets[daID].commit.member.token}, []([32]byte){}
			for index := range row.chunks {
				tokens = append(tokens, before.sets[daID].chunks[uint16(index)].member.token)
			}
			for _, tx := range txs {
				txids = append(txids, tx.txid)
			}
			if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
				t.Fatalf("release: %v", err)
			}
			if !row.whole && len(row.dropped) == 0 {
				requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
				return
			}
			after, owner := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			requireOwnerReadyPeerCharges(t, after)
			if row.whole {
				ownerReadyRecordAbsent(t, after, daID, txids...)
				for index, token := range tokens {
					ownerReadyClaimGone(t, owner, token, txs[index].inputs)
				}
				return
			}
			record, resident := after.sets[daID]
			if !resident || record.state != daRelayStateStagedCommit || len(record.chunks) != len(row.chunks)-len(row.dropped) {
				t.Fatalf("partial survivor=%+v", record)
			}
			ownerReadyClaimLive(t, owner, tokens[0])
			for index := range row.chunks {
				if slices.Contains(row.dropped, uint16(index)) {
					ownerReadyClaimGone(t, owner, tokens[1+index], txs[1+index].inputs)
					continue
				}
				ownerReadyClaimLive(t, owner, tokens[1+index])
			}
		})
	}
	t.Run("peer state B mixed protects the commit", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 3), [32]byte{0xd3}
		commit := f.ownerReadyCommit(daID, 3, daNonReplayPeer("drop"))
		drop := f.ownerReadyChunk(daID, 0, "m0", daNonReplayPeer("drop"))
		keep := f.ownerReadyChunk(daID, 1, "m1", DetachedReorgDAProvenance())
		before := daRelayStateSnapshot(f.relay)
		commitToken := before.sets[daID].commit.member.token
		dropToken, keepToken := before.sets[daID].chunks[0].member.token, before.sets[daID].chunks[1].member.token
		if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
			t.Fatalf("release: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		record, ok := after.sets[daID]
		if !ok || record.state != daRelayStateStagedCommit || record.commit.member == nil || len(record.chunks) != 1 {
			t.Fatalf("mixed survivor=%+v", record)
		}
		if _, kept := record.chunks[1]; !kept {
			t.Fatalf("protected chunk missing")
		}
		// F2: the released key still HOLDS the protected commit's charge. Every earlier peer row
		// pinned only what LEFT, which is why a commit surviving its own cleanup went unseen.
		requireOwnerReadyPeerCharges(t, after)
		if want := uint64(len(before.sets[daID].commit.txBytes)); after.peerBytes["drop"] != want {
			t.Fatalf("released quota holds %d bytes, want the protected commit's %d", after.peerBytes["drop"], want)
		}
		owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		ownerReadyClaimGone(t, owner, dropToken, drop.inputs)
		ownerReadyClaimLive(t, owner, commitToken)
		ownerReadyClaimLive(t, owner, keepToken)
		if _, dropped := after.locators[drop.txid]; dropped || after.locators[commit.txid].kind != daRelayLocatorCommit || after.locators[keep.txid].chunkIndex != 1 {
			t.Fatalf("mixed locators=%+v", after.locators)
		}
	})
	t.Run("peer empty quota is a no-op", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xd5}
		f.ownerReadyChunk(daID, 0, "n0", daNonReplayPeer("keep"))
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		if err := f.relay.releaseOwnerReadyPeerQuota(""); err != nil {
			t.Fatalf("empty release: %v", err)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
	})
	t.Run("an empty quota identity still runs the whole-image preflight", func(t *testing.T) {
		// A1 keeps the empty key selecting nothing, but the pre-fix early return sat ABOVE the
		// preflight: an empty key was then a silent success over ANY image, malformed included.
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xde}
		f.ownerReadyChunk(daID, 0, "e1", daNonReplayPeer("keep"))
		f.mutateRelay(func(s *DARelayState) {
			record := s.sets[daID]
			record.wireBytes = 1 // owner-ready records pin legacy wireBytes to zero (R1 closed-state)
			s.sets[daID] = record
		})
		requireOwnerReadySentinel(t, f, func(s *DARelayState) error { return s.releaseOwnerReadyPeerQuota("") }, errDARelayImageIncompatible, "empty-key release over a malformed image")
	})
	t.Run("a record hidden from every cached total is still records-authority terminal", func(t *testing.T) {
		// R4 sharpened: deleting only the da_id entry is terminal under EITHER authority, since the
		// residual orphan/peer bytes stop balancing. Erasing hidden's WHOLE contribution leaves the
		// cached domain self-consistent, so a cached-total enumeration would publish touched's
		// removal while a resident record sits outside the accounting; records-authority refuses.
		f := newDANonReplayFixture(t, 2)
		hidden, touched := [32]byte{0xdb}, [32]byte{0xdd}
		f.ownerReadyChunk(hidden, 0, "hidden", daNonReplayPeer("hide"))
		f.ownerReadyChunk(touched, 0, "touched", daNonReplayPeer("drop"))
		f.mutateRelay(func(s *DARelayState) {
			s.orphanBytes -= s.orphanBytesByDAID[hidden]
			delete(s.orphanBytesByDAID, hidden)
			delete(s.orphanBytesByPeerQuotaKey, "hide")
		})
		// The evidence names HIDDEN's own da_id, which is the row's whole claim: the record the
		// cached domain no longer mentions is still walked, and refuses before touched is selected.
		requireOwnerReadyTerminal(t, f, ownerReadyDropRelease, fmt.Sprintf("per-da_id orphan bytes for %x", hidden), "a record hidden from every cached total")
	})
	t.Run("every tick decrements by one and mints one revision per record in da_id order", func(t *testing.T) {
		// TTL boundaries above two (4, 3, 2) plus the exact revision sequence: admission order is
		// deliberately not da_id order, so the pinned arithmetic fails on insertion or map order.
		f := newDANonReplayFixture(t, 3)
		ids := [][32]byte{{0xe7}, {0xe8}, {0xec}}
		for _, i := range []int{2, 0, 1} {
			f.ownerReadyChunk(ids[i], 0, fmt.Sprintf("o%d", i), daNonReplayPeer("keep"))
			f.setOwnerReadyTTL(ids[i], 4)
		}
		for ttl := uint64(4); ttl > 1; ttl-- {
			before := daRelayStateSnapshot(f.relay)
			if err := f.relay.advanceOwnerReadyTTL(); err != nil {
				t.Fatalf("tick at ttl %d: %v", ttl, err)
			}
			after := daRelayStateSnapshot(f.relay)
			for i, daID := range ids {
				if got := after.sets[daID]; got.ttlBlocksRemaining != ttl-1 || got.revision != before.records+uint64(i)+1 {
					t.Fatalf("tick at ttl %d record %x: ttl=%d revision=%d, want ttl=%d revision=%d", ttl, daID, got.ttlBlocksRemaining, got.revision, ttl-1, before.records+uint64(i)+1)
				}
			}
			if after.records != before.records+uint64(len(ids)) {
				t.Fatalf("tick at ttl %d high-water=%d, want %d", ttl, after.records, before.records+uint64(len(ids)))
			}
		}
	})
	// A retained COMPLETE_SET makes the whole image terminal for BOTH selectors, refused in the
	// candidate walk before any selection, victim assembly or publication (RUB-1275
	// coverage_disposition, "R1 for a resident COMPLETE_SET"). The image is a MIXED one whose
	// incomplete record is squarely selectable — "drop" matches its only member and TTL 1 would
	// expire it — and is otherwise closed, so the State C record is the only thing either selector
	// can refuse. Before the ruling this exact image published that removal, which is what these
	// rows kill; the state disjunct they run through is redundant with checkOwnerReadyRecord's
	// two-state allowlist until issue 1118 widens it, so no row can redden the disjunct alone.
	for _, selector := range ownerReadyRemovalSelectors {
		t.Run("a retained complete set is terminal on the "+selector.name, func(t *testing.T) {
			f := newDANonReplayFixture(t, 4)
			incompleteID, completeID := [32]byte{0xd1}, [32]byte{0xdf}
			f.ownerReadyChunk(incompleteID, 0, "m0", daNonReplayPeer("drop"))
			f.setOwnerReadyTTL(incompleteID, 1)
			f.completeReplayPinned(completeID)
			if got := daRelayStateSnapshot(f.relay).sets[completeID]; got.state != daRelayStateCompleteSet {
				t.Fatalf("fixture is not complete: %+v", got)
			}
			requireOwnerReadySentinel(t, f, selector.run, errDARelayImageIncompatible, "a retained complete set on the "+selector.name)
		})
	}
	t.Run("ttl greater than one decrements and mints one revision", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0xd7}
		commit := f.ownerReadyCommit(daID, 3, daNonReplayPeer("keep"))
		chunk := f.ownerReadyChunk(daID, 0, "t0", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(daID, 2)
		var liveBefore, liveAfter daRelaySetRecord
		var chunkBefore daRelayChunk // a value copy: an in-place edit of the shared live map cannot reach it
		f.mutateRelay(func(s *DARelayState) {
			s.prefetch.indexes = map[[32]byte]map[uint16]string{daID: {2: "peer"}}
			liveBefore = s.sets[daID]
			chunkBefore = liveBefore.chunks[0]
		})
		before := daRelayStateSnapshot(f.relay)
		commitToken, chunkToken := before.sets[daID].commit.member.token, before.sets[daID].chunks[0].member.token
		if err := f.relay.advanceOwnerReadyTTL(); err != nil {
			t.Fatalf("ttl tick: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		f.mutateRelay(func(s *DARelayState) { liveAfter = s.sets[daID] })
		record := after.sets[daID]
		if record.ttlBlocksRemaining != 1 || record.state != daRelayStateStagedCommit || record.commit.member == nil || len(record.chunks) != 1 {
			t.Fatalf("decremented record=%+v", record)
		}
		// Alias rule: the ORIGINAL container and every backing kept; locators, accounting, prefetch byte-equal.
		require(t, reflect.ValueOf(liveAfter.chunks).Pointer() == reflect.ValueOf(liveBefore.chunks).Pointer() && liveAfter.commit.member == liveBefore.commit.member && &liveAfter.commit.txBytes[0] == &liveBefore.commit.txBytes[0] && liveAfter.chunks[0].member == chunkBefore.member && &liveAfter.chunks[0].txBytes[0] == &chunkBefore.txBytes[0] && &liveAfter.chunks[0].payload[0] == &chunkBefore.payload[0], "pure TTL decrement copied the chunks container or a member's backing")
		require(t, reflect.DeepEqual(after.locators, before.locators) && after.orphanBytes == before.orphanBytes && reflect.DeepEqual(after.peerBytes, before.peerBytes) && reflect.DeepEqual(after.prefetchIndexes, before.prefetchIndexes), "pure TTL decrement rewrote locators, accounting or prefetch")
		if record.revision <= before.sets[daID].revision || after.records != record.revision {
			t.Fatalf("revision high-water=%d record=%d before=%d", after.records, record.revision, before.sets[daID].revision)
		}
		if after.nextReceivedTime != before.nextReceivedTime {
			t.Fatalf("decrement moved receivedTime high-water: %d != %d", after.nextReceivedTime, before.nextReceivedTime)
		}
		owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		ownerReadyClaimLive(t, owner, commitToken)
		ownerReadyClaimLive(t, owner, chunkToken)
		if after.locators[commit.txid].kind != daRelayLocatorCommit || after.locators[chunk.txid].kind != daRelayLocatorChunk {
			t.Fatalf("decrement dropped a locator: %+v", after.locators)
		}
	})
	t.Run("ttl one expires the whole record with no revision", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xd8}
		tx := f.ownerReadyChunk(daID, 0, "e0", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(daID, 1)
		before := daRelayStateSnapshot(f.relay)
		token := before.sets[daID].chunks[0].member.token
		if err := f.relay.advanceOwnerReadyTTL(); err != nil {
			t.Fatalf("ttl tick: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		ownerReadyRecordAbsent(t, after, daID, tx.txid)
		if after.records != before.records {
			t.Fatalf("whole expiry minted a revision: %d != %d", after.records, before.records)
		}
		ownerReadyClaimGone(t, cloneDAAdmissionOwner(f.mp.pendingOutpoints), token, tx.inputs)
	})
	t.Run("ttl zero fails closed before any change", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xd9}
		f.ownerReadyChunk(daID, 0, "z0", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(daID, 0)
		requireOwnerReadySentinel(t, f, (*DARelayState).advanceOwnerReadyTTL, errDARelayImageIncompatible, "a resident ttl of zero")
	})
	// R1's closed-state clauses over a record for which NEITHER selector projects a member image —
	// the "keep" quota matches nothing for the release, TTL 1 expires the record whole — so only
	// the pre-selection candidate gate can refuse these.
	for _, row := range []struct {
		name    string
		corrupt func(*DARelayState, [32]byte)
	}{
		{"record shape", func(s *DARelayState, daID [32]byte) {
			record := s.sets[daID]
			record.wireBytes = 1 // owner-ready records pin legacy wireBytes to zero
			s.sets[daID] = record
		}},
		{"record state", func(s *DARelayState, daID [32]byte) {
			record := s.sets[daID]
			record.state = daRelayStateCompleteSet + 1 // outside the two owner-ready states, and not State C
			s.sets[daID] = record
		}},
		{"member provenance", func(s *DARelayState, daID [32]byte) { s.sets[daID].chunks[0].member.provenance = DAProvenance{} }},
		{"member identity", func(s *DARelayState, daID [32]byte) { s.sets[daID].chunks[0].member.wtxid = [32]byte{} }},
	} {
		for _, selector := range ownerReadyRemovalSelectors {
			t.Run("a malformed unselected "+row.name+" is terminal before selection on the "+selector.name, func(t *testing.T) {
				f, daID := newDANonReplayFixture(t, 1), [32]byte{0xdd}
				f.ownerReadyChunk(daID, 0, "n0", daNonReplayPeer("keep"))
				f.setOwnerReadyTTL(daID, 1)
				f.mutateRelay(func(s *DARelayState) { row.corrupt(s, daID) })
				requireOwnerReadySentinel(t, f, selector.run, errDARelayImageIncompatible, "a malformed unselected "+row.name+" on the "+selector.name)
			})
		}
	}
	// The activation constraint RUB-678 inherits, one row per selector: a resident LEGACY record is
	// not owner-ready, so it is terminal for the WHOLE image — a relay still staging legacy bytes can
	// neither tick nor release, and the owner-ready record beside it is left untouched.
	for _, selector := range ownerReadyRemovalSelectors {
		t.Run("a resident legacy record is terminal on the "+selector.name, func(t *testing.T) {
			f, ownerReady, legacy := newDANonReplayFixture(t, 1), [32]byte{0xdc}, [32]byte{0xdf}
			f.ownerReadyChunk(ownerReady, 0, "m0", daNonReplayPeer("keep"))
			mustAddDAChunk(t, f.relay, "legacypeer", daRelayTestChunk(legacy, 0, 7))
			requireOwnerReadySentinel(t, f, selector.run, errDARelayImageIncompatible, "a resident legacy record on the "+selector.name)
		})
	}
	t.Run("one tick mixes a whole expiry with a decrement in da_id order", func(t *testing.T) {
		// The one selector shape with no row: a single batch whose per-record arms DIFFER. Ascending
		// da_id reaches the expiry first, and the decrement is the batch's only minted revision.
		// Reversing the two TTLs swaps both per-record outcomes and reddens the row.
		f := newDANonReplayFixture(t, 2)
		expireID, decrementID := [32]byte{0xf1}, [32]byte{0xf2}
		expiring := f.ownerReadyChunk(expireID, 0, "x0", daNonReplayPeer("keep"))
		surviving := f.ownerReadyChunk(decrementID, 0, "s0", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(expireID, 1)
		f.setOwnerReadyTTL(decrementID, 3)
		before := daRelayStateSnapshot(f.relay)
		expiringToken, survivingToken := before.sets[expireID].chunks[0].member.token, before.sets[decrementID].chunks[0].member.token
		if err := f.relay.advanceOwnerReadyTTL(); err != nil {
			t.Fatalf("mixed tick: %v", err)
		}
		after, owner := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		ownerReadyRecordAbsent(t, after, expireID, expiring.txid)
		record := after.sets[decrementID]
		if record.ttlBlocksRemaining != 2 || len(record.chunks) != 1 {
			t.Fatalf("decremented record=%+v, want ttl 2 with its one chunk", record)
		}
		if record.revision != before.records+1 || after.records != record.revision {
			t.Fatalf("mixed batch record revision=%d high-water=%d, want exactly one minted above %d", record.revision, after.records, before.records)
		}
		if after.locators[surviving.txid] != (daRelayLocator{daID: decrementID, kind: daRelayLocatorChunk}) || len(after.locators) != 1 {
			t.Fatalf("mixed batch locators=%+v", after.locators)
		}
		requireOwnerReadyPeerCharges(t, after)
		ownerReadyClaimGone(t, owner, expiringToken, expiring.inputs)
		ownerReadyClaimLive(t, owner, survivingToken)
	})
	// Each row lowers one of the four lifted caps below its live counter and requires the tick
	// to proceed anyway; without the lift the absolute arithmetic would abort the batch.
	for _, row := range []struct {
		name       string
		capAndLive func(*DARelayState, [32]byte) (*uint64, uint64)
	}{
		{"per-da_id", func(s *DARelayState, daID [32]byte) (*uint64, uint64) {
			return &s.caps.orphanPoolPerDAIDBytes, s.orphanBytesByDAID[daID]
		}},
		{"per-peer", func(s *DARelayState, _ [32]byte) (*uint64, uint64) {
			return &s.caps.orphanPoolPerPeerBytes, s.orphanBytesByPeerQuotaKey["over"]
		}},
		{"global pool", func(s *DARelayState, _ [32]byte) (*uint64, uint64) {
			return &s.caps.orphanPoolBytes, s.orphanBytes
		}},
		{"commit overhead", func(s *DARelayState, _ [32]byte) (*uint64, uint64) {
			return &s.caps.orphanCommitOverheadBytes, s.orphanCommitOverheadBytes
		}},
	} {
		t.Run("ttl decrement is projected uncapped above the "+row.name+" cap", func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 2), [32]byte{0xe4}
			f.ownerReadyCommit(daID, 3, daNonReplayPeer("over"))
			f.ownerReadyChunk(daID, 0, "o0", daNonReplayPeer("over"))
			f.setOwnerReadyTTL(daID, 2)
			f.relay.mu.Lock()
			capBound, live := row.capAndLive(f.relay, daID)
			if live == 0 {
				f.relay.mu.Unlock()
				t.Fatalf("%s live counter is 0: the lowered cap would wrap to the maximum and the row would stop exercising the cap arithmetic", row.name)
			}
			*capBound = live - 1
			f.relay.mu.Unlock()
			before := daRelayStateSnapshot(f.relay)
			if err := f.relay.advanceOwnerReadyTTL(); err != nil {
				t.Fatalf("over-cap ttl tick: %v", err)
			}
			after := daRelayStateSnapshot(f.relay)
			record := after.sets[daID]
			if record.ttlBlocksRemaining != 1 || record.revision <= before.sets[daID].revision {
				t.Fatalf("over-cap decrement record=%+v, before revision=%d", record, before.sets[daID].revision)
			}
		})
	}
	t.Run("a whole-record peer removal is projected uncapped above the global pool cap", func(t *testing.T) {
		// The whole-record arm is the second removal-projection site and needs its own row: a
		// whole removal zeroes its own per-da_id bucket, so only a cap the SURVIVING records
		// still exceed can prove the lift reaches this arm too.
		f := newDANonReplayFixture(t, 2)
		dropID, keepID := [32]byte{0xe5}, [32]byte{0xe6}
		drop := f.ownerReadyChunk(dropID, 0, "g0", daNonReplayPeer("drop"))
		f.ownerReadyChunk(keepID, 0, "g1", LocalDAProvenance())
		f.relay.mu.Lock()
		live := f.relay.orphanBytesByDAID[keepID] // the survivor ALONE stays above the cap
		if live == 0 {
			f.relay.mu.Unlock()
			t.Fatal("survivor da_id counter is 0: the lowered cap would wrap to the maximum and the row would stop exercising the cap arithmetic")
		}
		f.relay.caps.orphanPoolBytes = live - 1
		f.relay.mu.Unlock()
		before := daRelayStateSnapshot(f.relay)
		dropToken := before.sets[dropID].chunks[0].member.token
		if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
			t.Fatalf("over-cap whole removal: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		ownerReadyRecordAbsent(t, after, dropID, drop.txid)
		if got := after.sets[keepID]; !reflect.DeepEqual(got, before.sets[keepID]) {
			t.Fatalf("survivor not byte-identical: got=%+v want=%+v", got, before.sets[keepID])
		}
		requireOwnerReadyPeerCharges(t, after)
		ownerReadyClaimGone(t, cloneDAAdmissionOwner(f.mp.pendingOutpoints), dropToken, drop.inputs)
	})
	// A5's third clause: repeating an already absent selection is a no-op. Each selector runs to a
	// SUCCESSFUL whole-record removal first, so the repeat works on the image the first published.
	for _, selector := range ownerReadyRemovalSelectors {
		t.Run("repeating an absent "+selector.name+" selection is a no-op", func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 1), [32]byte{0xc0}
			f.ownerReadyChunk(daID, 0, "a0", daNonReplayPeer("drop"))
			f.setOwnerReadyTTL(daID, 1)
			if err := selector.run(f.relay); err != nil {
				t.Fatalf("first %s: %v", selector.name, err)
			}
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			if err := selector.run(f.relay); err != nil {
				t.Fatalf("repeat %s: %v", selector.name, err)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		})
	}
}

func TestOwnerReadyRemovalIsAtomicWithClaimsAndPrefetch(t *testing.T) {
	t.Run("bound whole removal releases every claim and prefetch row", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 3), [32]byte{0xe0}
		commit := f.ownerReadyCommit(daID, 3, daNonReplayPeer("q"))
		chunk0 := f.ownerReadyChunk(daID, 0, "a0", daNonReplayPeer("q"))
		chunk1 := f.ownerReadyChunk(daID, 1, "a1", daNonReplayPeer("q"))
		f.mutateRelay(func(s *DARelayState) {
			s.prefetch.indexes = map[[32]byte]map[uint16]string{daID: {2: "peer"}}
			s.prefetch.expires = map[[32]byte]time.Time{daID: time.Unix(1, 0)}
		})
		before := daRelayStateSnapshot(f.relay)
		tokens := []struct {
			token  PendingOutpointToken
			inputs []consensus.Outpoint
		}{
			{before.sets[daID].commit.member.token, commit.inputs},
			{before.sets[daID].chunks[0].member.token, chunk0.inputs},
			{before.sets[daID].chunks[1].member.token, chunk1.inputs},
		}
		ownerBefore := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		if err := f.relay.releaseOwnerReadyPeerQuota("q"); err != nil {
			t.Fatalf("release: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		ownerReadyRecordAbsent(t, after, daID, commit.txid, chunk0.txid, chunk1.txid)
		if len(after.sets) != 0 || len(after.locators) != 0 || after.orphanBytes != 0 || len(after.peerBytes) != 0 || after.commitBytes != 0 {
			t.Fatalf("residual image: %+v", after)
		}
		owner := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		if len(owner.byToken) != 0 || len(owner.byOutpoint) != 0 {
			t.Fatalf("owner still holds claims: byToken=%d byOutpoint=%d", len(owner.byToken), len(owner.byOutpoint))
		}
		if owner.tokenHighWater != ownerBefore.tokenHighWater {
			t.Fatalf("removal moved the token high-water: %d != %d", owner.tokenHighWater, ownerBefore.tokenHighWater)
		}
		for _, row := range tokens {
			ownerReadyClaimGone(t, owner, row.token, row.inputs)
		}
		if !f.mp.pendingOutpoints.mu.TryLock() {
			t.Fatal("owner mutex leaked")
		}
		f.mp.pendingOutpoints.mu.Unlock()
	})
	t.Run("unbound relay removes DA only and leaves the claim domain", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xe1}
		tx := f.ownerReadyChunk(daID, 0, "u0", daNonReplayPeer("q"))
		ownerBefore := cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		token := daRelayStateSnapshot(f.relay).sets[daID].chunks[0].member.token
		f.mutateRelay(func(s *DARelayState) { s.mempool = nil })
		if err := f.relay.releaseOwnerReadyPeerQuota("q"); err != nil {
			t.Fatalf("unbound release: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		ownerReadyRecordAbsent(t, after, daID, tx.txid)
		ownerReadyClaimLive(t, ownerBefore, token)
		if got := cloneDAAdmissionOwner(f.mp.pendingOutpoints); !reflect.DeepEqual(got, ownerBefore) {
			t.Fatalf("unbound removal touched the owner: got=%+v want=%+v", got, ownerBefore)
		}
	})
	// The owner hold allocates nothing. The proof used to build the image-wide token set, sort the
	// da_id list and materialize a member slice per record INSIDE the hold, so one release or tick
	// blocked every mempool admission for a full retained-image scan; the owner's lock contract
	// (pending_outpoint_owner.go) puts caller scratch before the hold, and BeginCommit
	// (da_admission.go) is the shape. The probe drives the hold's own statements, in production
	// order and in production's BINDING FORMS, over descriptors ownerReadyRetainedBindingMembers
	// built off-lock: dropping the address-taken refusal binding would measure a body production
	// does not have, which is what this probe measured before RUB-1275.
	t.Run("the owner hold allocates nothing", func(t *testing.T) {
		f, first, second := newDANonReplayFixture(t, 4), [32]byte{0xa1}, [32]byte{0xa2}
		f.ownerReadyCommit(first, 3, daNonReplayPeer("q"))
		f.ownerReadyChunk(first, 0, "s0", daNonReplayPeer("q"))
		f.ownerReadyChunk(first, 1, "s1", LocalDAProvenance())
		f.ownerReadyChunk(second, 0, "s2", daNonReplayPeer("q"))
		owner, refusals := f.mp.pendingOutpoints, 0
		var allocs float64
		var refusal error
		// s.mu is held across the whole probe exactly as commitOwnerReadyRemoval holds it.
		f.mutateRelay(func(s *DARelayState) {
			clone := s.cloneForAtomicBatchLocked()
			members, err := ownerReadyRetainedBindingMembers(clone, owner, nil)
			if err != nil {
				t.Fatalf("prepare binding descriptors: %v", err)
			}
			if len(members) != 4 {
				t.Fatalf("probe image carries %d members, want 4", len(members))
			}
			batch, err := prepareDAAdmissionVictims([]DAAdmissionVictim{ownerReadyMemberVictim(clone.sets[second].chunks[0].member)}, [32]byte{})
			if err != nil {
				t.Fatalf("prepare victims: %v", err)
			}
			// Declared above the measured region exactly where production declares it above the
			// lock: production's &failure escapes, so its heap cell is taken off-lock, and the
			// mapper that takes the address runs after the release, outside the hold measured here.
			var failure PendingOutpointError
			var failed bool
			allocs = testing.AllocsPerRun(20, func() {
				owner.mu.Lock()
				if failure, failed = owner.validateDAAdmissionVictimsLocked(batch, PendingOutpointToken{}); failed {
					refusals++
				}
				if err := checkOwnerReadyMemberClaimsLocked(owner, members); err != nil {
					refusals++
				}
				s.publishAtomicBatchLocked(clone)
				owner.mu.Unlock()
			})
			if failed {
				refusal = txAdmitFromPendingOutpointError(&failure) // mapped after the release, as production maps it
			}
		})
		if refusals != 0 {
			t.Fatalf("probe took %d refusals (%v); it must measure the path that reaches publication", refusals, refusal)
		}
		if allocs != 0 {
			t.Fatalf("owner hold allocated %v times per run", allocs)
		}
		t.Logf("owner hold over 2 records and 4 members: %v allocations per run", allocs)
		// The probe names the hold's statements, so pin the hold's call set AND its statement order.
		// A later round adding an allocating call under owner.mu, or a return that does not release
		// it first, must redden here: AllocsPerRun sees neither. dropClaimLocked is the one call the
		// probe omits — it mutates, so it cannot be repeated — and it only reads byToken/byOutpoint
		// and deletes from them. txAdmitFromPendingOutpointError is NOT in the set and must not be:
		// production releases owner.mu and only then maps the victim refusal, the shape both
		// BeginCommit bodies use (da_admission.go). Every branch under the hold must therefore be an
		// exit — release, then return — so a branch that instead falls back into the hold reddens
		// here rather than silently outgrowing the flat walk that models it.
		body := daOwnerFileFuncs(t, "da_relay_mutation.go")["commitOwnerReadyRemovalClaimsLocked"].Body
		held, offLock, inHold := false, map[string]bool{}, map[string]bool{}
		names := func(node ast.Node, skip ast.Node, into map[string]bool) {
			ast.Inspect(node, func(inner ast.Node) bool {
				switch inner := inner.(type) {
				case *ast.CallExpr:
					into[daNonReplaySelector(inner.Fun)] = true
				case *ast.ValueSpec:
					into[inner.Names[0].Name] = true
				}
				return inner != skip
			})
		}
		for index, statement := range body.List {
			branch, isBranch := statement.(*ast.IfStmt)
			switch {
			case daNonReplayCall(statement, "owner.mu.Lock", ""):
				held = true
			case daNonReplayCall(statement, "owner.mu.Unlock", ""):
				// The function returns error, so Go's terminating-statement rule guarantees a
				// statement after this release; it must be the return the release guards.
				held = false
				if _, returns := body.List[index+1].(*ast.ReturnStmt); !returns {
					t.Fatalf("the release at statement %d does not immediately precede a return", index)
				}
			case !held:
				names(statement, nil, offLock)
			case isBranch:
				names(branch, branch.Body, inHold)
				if len(branch.Body.List) != 2 || branch.Else != nil || !daNonReplayCall(branch.Body.List[0], "owner.mu.Unlock", "") {
					t.Fatalf("the branch at statement %d does not release owner.mu as its first act", index)
				}
				if _, returns := branch.Body.List[1].(*ast.ReturnStmt); !returns {
					t.Fatalf("the branch at statement %d releases owner.mu without returning", index)
				}
			default:
				names(statement, nil, inHold)
			}
		}
		if held {
			t.Fatal("commitOwnerReadyRemovalClaimsLocked falls through with owner.mu still held")
		}
		if !offLock["failure"] {
			t.Fatal("failure is not declared above the hold: &failure escapes, so the hold takes its heap cell")
		}
		want := []string{"checkOwnerReadyMemberClaimsLocked", "owner.dropClaimLocked", "owner.validateDAAdmissionVictimsLocked", "s.publishAtomicBatchLocked"}
		if got := slices.Sorted(maps.Keys(inHold)); !slices.Equal(got, want) {
			t.Fatalf("owner hold calls %v, want %v", got, want)
		}
		// AllocsPerRun measures the closure, not the hold, so the closure must BE the hold: the same
		// calls, minus dropClaimLocked. The lock and the release delimit the hold, so neither is a
		// member of either set. The walk is scoped to THIS subtest, because the refusal receipt
		// below measures three closures of its own that are not the hold.
		var probe ast.Node
		ast.Inspect(daOwnerFileFuncs(t, "da_relay_owner_test.go")["TestOwnerReadyRemovalIsAtomicWithClaimsAndPrefetch"].Body, func(node ast.Node) bool {
			call, ok := node.(*ast.CallExpr)
			if !ok || daNonReplaySelector(call.Fun) != "t.Run" || len(call.Args) != 2 {
				return true
			}
			if name, ok := call.Args[0].(*ast.BasicLit); ok && strings.Contains(name.Value, "the owner hold allocates nothing") {
				probe = call.Args[1]
			}
			return true
		})
		if probe == nil {
			t.Fatal("the probe subtest is no longer named 'the owner hold allocates nothing'")
		}
		measured := map[string]bool{}
		ast.Inspect(probe, func(node ast.Node) bool {
			call, ok := node.(*ast.CallExpr)
			if !ok || daNonReplaySelector(call.Fun) != "testing.AllocsPerRun" || len(call.Args) != 2 {
				return true
			}
			ast.Inspect(call.Args[1], func(inner ast.Node) bool {
				if probed, ok := inner.(*ast.CallExpr); ok {
					measured[daNonReplaySelector(probed.Fun)] = true
				}
				return true
			})
			return false
		})
		delete(measured, "owner.mu.Lock")
		delete(measured, "owner.mu.Unlock")
		mirror := slices.DeleteFunc(slices.Clone(want), func(name string) bool { return name == "owner.dropClaimLocked" })
		if got := slices.Sorted(maps.Keys(measured)); !slices.Equal(got, mirror) {
			t.Fatalf("the probe measures %v, want the hold's %v", got, mirror)
		}
	})
	// The REFUSAL path's receipt. The probe above drives the hold's statements on the path that
	// publishes; this row drives the REAL commitOwnerReadyRemovalClaimsLocked on a batch the owner
	// refuses — it mutates nothing on that path, so AllocsPerRun may repeat it — and closes its
	// allocation accounting: the whole refusal costs the off-lock preparation, the refusal
	// descriptor's own heap cell and the mapper, with nothing left over.
	// WHAT THIS ROW CANNOT SEE: placement. Moving txAdmitFromPendingOutpointError back under
	// owner.mu leaves every measured term unchanged and the identity closing, because the same
	// allocations happen in a different place; only the statement-order guard above sees that.
	// What this row does see is an allocation ADDED anywhere on the refusal path, under the hold
	// included: the identity stops closing wherever the new allocation is put.
	t.Run("the refusal path allocates only its off-lock preparation, descriptor and mapper", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 2), [32]byte{0xb1}
		f.ownerReadyChunk(daID, 0, "r0", daNonReplayPeer("q"))
		owner := f.mp.pendingOutpoints
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		var whole, preparation, mapper float64
		var refusal error
		f.mutateRelay(func(s *DARelayState) {
			clone := s.cloneForAtomicBatchLocked()
			victim := ownerReadyMemberVictim(clone.sets[daID].chunks[0].member)
			victim.Token.seq = ^uint64(0) // shape-valid, past the high-water: only the in-hold victim arm refuses it
			victims := []DAAdmissionVictim{victim}
			whole = testing.AllocsPerRun(20, func() {
				refusal = s.commitOwnerReadyRemovalClaimsLocked(owner, clone, victims)
			})
			var batch []DAAdmissionVictim
			var members []*daRelayMemberIdentity
			preparation = testing.AllocsPerRun(20, func() {
				batch, _ = prepareDAAdmissionVictims(victims, [32]byte{})
				members, _ = ownerReadyRetainedBindingMembers(clone, owner, batch)
			})
			if len(batch) != 1 || len(members) != 1 {
				t.Fatalf("preparation yielded batch=%d members=%d, want 1 and 1", len(batch), len(members))
			}
			// The mapper alone, over the descriptor the refusal actually produces. failure is
			// declared outside the closure, so its heap cell is not in this measurement — exactly
			// as production's is not inside the hold.
			failure, failed := owner.validateDAAdmissionVictimsLocked(batch, PendingOutpointToken{})
			if !failed {
				t.Fatal("the receipt batch must be refused by the victim arm")
			}
			mapper = testing.AllocsPerRun(20, func() { refusal = txAdmitFromPendingOutpointError(&failure) })
		})
		var admitErr *TxAdmitError
		if !errors.As(refusal, &admitErr) || admitErr.Message != "invalid DA victim token" {
			t.Fatalf("receipt refusal=%v, want invalid DA victim token", refusal)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		// One cell for the refusal descriptor: &failure escapes, so every call takes one, above
		// the lock. It is the one term with no closure of its own to measure.
		const descriptor = 1
		if whole != preparation+descriptor+mapper {
			t.Fatalf("refusal path allocates %v, want preparation %v + descriptor %d + mapper %v", whole, preparation, descriptor, mapper)
		}
		t.Logf("refusal path: %v allocations = preparation %v + descriptor %d + mapper %v", whole, preparation, descriptor, mapper)
	})
	t.Run("a victim token still held by a surviving member is terminal before publication", func(t *testing.T) {
		// The owner-domain gap: checkDANonReplayShape never reads tokens and
		// prepareDAAdmissionVictims refuses only a duplicate WITHIN the batch, so one token on
		// two members would publish the survivor and drop its claim — a member with no claim.
		// Two arms of the binding proof refuse it: ownerReadyRetainedBindingMembers' closing
		// batch-versus-retained comparison returns the sentinel as bindErr, and under the hold
		// checkOwnerReadyMemberClaimsLocked returns the same sentinel first, because the survivor's
		// aliased token resolves the VICTIM's claim, which names another txid. This row pins the
		// outcome and the unchanged image, not which arm.
		f := newDANonReplayFixture(t, 2)
		dropID, keepID := [32]byte{0xf0}, [32]byte{0xf1}
		f.ownerReadyChunk(dropID, 0, "alias0", daNonReplayPeer("drop"))
		f.ownerReadyChunk(keepID, 0, "alias1", LocalDAProvenance())
		f.mutateRelay(func(s *DARelayState) {
			s.sets[keepID].chunks[0].member.token = s.sets[dropID].chunks[0].member.token
		})
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		aliased := before.sets[dropID].chunks[0].member.token
		if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != errDARelayImageIncompatible { //nolint:errorlint // Exact direct sentinel identity is part of the contract.
			t.Fatalf("aliased-token err=%v, want %v", err, errDARelayImageIncompatible)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		ownerReadyClaimLive(t, cloneDAAdmissionOwner(f.mp.pendingOutpoints), aliased)
	})
	// Victim order shows in the owner's FIRST refusal: a token beyond the high-water and an owner
	// by-outpoint row that no longer names its victim fail differently, so the message names the
	// first victim. The LATER defect must be one the retained-binding preflight cannot see, and
	// the owner's byOutpoint index is exactly that: auditing it against retained members is the
	// widening this slice refuses, so only the victim arm compares it. A defect on the member
	// itself is now terminal in the preflight, before any victim is assembled.
	for _, row := range []struct {
		name    string
		corrupt func(daRelaySetRecord)
		later   func(daRelaySetRecord) *daRelayMemberIdentity
	}{
		{"the commit victim precedes every chunk", func(r daRelaySetRecord) {
			r.commit.member.token.seq = ^uint64(0)
		}, func(r daRelaySetRecord) *daRelayMemberIdentity { return r.chunks[0].member }},
		{"chunk victims ascend by index", func(r daRelaySetRecord) {
			r.chunks[0].member.token.seq = ^uint64(0)
		}, func(r daRelaySetRecord) *daRelayMemberIdentity { return r.chunks[1].member }},
	} {
		t.Run("victim order: "+row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 3), [32]byte{0xf2}
			f.ownerReadyCommit(daID, 3, daNonReplayPeer("drop"))
			f.ownerReadyChunk(daID, 0, "v0", daNonReplayPeer("drop"))
			f.ownerReadyChunk(daID, 1, "v1", daNonReplayPeer("drop"))
			var later *daRelayMemberIdentity
			f.mutateRelay(func(s *DARelayState) {
				row.corrupt(s.sets[daID])
				later = row.later(s.sets[daID])
			})
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { delete(o.byOutpoint, later.inputs[0]) })
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			err := f.relay.releaseOwnerReadyPeerQuota("drop")
			var admitErr *TxAdmitError
			if !errors.As(err, &admitErr) || admitErr.Message != "invalid DA victim token" {
				t.Fatalf("%s err=%v, want invalid DA victim token", row.name, err)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		})
	}
	// H3 PEER PARTIAL arm: the victim-order rows above walk ownerReadyRecordVictims, the WHOLE-record arm.
	// The partial arm has its own sorted walk, in ownerReadyPeerMatches, which only the chunk map's INSERTION
	// order can move, so each order must select the same survivor, mint the same revision and refuse first alike.
	buildOwnerReadyPartial := func(t *testing.T, order []uint16) (*daNonReplayFixture, [32]byte) {
		f, daID := newDANonReplayFixture(t, 5), [32]byte{0xf3}
		for _, index := range order {
			provenance := daNonReplayPeer("drop")
			if index == 4 {
				provenance = LocalDAProvenance() // the one non-matching member keeps the removal partial
			}
			f.ownerReadyChunk(daID, index, fmt.Sprintf("h%d", index), provenance)
		}
		return f, daID
	}
	for _, order := range [][]uint16{{0, 1, 2, 3, 4}, {4, 3, 2, 1, 0}, {2, 4, 0, 3, 1}} {
		t.Run(fmt.Sprintf("peer partial arm ignores chunk insertion order %v", order), func(t *testing.T) {
			f, daID := buildOwnerReadyPartial(t, order)
			before := daRelayStateSnapshot(f.relay)
			if err := f.relay.releaseOwnerReadyPeerQuota("drop"); err != nil {
				t.Fatalf("partial release: %v", err)
			}
			if survivor := daRelayStateSnapshot(f.relay).sets[daID]; len(survivor.chunks) != 1 || survivor.chunks[4].member == nil || survivor.revision != before.records+1 {
				t.Fatalf("survivor=%+v, want only chunk 4 at revision %d", survivor, before.records+1)
			}
			// Victim ORDER shows only in the owner's FIRST refusal, so the second image makes the lowest-index victim fail differently from every later one. As above, the later defect sits in the owner's byOutpoint index, the one victim-arm input the preflight does not audit.
			f, daID = buildOwnerReadyPartial(t, order)
			var later []*daRelayMemberIdentity
			f.mutateRelay(func(s *DARelayState) {
				s.sets[daID].chunks[0].member.token.seq = ^uint64(0)
				for _, index := range []uint16{1, 2, 3} {
					later = append(later, s.sets[daID].chunks[index].member)
				}
			})
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) {
				for _, member := range later {
					delete(o.byOutpoint, member.inputs[0])
				}
			})
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			var admitErr *TxAdmitError
			if err := f.relay.releaseOwnerReadyPeerQuota("drop"); !errors.As(err, &admitErr) || admitErr.Message != "invalid DA victim token" {
				t.Fatalf("first refusal=%v, want chunk 0's invalid DA victim token", err)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		})
	}
	// R3 completeness: every owner-token refusal the contract names fails BEFORE publication, leaving both
	// complete images unchanged. Names sharing one guard are rowed once, not twice: a partial release and a
	// superseded claim are the same by-outpoint comparison in daAdmissionVictimInputsMatchLocked — the index
	// row is gone, or it names a newer token — whose other clause, wrong inputs, the victim-order and
	// valid-prefix rows above already carry.
	for _, row := range []struct {
		name    string
		message string
		corrupt func(*daNonReplayFixture, [2]*daRelayMemberIdentity)
	}{
		{"a zero victim token", "zero DA victim txid or token", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			f.mutateRelay(func(*DARelayState) { m[0].token = PendingOutpointToken{} })
		}},
		{"a token issued by a foreign owner", "invalid DA victim token", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			f.mutateRelay(func(*DARelayState) { m[0].token.owner = &PendingOutpointOwner{} })
		}},
		{"two victims sharing one token", "duplicate DA victim token", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			f.mutateRelay(func(*DARelayState) { m[1].token = m[0].token })
		}},
		{"a claim whose txid moved", "DA victim claim mismatch", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { o.byToken[m[0].token].txid = [32]byte{0xaa} })
		}},
		{"a claim in another domain", "DA victim claim mismatch", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { o.byToken[m[0].token].domain = PendingOutpointStandardMempool })
		}},
		{"a missing claim", "DA victim claim mismatch", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { delete(o.byToken, m[0].token) })
		}},
		{"a partially released or superseded claim", "DA victim input mismatch", func(f *daNonReplayFixture, m [2]*daRelayMemberIdentity) {
			ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { delete(o.byOutpoint, m[0].inputs[0]) })
		}},
	} {
		t.Run("owner refusal: "+row.name, func(t *testing.T) {
			f, dropID, keepID := newDANonReplayFixture(t, 3), [32]byte{0xf4}, [32]byte{0xf5}
			f.ownerReadyChunk(dropID, 0, "r0", daNonReplayPeer("drop"))
			f.ownerReadyChunk(dropID, 1, "r1", daNonReplayPeer("drop"))
			// A third live claim keeps the missing-claim row inside the claim guard instead of
			// validateDAAdmissionVictimsLocked's batch-versus-population bound.
			f.ownerReadyChunk(keepID, 0, "r2", LocalDAProvenance())
			var members [2]*daRelayMemberIdentity
			f.mutateRelay(func(s *DARelayState) {
				members[0], members[1] = s.sets[dropID].chunks[0].member, s.sets[dropID].chunks[1].member
			})
			row.corrupt(f, members)
			before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
			var admitErr *TxAdmitError
			if err := f.relay.releaseOwnerReadyPeerQuota("drop"); !errors.As(err, &admitErr) || admitErr.Message != row.message {
				t.Fatalf("%s err=%v, want %s", row.name, err, row.message)
			}
			requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
		})
	}
	// A bound relay (mempool+chainState set) whose pending-outpoint owner is nil is NOT unbound, and
	// the refusal does not turn on what the batch releases: publishing a victim-removing image
	// without dropping claims would orphan them, and republishing a member-preserving decrement
	// mints a revision no claim domain witnessed. Each batch takes BeginDARemoval's exact refusal
	// and leaves the DA image whole. The zero-victim rows fail against a victim-count-gated refusal.
	for _, row := range []struct {
		name string
		run  func(*DARelayState) error
	}{
		{"a victim-carrying peer release", func(s *DARelayState) error { return s.releaseOwnerReadyPeerQuota("q") }},
		{"a peer release matching nothing", func(s *DARelayState) error { return s.releaseOwnerReadyPeerQuota("other") }},
		{"a member-preserving ttl decrement", (*DARelayState).advanceOwnerReadyTTL},
	} {
		t.Run("a bound relay with a nil owner refuses "+row.name, func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 1), [32]byte{0xe2}
			f.ownerReadyChunk(daID, 0, "b0", daNonReplayPeer("q"))
			f.setOwnerReadyTTL(daID, 2) // above one, so the tick decrements and releases nothing
			before := daRelayStateSnapshot(f.relay)
			f.mutateRelay(func(s *DARelayState) { s.mempool.pendingOutpoints = nil }) // bound, but no claim domain
			var admitErr *TxAdmitError
			if err := row.run(f.relay); !errors.As(err, &admitErr) || admitErr.Message != "nil pending-outpoint owner" {
				t.Fatalf("bound nil-owner %s: err=%v, want nil pending-outpoint owner", row.name, err)
			}
			if got := daRelayStateSnapshot(f.relay); !reflect.DeepEqual(got, before) { //nolint:govet // Complete private state-image equality requires structural comparison.
				t.Fatalf("bound nil-owner %s mutated the DA image: got=%+v want=%+v", row.name, got, before)
			}
		})
	}
	// A mempool with a LIVE claim domain but no chainstate is the third BeginDARemoval arm, and the
	// one publishing would harm: the removed member's finalized claim stays in an owner no retained
	// DA record names any more, so its outpoints never free. Only NewMempoolWithConfig builds a
	// mempool (mempool_stats.go, which refuses a nil chainstate), so this shape is a hand-built
	// relay today and the arm keeps it that way.
	t.Run("a bound relay with a nil chainstate strands no claim", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0xe3}
		f.ownerReadyChunk(daID, 0, "c0", daNonReplayPeer("q"))
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		token := before.sets[daID].chunks[0].member.token
		f.mutateRelay(func(s *DARelayState) { s.mempool.chainState = nil }) // live owner, no chainstate
		var admitErr *TxAdmitError
		if err := f.relay.releaseOwnerReadyPeerQuota("q"); !errors.As(err, &admitErr) || admitErr.Message != "nil chainstate" {
			t.Fatalf("bound nil-chainstate release: err=%v, want nil chainstate", err)
		}
		ownerReadyClaimLive(t, cloneDAAdmissionOwner(f.mp.pendingOutpoints), token)
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
	})
}

func TestOwnerReadyRemovalFailurePreservesWholeImage(t *testing.T) {
	t.Run("a later victim mismatch publishes nothing", func(t *testing.T) {
		f := newDANonReplayFixture(t, 2)
		early, late := [32]byte{0x01}, [32]byte{0x02}
		earlyTx := f.ownerReadyChunk(early, 0, "early", daNonReplayPeer("drop"))
		f.ownerReadyChunk(late, 0, "late", daNonReplayPeer("drop"))
		// Retire the later record's owner by-outpoint row so the owner victim preflight fails
		// after the earlier record has already been projected onto the private clone. That index
		// is the only victim-arm input the retained-binding preflight does not audit, so it is
		// what keeps a valid prefix REACHABLE at all: a defect on the member itself is terminal
		// before any record is projected. H2's prefetch arm needs a reservation the prefix would
		// RELEASE to be worth asserting: early is a whole record removal, which releases both
		// prefetch rows on the clone, so a published prefix takes them with it.
		var late0 *daRelayMemberIdentity
		f.mutateRelay(func(s *DARelayState) {
			s.prefetch.indexes = map[[32]byte]map[uint16]string{early: {1: "peer"}}
			s.prefetch.expires = map[[32]byte]time.Time{early: time.Unix(1, 0)}
			late0 = s.sets[late].chunks[0].member
		})
		ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { delete(o.byOutpoint, late0.inputs[0]) })
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		err := f.relay.releaseOwnerReadyPeerQuota("drop")
		var admitErr *TxAdmitError
		if !errors.As(err, &admitErr) || admitErr.Message != "DA victim input mismatch" {
			t.Fatalf("victim mismatch err=%v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		if after.prefetchIndexes[early][1] != "peer" || !after.prefetchExpires[early].Equal(time.Unix(1, 0)) {
			t.Fatalf("valid-prefix prefetch rows lost: indexes=%+v expires=%+v", after.prefetchIndexes, after.prefetchExpires)
		}
		if _, present := after.sets[early]; !present {
			t.Fatalf("valid-prefix record %x was dropped by a failed batch", earlyTx.txid)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
	})
	// R1/R4 over the whole IMAGE, one row per cached domain: a stray entry no record implies, a
	// deleted entry a resident record does imply, or a live total that does not balance is a
	// derived-versus-live mismatch, terminal before selection and never repaired. Records are the
	// authority, so a record hidden from a cached total is walked anyway rather than silently
	// skipped (the pre-fix bug). The "keep" rows leave the release matching nothing, so only the
	// preflight can refuse them. The preflight refuses before the per-record projector's own
	// arithmetic would, and neither mutates the clone.
	// detail is the evidence string of the arm THIS row reaches, so no row can pass on another
	// arm's refusal. The six rows reach six distinct messages: the per-record comparison inside
	// canonicalDARecordAccounted, the locator bijection in canonicalDARetainedImageClosed, and
	// four totals across checkAgainstLocked and checkPeerBytesLocked (sync_da_relay.go).
	for _, row := range []struct {
		name    string
		detail  string
		quota   string
		ttl     uint64
		corrupt func(*DARelayState, [32]byte)
	}{
		{name: "a deleted cached da_id entry a resident record implies", detail: "per-da_id orphan bytes for", corrupt: func(s *DARelayState, daID [32]byte) {
			delete(s.orphanBytesByDAID, daID)
		}},
		{name: "an extra cached da_id entry no record backs", detail: "per-da_id orphan bytes: records imply", corrupt: func(s *DARelayState, _ [32]byte) {
			s.orphanBytesByDAID[[32]byte{0xbb}] = 1
		}},
		{name: "an extra locator row no record implies", detail: "retained DA locator index holds", corrupt: func(s *DARelayState, _ [32]byte) {
			s.locators[[32]byte{0xce}] = daRelayLocator{daID: [32]byte{0xcf}, kind: daRelayLocatorCommit}
		}},
		{name: "an extra per-peer entry no record backs", detail: "per-peer orphan bytes: records imply", corrupt: func(s *DARelayState, _ [32]byte) {
			s.orphanBytesByPeerQuotaKey["ghost"] = 1
		}},
		{name: "an orphan-pool total below what the resident record implies", detail: "orphan pool bytes: records imply", corrupt: func(s *DARelayState, _ [32]byte) {
			s.orphanBytes = 0
		}},
		// Every incomplete record pins nothing, so a live pinned counter no record implies is a
		// mismatch over the pinned domain alone.
		{name: "a nonzero pinned pool over an all-incomplete image", detail: "pinned payload bytes: records imply", quota: "keep", ttl: 2, corrupt: func(s *DARelayState, _ [32]byte) {
			s.pinnedPayloadBytes = 999_999
		}},
	} {
		t.Run(row.name+" is terminal before selection", func(t *testing.T) {
			f, incompleteID := newDANonReplayFixture(t, 4), [32]byte{0x03}
			quota := "drop"
			if row.quota != "" {
				quota = row.quota
			}
			f.ownerReadyChunk(incompleteID, 0, "img", daNonReplayPeer(quota))
			if row.ttl != 0 {
				f.setOwnerReadyTTL(incompleteID, row.ttl)
			}
			f.mutateRelay(func(s *DARelayState) { row.corrupt(s, incompleteID) })
			requireOwnerReadyTerminal(t, f, ownerReadyDropRelease, row.detail, row.name)
		})
	}
	// FIRST-ERROR ORDER over an image carrying TWO defects on different axes. The closure is
	// canonicalDARetainedImageClosed, which is RECORD-major: it decides the lower da_id's locator
	// bijection AND its accounting before reading the higher one, so the accounting refusal is the
	// sole result. A closure that walked every record's locators first and every record's
	// accounting second would report the higher da_id's locator refusal instead, and this row's
	// evidence string is what separates the two orders — the earlier two-record row (0xdb, 0xdd)
	// carries one defect, so both orders answer it identically. Both records are provenance "keep",
	// leaving the preflight as the only arm either selector can refuse on.
	for _, selector := range ownerReadyRemovalSelectors {
		t.Run("a two-defect image refuses record-major on the "+selector.name, func(t *testing.T) {
			f := newDANonReplayFixture(t, 2)
			accounted, indexed := [32]byte{0x21}, [32]byte{0x22}
			f.ownerReadyChunk(accounted, 0, "acct", daNonReplayPeer("keep"))
			indexedTx := f.ownerReadyChunk(indexed, 0, "loc", daNonReplayPeer("keep"))
			f.mutateRelay(func(s *DARelayState) {
				delete(s.orphanBytesByDAID, accounted) // lower da_id: accounting defect
				row := s.locators[indexedTx.txid]      // higher da_id: locator defect
				row.chunkIndex++                       // still one row, no longer the one the record implies
				s.locators[indexedTx.txid] = row
			})
			requireOwnerReadyTerminal(t, f, selector.run, fmt.Sprintf("per-da_id orphan bytes for %x", accounted),
				"a two-defect image on the "+selector.name)
		})
	}
	t.Run("a valid partial prefix leaves no alias of the clone in live state", func(t *testing.T) {
		// The prefix here SURVIVES partially, so the batch projects a survivor before the later
		// record fails. cloneForAtomicBatchLocked shares each record's chunk map with live, so only
		// the survivor's cloned chunks container keeps the drop off live state when nothing is
		// ever published.
		f := newDANonReplayFixture(t, 3)
		early, late := [32]byte{0x10}, [32]byte{0x11}
		f.ownerReadyChunk(early, 0, "p0", daNonReplayPeer("drop"))
		f.ownerReadyChunk(early, 1, "p1", LocalDAProvenance())
		f.ownerReadyChunk(late, 0, "p2", daNonReplayPeer("drop"))
		var late0 *daRelayMemberIdentity
		f.mutateRelay(func(s *DARelayState) { late0 = s.sets[late].chunks[0].member })
		ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { delete(o.byOutpoint, late0.inputs[0]) })
		before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
		err := f.relay.releaseOwnerReadyPeerQuota("drop")
		var admitErr *TxAdmitError
		if !errors.As(err, &admitErr) || admitErr.Message != "DA victim input mismatch" {
			t.Fatalf("partial-prefix err=%v, want DA victim input mismatch", err)
		}
		if got := daRelayStateSnapshot(f.relay).sets[early]; len(got.chunks) != 2 {
			t.Fatalf("projected prefix leaked into live state: chunks=%+v", got.chunks)
		}
		requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
	})
	t.Run("a tick at the revision ceiling fails closed and whole expiry still needs none", func(t *testing.T) {
		f, daID := newDANonReplayFixture(t, 1), [32]byte{0x07}
		f.ownerReadyChunk(daID, 0, "ceiling", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(daID, 2)
		f.mutateRelay(func(s *DARelayState) { s.records = ^uint64(0) })
		sequence := daRelayStateSnapshot(f.relay).nextReceivedTime
		requireOwnerReadySentinel(t, f, (*DARelayState).advanceOwnerReadyTTL, errDARelayArithmeticOverflow, "a tick at the revision ceiling")
		// R5: whole-record deletion requests no revision, so the same ceiling does not block it.
		f.setOwnerReadyTTL(daID, 1)
		if err := f.relay.advanceOwnerReadyTTL(); err != nil {
			t.Fatalf("expiry at the ceiling: %v", err)
		}
		after := daRelayStateSnapshot(f.relay)
		require(t, len(after.sets) == 0 && after.records == ^uint64(0) && after.nextReceivedTime == sequence, "expiry at the ceiling left sets=%d high-water=%d sequence=%d (want %d)", len(after.sets), after.records, after.nextReceivedTime, sequence)
	})
	// One row per clause of ownerReadyRemovalGateFails that checkDANonReplayShape does not carry
	// itself: ttlBlocksRemaining, revision, receivedTime and the locator-row count. The record is
	// provenance "keep", so the "drop" release matches no member and without its own clause the
	// PEER selector returns no victims and republishes the corrupt record on a successful clone —
	// that arm is what makes each row red exactly when its disjunct is removed. The tick, at TTL 2,
	// drives the same image through the decrement arm.
	for _, row := range []struct {
		name    string
		corrupt func(*DARelayState, [32]byte)
	}{
		{"ttl-zero", func(s *DARelayState, daID [32]byte) {
			mutateOwnerReadyRecord(s, daID, func(r *daRelaySetRecord) { r.ttlBlocksRemaining = 0 })
		}},
		{"revision-zero", func(s *DARelayState, daID [32]byte) {
			mutateOwnerReadyRecord(s, daID, func(r *daRelaySetRecord) { r.revision = 0 })
		}},
		{"receivedTime-zero", func(s *DARelayState, daID [32]byte) {
			mutateOwnerReadyRecord(s, daID, func(r *daRelaySetRecord) { r.receivedTime = 0 })
		}},
		// A memberless resident record implies no locator row, no orphan bytes and no peer
		// entry, so the whole-image preflight still closes and only the locator-row clause
		// can refuse it. Its revision and receivedTime sit under both live high-waters.
		{"memberless", func(s *DARelayState, _ [32]byte) {
			s.sets[[32]byte{0x09}] = daRelaySetRecord{daID: [32]byte{0x09}, state: daRelayStateOrphanChunks, revision: 1, receivedTime: 1, ttlBlocksRemaining: 2}
		}},
	} {
		for _, selector := range ownerReadyRemovalSelectors {
			t.Run("a resident "+row.name+" record is terminal on the "+selector.name, func(t *testing.T) {
				f, daID := newDANonReplayFixture(t, 2), [32]byte{0x06}
				f.ownerReadyChunk(daID, 0, "stalled", daNonReplayPeer("keep"))
				f.setOwnerReadyTTL(daID, 2)
				f.mutateRelay(func(s *DARelayState) { row.corrupt(s, daID) })
				requireOwnerReadySentinel(t, f, selector.run, errDARelayImageIncompatible, "a resident "+row.name+" record on the "+selector.name)
			})
		}
	}
	// Each defect below passes the weaker checkOwnerReadyRecord and is invisible to the
	// accounting arm — an incomplete record pins no payload, so pinnedPayloadAccountingBytes
	// never reads payloadBytes — so only the candidate gate's full checkDANonReplayShape makes
	// it terminal. TTL 2 is the sharpest driver: without the gate the tick decrements and
	// publishes a fresh revision of the malformed record.
	for _, row := range []struct {
		name    string
		corrupt func(*daRelaySetRecord)
	}{
		{"a nonzero payloadBytes", func(r *daRelaySetRecord) { r.payloadBytes = 1 }},
		{"a non-nil replaceableChunks", func(r *daRelaySetRecord) { r.replaceableChunks = map[uint16]bool{} }},
		{"a state A record carrying a commit slot", func(r *daRelaySetRecord) { r.commit.payloadCommitment = [32]byte{0x01} }},
	} {
		t.Run(row.name+" is terminal before any decrement", func(t *testing.T) {
			f, daID := newDANonReplayFixture(t, 1), [32]byte{0x05}
			f.ownerReadyChunk(daID, 0, "shape", daNonReplayPeer("keep"))
			f.setOwnerReadyTTL(daID, 2)
			f.mutateRelay(func(s *DARelayState) { mutateOwnerReadyRecord(s, daID, row.corrupt) })
			requireOwnerReadySentinel(t, f, (*DARelayState).advanceOwnerReadyTTL, errDARelayImageIncompatible, row.name)
		})
	}
	// R1 over the retained BYTES and the scalars they prove — the surface the stored-shape gate
	// cannot reach. Every member of every incomplete record is re-parsed from its own retained
	// bytes, role-checked against the record's claims and bound to its stored identity, inputs and
	// payload cache by the canonical retained validator's own phase 2 (bindRetainedRecord). The
	// record is provenance "keep", so the "drop" release matches no member, and TTL 2, so the tick
	// would otherwise decrement and publish a fresh revision of the corrupt record: only a
	// pre-selection refusal can be red here. Each row also pins the sibling predicate that fired,
	// so no row can pass on some later arm's refusal of the same image.
	retainedBytesImage := func(t *testing.T) (*daNonReplayFixture, [32]byte) {
		f, daID := newDANonReplayFixture(t, 4), [32]byte{0xc3}
		f.ownerReadyCommit(daID, 3, daNonReplayPeer("keep"))
		f.ownerReadyChunk(daID, 0, "y0", daNonReplayPeer("keep"))
		f.setOwnerReadyTTL(daID, 2)
		return f, daID
	}
	setOwnerReadyChunkBytes := func(record daRelaySetRecord, index uint16, txBytes []byte) {
		chunk := record.chunks[index]
		chunk.txBytes = txBytes
		record.chunks[index] = chunk
	}
	for _, row := range []struct {
		name    string
		detail  string
		corrupt func(*daNonReplayFixture, *daRelaySetRecord)
	}{
		{"retained bytes that do not canonically parse", "does not canonically parse", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			setOwnerReadyChunkBytes(*r, 0, []byte{0x01})
		}},
		{"retained bytes carrying a trailing byte", "has trailing bytes", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			setOwnerReadyChunkBytes(*r, 0, append(slices.Clone(r.chunks[0].txBytes), 0x00))
		}},
		{"a commit slot retaining the chunk transaction", "is tx_kind 0x02", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			r.commit.txBytes = slices.Clone(r.chunks[0].txBytes)
		}},
		{"a commit whose stored chunk_count contradicts its bytes", "record holds 2", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			r.commit.chunkCount = 2
		}},
		{"a chunk stored outside the slot its bytes declare", "is stored at index 0 and declares 1", func(f *daNonReplayFixture, r *daRelaySetRecord) {
			setOwnerReadyChunkBytes(*r, 0, f.signed(daNonReplayTxSpec{kind: 0x02, daID: r.daID, chunkIndex: 1, payload: []byte("y0")}).raw)
		}},
		{"a chunk whose bytes declare a foreign da_id", "carries da_id", func(f *daNonReplayFixture, r *daRelaySetRecord) {
			setOwnerReadyChunkBytes(*r, 0, f.signed(daNonReplayTxSpec{kind: 0x02, daID: [32]byte{0xce}, payload: []byte("y0")}).raw)
		}},
		{"a stored txid contradicting the parse", "contradicts its parsed identity", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			r.chunks[0].member.txid[0] ^= 0xff
		}},
		{"stored inputs contradicting the parse", "contradicts its parsed identity", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			member := r.chunks[0].member // the slice may alias the owner's claim, so it is copied before the edit
			member.inputs = append([]consensus.Outpoint(nil), member.inputs...)
			member.inputs[0].Vout++
		}},
		{"a stored payload commitment contradicting the commit's bytes", "contradicts its payload commitment", func(_ *daNonReplayFixture, r *daRelaySetRecord) {
			r.commit.payloadCommitment[0] ^= 0xff
		}},
	} {
		for _, selector := range ownerReadyRemovalSelectors {
			t.Run(row.name+" is terminal before selection on the "+selector.name, func(t *testing.T) {
				f, daID := retainedBytesImage(t)
				f.mutateRelay(func(s *DARelayState) {
					mutateOwnerReadyRecord(s, daID, func(r *daRelaySetRecord) { row.corrupt(f, r) })
				})
				requireOwnerReadyTerminal(t, f, selector.run, row.detail, row.name+" on the "+selector.name)
			})
		}
	}
	// R1/R3 over the RETAINED image. One fixture drives both publication arms: the tick preserves
	// both members and releases none, the "drop" release removes chunk 0 and keeps chunk 1. Chunk 1
	// survives every selection, so a defect placed on it is caught only by a check reading the image
	// the batch is about to publish.
	bindingImage := func(t *testing.T) (*daNonReplayFixture, [32]byte) {
		f, incompleteID := newDANonReplayFixture(t, 5), [32]byte{0xc1}
		f.ownerReadyChunk(incompleteID, 0, "b0", daNonReplayPeer("drop"))
		f.ownerReadyChunk(incompleteID, 1, "b1", LocalDAProvenance())
		f.setOwnerReadyTTL(incompleteID, 2)
		return f, incompleteID
	}
	for _, selector := range ownerReadyRemovalSelectors {
		t.Run("the binding fixture publishes cleanly on the "+selector.name, func(t *testing.T) {
			f, _ := bindingImage(t)
			if err := selector.run(f.relay); err != nil {
				t.Fatalf("uncorrupted binding fixture on the %s: %v", selector.name, err)
			}
		})
	}
	for _, row := range []struct {
		name      string
		canonical bool // refused by the preflight's canonical retained-DA terminal class, not the sentinel
		corrupt   func(*DARelayState, [32]byte)
	}{
		{"a retained member carrying a zero token", false, func(s *DARelayState, incompleteID [32]byte) {
			s.sets[incompleteID].chunks[1].member.token = PendingOutpointToken{}
		}},
		{"a retained member carrying a foreign owner's token", false, func(s *DARelayState, incompleteID [32]byte) {
			s.sets[incompleteID].chunks[1].member.token.owner = &PendingOutpointOwner{}
		}},
		{"two retained members sharing one token", false, func(s *DARelayState, incompleteID [32]byte) {
			s.sets[incompleteID].chunks[1].member.token = s.sets[incompleteID].chunks[0].member.token
		}},
		{"a record stored under a mismatched da_id", true, func(s *DARelayState, incompleteID [32]byte) {
			s.sets[[32]byte{0xcd}] = s.sets[incompleteID]
			delete(s.sets, incompleteID)
		}},
	} {
		for _, selector := range ownerReadyRemovalSelectors {
			t.Run(row.name+" is terminal on the "+selector.name, func(t *testing.T) {
				f, incompleteID := bindingImage(t)
				f.mutateRelay(func(s *DARelayState) { row.corrupt(s, incompleteID) })
				before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
				err := selector.run(f.relay)
				var terminal *canonicalDATerminalError
				if errors.As(err, &terminal) != row.canonical || (!row.canonical && !errors.Is(err, errDARelayImageIncompatible)) {
					t.Fatalf("%s on the %s: err=%v, want terminal with canonical=%v", row.name, selector.name, err, row.canonical)
				}
				requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
			})
		}
	}
	// R3 over the LIVE claim domain: every retained member must resolve a live owner claim that
	// describes it by DA domain, txid, ordered inputs and finalized, the canonical builder's own
	// phase-5 predicate. Chunk 1 SURVIVES both selectors, so it is never a victim and the victim
	// preflight never reads its claim: only the retained-binding proof can refuse these, and
	// without it each row publishes a record whose member has no live claim behind it.
	for _, row := range []struct {
		name string
		edit func(*PendingOutpointOwner, PendingOutpointToken)
	}{
		{"whose live claim is gone", func(o *PendingOutpointOwner, token PendingOutpointToken) {
			delete(o.byToken, token)
		}},
		{"whose claim names another txid", func(o *PendingOutpointOwner, token PendingOutpointToken) {
			o.byToken[token].txid[0] ^= 0xff
		}},
		{"whose claim carries other inputs", func(o *PendingOutpointOwner, token PendingOutpointToken) {
			o.byToken[token].inputs = slices.Clone(o.byToken[token].inputs)
			o.byToken[token].inputs[0].Vout++
		}},
		{"whose claim is not finalized", func(o *PendingOutpointOwner, token PendingOutpointToken) {
			o.byToken[token].finalized = false
		}},
		{"whose claim left the DA domain", func(o *PendingOutpointOwner, token PendingOutpointToken) {
			o.byToken[token].domain = PendingOutpointStandardMempool
		}},
	} {
		for _, selector := range ownerReadyRemovalSelectors {
			t.Run("a surviving incomplete member "+row.name+" is terminal on the "+selector.name, func(t *testing.T) {
				f, incompleteID := bindingImage(t)
				token := daRelayStateSnapshot(f.relay).sets[incompleteID].chunks[1].member.token
				ownerReadyEditOwner(f, func(o *PendingOutpointOwner) { row.edit(o, token) })
				before, ownerBefore := daRelayStateSnapshot(f.relay), cloneDAAdmissionOwner(f.mp.pendingOutpoints)
				if err := selector.run(f.relay); !errors.Is(err, errDARelayImageIncompatible) {
					t.Fatalf("a surviving incomplete member %s on the %s: err=%v, want %v", row.name, selector.name, err, errDARelayImageIncompatible)
				}
				requireDANonReplayUnchanged(t, f.relay, f.mp.pendingOutpoints, before, ownerBefore)
			})
		}
	}
}

func TestOwnerReadyRemovalRemainsDormant(t *testing.T) {
	calleeName := func(call *ast.CallExpr) string {
		switch function := call.Fun.(type) {
		case *ast.Ident:
			return function.Name
		case *ast.SelectorExpr:
			return function.Sel.Name
		}
		return ""
	}
	// OWNED CALLERS: each owner-aware entrypoint is named once, in its wrapper; the legacy roots never.
	refs := productionReferenceCensus(t, "releaseOwnerReadyPeerQuota", "advanceOwnerReadyTTL", "releasePeerQuotaKey", "advanceOrphanTTL", "prepareCanonicalDAImage")
	require(t, reflect.DeepEqual(refs, map[string][]string{"releaseOwnerReadyPeerQuota": {"ReleasePeerQuotaKey"}, "advanceOwnerReadyTTL": {"AdvanceOrphanTTL"}, "releasePeerQuotaKey": nil, "advanceOrphanTTL": nil, "prepareCanonicalDAImage": nil}), "production references=%v", refs)
	// TEETH: `f := s.advanceOwnerReadyTTL` is a bare SelectorExpr with no CallExpr; the identifier
	// census must count it, or a second activation through a method value would pass.
	teeth, parseErr := parser.ParseFile(token.NewFileSet(), "teeth.go", "package node\nfunc wire(s *DARelayState) { f := s.advanceOwnerReadyTTL; _ = f }", parser.SkipObjectResolution)
	if parseErr != nil {
		t.Fatalf("parse teeth fixture: %v", parseErr)
	}
	selectorHits, callHits := 0, 0
	ast.Inspect(teeth, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.SelectorExpr:
			if node.Sel.Name == "advanceOwnerReadyTTL" {
				selectorHits++
			}
		case *ast.CallExpr:
			if calleeName(node) == "advanceOwnerReadyTTL" {
				callHits++
			}
		}
		return true
	})
	if selectorHits != 1 || callHits != 0 {
		t.Fatalf("teeth: selector census=%d (want 1), call-only census=%d (want 0)", selectorHits, callHits)
	}
	// SEPARATION: the owner-aware removal path routes only through the owner-ready projector,
	// so none of its functions calls a legacy removal or apply primitive; the legacy exported
	// cleanup names are the owner-aware wrappers since issue 678; the DARemoval guard stays unwired.
	mutationFuncs := daOwnerFileFuncs(t, "da_relay_mutation.go")
	// The censused set is DERIVED from the file, never listed by hand: every FuncDecl whose
	// name carries "ownerready" case-insensitively. Completeness rests on the naming rule the
	// surface is written to — each of its functions is named for the owner-ready record it
	// operates on — so the filter cannot miss a function a later round adds under that rule,
	// the way a literal list silently would. It is a strict SUPERSET of this slice's own
	// additions: it also picks up the pre-existing owner-ready staging predicates in this
	// file, which is the conservative direction.
	legacy := map[string]bool{"removeDASetRecordLocked": true, "applyDASetRecordLocked": true, "advanceOrphanTTLLocked": true, "releasePeerQuotaKeyLocked": true, "releasePeerQuotaKeyRecordLocked": true, "withoutPeerQuotaKey": true, "BeginDARemoval": true}
	var censused []string
	for name := range mutationFuncs {
		if strings.Contains(strings.ToLower(name), "ownerready") {
			censused = append(censused, name)
		}
	}
	slices.Sort(censused) // one failing name per corrupt file, whatever the map order
	for _, name := range censused {
		ast.Inspect(mutationFuncs[name].Body, func(node ast.Node) bool {
			if call, ok := node.(*ast.CallExpr); ok && legacy[calleeName(call)] {
				t.Fatalf("%s calls legacy removal primitive %s", name, calleeName(call))
			}
			return true
		})
	}
	// Fail closed on a derivation that stopped selecting the surface it claims to cover.
	for _, entrypoint := range []string{"releaseOwnerReadyPeerQuota", "advanceOwnerReadyTTL"} {
		if !slices.Contains(censused, entrypoint) {
			t.Fatalf("separation census derived %d functions, none of them entrypoint %s", len(censused), entrypoint)
		}
	}
	t.Logf("separation census covers %d derived owner-ready functions: %v", len(censused), censused)
	// The new whole-record path releases the prefetch reservation the installer skips.
	var wholeRecordCallees []string
	ast.Inspect(mutationFuncs["removeOwnerReadyWholeRecordLocked"].Body, func(node ast.Node) bool {
		if call, ok := node.(*ast.CallExpr); ok {
			wholeRecordCallees = append(wholeRecordCallees, calleeName(call))
		}
		return true
	})
	if !slices.Contains(wholeRecordCallees, "releaseSet") {
		t.Fatal("whole-record removal does not release the prefetch reservation")
	}
	// RECORD-LOCAL WORK: the removal arms and their shared retirement helper never call the global locator traversal, the record deep clone
	// or the Live projector, nor range locators. Locator WRITE SINKS (indexed assignment/IncDec, rebinding, delete, any call taking the map as an argument)
	// are refused only on the pure-TTL path: the tick arm, which reaches `s` solely via s.sets, s.records, the whole-record arm and scanned same-file direct helpers.
	// A bounded shape check, not a proof over arbitrary Go: which rows the retirement arms retire or keep is pinned by the runtime rows (TestAdmitDANonReplayPrunesOutOfRangeClaims, TestOwnerReadyRemovalPeerAndTTLSelectors, the OWNER-READY WRAPPER row below).
	isIdent := func(expr ast.Expr, name string) bool { ident, ok := expr.(*ast.Ident); return ok && ident.Name == name }
	isLocators := func(expr ast.Expr) bool { sel, ok := expr.(*ast.SelectorExpr); return ok && sel.Sel.Name == "locators" }
	locatorSink := func(node ast.Node) string {
		var lhs []ast.Expr
		switch node := node.(type) {
		case *ast.AssignStmt:
			lhs = node.Lhs
		case *ast.IncDecStmt:
			lhs = []ast.Expr{node.X}
		case *ast.CallExpr:
			if len(node.Args) == 2 && isIdent(node.Fun, "delete") && isLocators(node.Args[0]) {
				return "delete"
			}
			if slices.ContainsFunc(node.Args, isLocators) {
				return "call " + calleeName(node)
			}
		}
		for _, expr := range lhs {
			if index, ok := expr.(*ast.IndexExpr); ok && isLocators(index.X) || isLocators(expr) {
				return "assignment"
			}
		}
		return ""
	}
	var scan func(owner string, body *ast.BlockStmt, pureTTL, direct bool)
	scan = func(owner string, body *ast.BlockStmt, pureTTL, direct bool) {
		ast.Inspect(body, func(node ast.Node) bool {
			if kind := locatorSink(node); pureTTL && kind != "" {
				t.Fatalf("%s writes the locator index: %s", owner, kind)
			}
			switch node := node.(type) {
			case *ast.RangeStmt:
				if isLocators(node.X) {
					t.Fatalf("%s ranges over the locator index", owner)
				}
			case *ast.CallExpr:
				if callee := calleeName(node); slices.Contains([]string{"checkRetiredLocatorRowsLocked", "checkDARecordImageLocatorsLocked", "projectDARecordImageLiveLocked", "cloneOwnerReady"}, callee) {
					t.Fatalf("%s calls %s", owner, callee)
				}
				require(t, !pureTTL || !slices.ContainsFunc(node.Args, func(arg ast.Expr) bool { return isIdent(arg, "s") }), "%s hands the relay state to %s", owner, calleeName(node))
			case *ast.SelectorExpr:
				if pureTTL && isIdent(node.X, "s") && !slices.Contains([]string{"sets", "records", "removeOwnerReadyWholeRecordLocked"}, node.Sel.Name) {
					require(t, !direct && mutationFuncs[node.Sel.Name] != nil, "%s reaches s.%s, which no sink scan covers", owner, node.Sel.Name)
					scan(owner+"'s direct helper "+node.Sel.Name, mutationFuncs[node.Sel.Name].Body, true, true)
				}
			}
			return true
		})
	}
	for _, name := range []string{"removeOwnerReadyWholeRecordLocked", "dropOwnerReadyChunksLocked", "tickOwnerReadyTTLRecordLocked", "projectOwnerReadyRetirementLocked"} {
		scan(name, mutationFuncs[name].Body, name == "tickOwnerReadyTTLRecordLocked", false)
	}
	// LEGACY ROOT PIN: the private TTL root still decrements in place and mints NO revision.
	legacyState := newDARelayStateForTest(t, defaultDARelayCaps())
	legacyState.caps.orphanTTLBlocks = 3
	legacyID := daRelayTestID(0x7a)
	mustAddDAChunk(t, legacyState, "legacy", daRelayTestChunk(legacyID, 0, 7))
	legacyState.mu.Lock()
	record := legacyState.sets[legacyID]
	record.ttlBlocksRemaining = 2
	legacyState.sets[legacyID] = record
	legacyState.mu.Unlock()
	_, err := legacyState.advanceOrphanTTL()
	after := daRelayStateSnapshot(legacyState)
	require(t, err == nil && after.sets[legacyID].ttlBlocksRemaining == 1 && after.sets[legacyID].revision == 0 && after.records == 0, "legacy advanceOrphanTTL err=%v record=%+v high-water=%d, want in-place ttl=1 revision=0", err, after.sets[legacyID], after.records)
	// OWNER-READY WRAPPER: AdvanceOrphanTTL ticks once, mints one revision, keeps the container and backing.
	f, daID := newDANonReplayFixture(t, 1), [32]byte{0x7b}
	f.ownerReadyChunk(daID, 0, "wrapped", daNonReplayPeer("keep"))
	f.setOwnerReadyTTL(daID, 3)
	var liveBefore, liveAfter daRelaySetRecord
	var chunkBefore daRelayChunk // a value copy: an in-place edit of the shared live map cannot reach it
	f.mutateRelay(func(s *DARelayState) { liveBefore = s.sets[daID]; chunkBefore = liveBefore.chunks[0] })
	err = f.relay.AdvanceOrphanTTL()
	f.mutateRelay(func(s *DARelayState) { liveAfter = s.sets[daID] })
	require(t, err == nil && liveAfter.ttlBlocksRemaining == 2 && liveAfter.revision == liveBefore.revision+1 && daRelayStateSnapshot(f.relay).records == liveAfter.revision, "owner-ready AdvanceOrphanTTL err=%v ttl=%d revision=%d (before %d)", err, liveAfter.ttlBlocksRemaining, liveAfter.revision, liveBefore.revision)
	require(t, reflect.ValueOf(liveAfter.chunks).Pointer() == reflect.ValueOf(liveBefore.chunks).Pointer() && liveAfter.chunks[0].member == chunkBefore.member && &liveAfter.chunks[0].txBytes[0] == &chunkBefore.txBytes[0] && &liveAfter.chunks[0].payload[0] == &chunkBefore.payload[0], "owner-ready tick copied the chunks container or a member's backing")
}
